window.getAvatarGender = getAvatarGender;
window.faceTextureUrlForGender = faceTextureUrlForGender;


var AZORA_TEMP_DISABLE_AZAFN = true;
function showDisabledFeatureTip(event, btnEl) {
    var tip = document.getElementById("azoraDisabledTip");
    if (!tip) return;
    tip.textContent = "Oops! Looks like this button is disabled!";
    tip.style.display = "block";
    var pad = 12, tw = tip.offsetWidth || 200, th = tip.offsetHeight || 40;
    var br = btnEl ? btnEl.getBoundingClientRect() : null;
    var mx = (event && typeof event.clientX === "number") ? event.clientX : (br ? br.left + br.width / 2 : 40);
    var my = (event && typeof event.clientY === "number") ? event.clientY : (br ? br.top : 40);
    var x = mx + 14, y = my + 14;
    if (br) {
        var left = br.left - pad, right = br.right + pad, top = br.top - pad, bottom = br.bottom + pad;
        var overlaps = !(x + tw < left || x > right || y + th < top || y > bottom);
        if (overlaps) {
            var spaceRight = window.innerWidth - br.right, spaceLeft = br.left, spaceBelow = window.innerHeight - br.bottom, spaceAbove = br.top;
            var best = Math.max(spaceRight, spaceLeft, spaceBelow, spaceAbove);
            if (best === spaceRight) { x = br.right + pad; y = Math.min(Math.max(my - th / 2, 8), window.innerHeight - th - 8); }
            else if (best === spaceLeft) { x = br.left - pad - tw; y = Math.min(Math.max(my - th / 2, 8), window.innerHeight - th - 8); }
            else if (best === spaceBelow) { y = br.bottom + pad; x = Math.min(Math.max(mx - tw / 2, 8), window.innerWidth - tw - 8); }
            else { y = br.top - pad - th; x = Math.min(Math.max(mx - tw / 2, 8), window.innerWidth - tw - 8); }
        }
    }
    x = Math.max(8, Math.min(x, window.innerWidth - tw - 8));
    y = Math.max(8, Math.min(y, window.innerHeight - th - 8));
    tip.style.left = x + "px"; tip.style.top = y + "px";
    clearTimeout(showDisabledFeatureTip._t);
    showDisabledFeatureTip._t = setTimeout(function () { tip.style.display = "none"; }, 2200);
}
function handleDisabledFeatureClick(event, btnEl) {
    if (event) { event.preventDefault(); event.stopPropagation(); }
    showDisabledFeatureTip(event || window.event, btnEl || (event && event.currentTarget));
    return false;
}
window.showDisabledFeatureTip = showDisabledFeatureTip;
window.handleDisabledFeatureClick = handleDisabledFeatureClick;

/* =========================================================
   Safety: Block, Report, Automated Moderation
   ========================================================= */

function getBlockedUsers() {
    try {
        var list = JSON.parse(localStorage.getItem("azoraBlocked") || "[]");
        return Array.isArray(list) ? list : [];
    } catch (e) { return []; }
}

function saveBlockedUsers(list) {
    try { localStorage.setItem("azoraBlocked", JSON.stringify(list || [])); } catch (e) {}
}

function isUserBlocked(username) {
    if (!username) return false;
    var key = String(username).toLowerCase();
    return getBlockedUsers().some(function (u) { return String(u).toLowerCase() === key; });
}

function blockUser(username) {
    if (!username) return;
    var me = (typeof getMyUsername === "function") ? getMyUsername() : null;
    if (me && String(me).toLowerCase() === String(username).toLowerCase()) {
        alert("You cannot block yourself.");
        return;
    }
    if (String(username).toLowerCase() === "azora") {
        alert("You cannot block the official Azora account.");
        return;
    }
    var list = getBlockedUsers();
    if (list.some(function (u) { return String(u).toLowerCase() === String(username).toLowerCase(); })) {
        if (typeof showAzoraToast === "function") showAzoraToast(username + " is already blocked.");
        return;
    }
    if (!confirm("Block " + username + "?\n\nYou will not see their messages in Chat or Norm Games. You can unblock them later from their profile.")) return;
    list.push(username);
    saveBlockedUsers(list);

    // Soft-remove from local friends/following for cleaner UI
    try {
        if (typeof getSocialData === "function" && me) {
            var data = getSocialData();
            var mine = (typeof ensureUserSocial === "function") ? ensureUserSocial(data, me) : (data[me] || {});
            ["friends", "following", "followers", "friendRequests"].forEach(function (k) {
                if (!Array.isArray(mine[k])) return;
                mine[k] = mine[k].filter(function (n) {
                    return String(n).toLowerCase() !== String(username).toLowerCase();
                });
            });
            data[me] = mine;
            if (typeof saveSocialData === "function") saveSocialData(data);
        }
    } catch (e) {}

    if (typeof showAzoraToast === "function") showAzoraToast("Blocked " + username);
    try {
        if (typeof currentChatFriend !== "undefined" && currentChatFriend === username && typeof selectChatFriend === "function") {
            selectChatFriend("__azora_ai__");
        }
        if (typeof renderFriendsList === "function") renderFriendsList();
        if (typeof closeProfile === "function") closeProfile();
    } catch (e2) {}
}

function unblockUser(username) {
    if (!username) return;
    var list = getBlockedUsers().filter(function (u) {
        return String(u).toLowerCase() !== String(username).toLowerCase();
    });
    saveBlockedUsers(list);
    if (typeof showAzoraToast === "function") showAzoraToast("Unblocked " + username);
    try {
        if (typeof openUserProfile === "function") openUserProfile(username);
    } catch (e) {}
}

/** Simple family-safe automated moderation for chat text */
function azoraAutoModerate(text) {
    text = String(text || "");
    var original = text;
    // Patterns kept mild and age-appropriate — catch common bad words / spam
    var blocked = [
        /\b(kill\s*yourself|kys)\b/i,
        /\b(n+i+gg+e*r+|f+a+g+g*o*t+)\b/i,
        /\b(f+u+c+k+|sh[i1]t+|b[i1]tch+|a+s+s+h+o+l+e+)\b/i,
        /\b(porn|onlyfans|sex\s*chat|nude|naked)\b/i,
        /\b(https?:\/\/\S+)/i  // bare links often used for spam in kids platforms
    ];
    for (var i = 0; i < blocked.length; i++) {
        if (blocked[i].test(text)) {
            return {
                ok: false,
                reason: "Your message was blocked by automated moderation. Please keep Azora friendly and safe for everyone."
            };
        }
    }
    // Soft length spam
    if (text.length > 400 && !/^\s*\/azorweb\s*:/i.test(text)) {
        return { ok: false, reason: "Message is too long (max 400 characters). Website prompts with /AzorWeb: can be longer." };
    }
    // Repeat character spam
    if (/(.)\1{12,}/.test(text)) {
        return { ok: false, reason: "Message looks like spam and was blocked." };
    }
    return { ok: true, text: original };
}

function getReports() {
    try {
        var list = JSON.parse(localStorage.getItem("azoraReports") || "[]");
        return Array.isArray(list) ? list : [];
    } catch (e) { return []; }
}

function saveReport(entry) {
    var list = getReports();
    list.unshift(entry);
    list = list.slice(0, 50);
    try { localStorage.setItem("azoraReports", JSON.stringify(list)); } catch (e) {}
    // Cloud copy for staff (best effort)
    try {
        if (typeof isCloudSocialReady === "function" && isCloudSocialReady() && typeof cloudPutJson === "function") {
            var id = "r_" + Date.now() + "_" + Math.random().toString(36).slice(2, 7);
            var base = (typeof cloudBase === "function" ? cloudBase() : "") + "/azoraReports/" + id + ".json";
            cloudPutJson(base, entry).catch(function () {});
        }
    } catch (e2) {}
}

function openReportUser(username) {
    if (!username) return;
    if (String(username).toLowerCase() === "azora") {
        alert("You cannot report the official Azora account.");
        return;
    }
    var me = (typeof getMyUsername === "function") ? getMyUsername() : "Player";
    if (me && String(me).toLowerCase() === String(username).toLowerCase()) {
        alert("You cannot report yourself.");
        return;
    }
    window._reportTargetUsername = String(username);
    var ov = document.getElementById("reportUserOverlay");
    var t = document.getElementById("reportUserTarget");
    var sel = document.getElementById("reportReasonSelect");
    var det = document.getElementById("reportDetails");
    var err = document.getElementById("reportFormError");
    if (t) t.textContent = "Reporting: " + username;
    if (sel) sel.value = "";
    if (det) det.value = "";
    if (err) { err.style.display = "none"; err.textContent = ""; }
    if (ov) ov.style.display = "flex";
}

function closeReportUser() {
    var ov = document.getElementById("reportUserOverlay");
    if (ov) ov.style.display = "none";
    window._reportTargetUsername = null;
}

function submitReportUser() {
    var username = window._reportTargetUsername;
    if (!username) return;
    var sel = document.getElementById("reportReasonSelect");
    var det = document.getElementById("reportDetails");
    var err = document.getElementById("reportFormError");
    var reason = sel ? String(sel.value || "").trim() : "";
    if (!reason) {
        if (err) { err.style.display = "block"; err.textContent = "Please select a reason."; }
        return;
    }
    var details = det ? String(det.value || "").trim().slice(0, 240) : "";
    if (details && typeof azoraAutoModerate === "function") {
        var mod = azoraAutoModerate(details);
        if (!mod.ok) {
            if (err) { err.style.display = "block"; err.textContent = mod.reason || "That note is not allowed."; }
            return;
        }
    }
    var me = (typeof getMyUsername === "function") ? getMyUsername() : "Player";
    var entry = {
        id: "rep_" + Date.now(),
        reported: username,
        by: me || "unknown",
        reason: reason,
        details: details,
        at: Date.now(),
        status: "pending"
    };
    saveReport(entry);

    // Notify Azora (owner) in notifications
    var msg = "Report: " + username + " — " + reason;
    if (details) msg += " (" + details + ")";
    msg += " · by " + (me || "someone");
    try {
        if (typeof pushNotification === "function") {
            pushNotification("Azora", msg, "report", {
                reported: username,
                reason: reason,
                details: details,
                by: me,
                reportId: entry.id
            });
        }
    } catch (eN) {}

    closeReportUser();
    if (typeof showAzoraToast === "function") {
        showAzoraToast("Report submitted. Azora has been notified.");
    } else {
        alert("Report submitted. Azora has been notified.");
    }
}

