// --- Global server flags (from Staff Console / Firebase) ---
function isFirebaseErrorNode(v) {
    return !!(v && typeof v === "object" && !Array.isArray(v) && typeof v.error === "string" && v.username == null && v.userId == null);
}

function isMaintenanceFlagOn(v) {
    // Only an explicit ON value shows the banner. Error objects, null, "false", {} stay OFF.
    if (v === true || v === 1) return true;
    if (typeof v === "string") {
        var s = v.trim().toLowerCase();
        return s === "true" || s === "on" || s === "1" || s === "yes";
    }
    return false;
}

function sanitizeBroadcastFlag(v) {
    if (v == null || v === false) return "";
    if (typeof v === "string") return v;
    if (isFirebaseErrorNode(v)) return "";
    if (typeof v === "object") return "";
    return String(v);
}

function applyServerFlags(flags) {
    if (!flags || typeof flags !== "object") return;
    var banner = document.getElementById("serverMessage");
    var maintOn = isMaintenanceFlagOn(flags.maintenance);
    var broadcast = sanitizeBroadcastFlag(flags.broadcast);
    if (banner) {
        if (maintOn) {
            banner.style.display = "block";
            banner.innerHTML = "⚠️ Azora is in <strong>maintenance mode</strong>. Some features may be limited.<br>Please check back soon.";
            banner.setAttribute("data-dynamic", "1");
        } else if (broadcast) {
            banner.style.display = "block";
            banner.textContent = broadcast;
            banner.setAttribute("data-dynamic", "1");
        } else {
            banner.style.display = "none";
            banner.removeAttribute("data-dynamic");
        }
    }
    if (flags.event) {
        document.documentElement.setAttribute("data-azora-event", String(flags.event));
    } else {
        document.documentElement.removeAttribute("data-azora-event");
    }
    // Coins display sync if present
    try {
        var coins = (typeof getCoins === "function") ? String(getCoins()) : (localStorage.getItem("azoraCoins") || "0");
        var el = document.getElementById("bucks");
        if (el && coins !== null) el.textContent = coins;
    } catch (e) {}
}

function loadServerFlags() {
    // Prefer cloud meta; fall back to local staff flags
    function fromLocal() {
        try {
            var flags = JSON.parse(localStorage.getItem("azoraServerFlags") || "{}");
            applyServerFlags(flags);
        } catch (e) {}
        // coins
        try {
            if (typeof updateCoinsUI === "function") updateCoinsUI();
            else {
                var el = document.getElementById("bucks");
                if (el && typeof getCoins === "function") el.textContent = String(getCoins());
            }
        } catch (e) {}
    }

    function fetchMetaNode(path) {
        return fetch(path + "?ts=" + Date.now(), { cache: "no-store" })
            .then(function (r) {
                if (!r.ok) return null;
                return r.json();
            })
            .then(function (v) {
                if (isFirebaseErrorNode(v)) return null;
                return v;
            })
            .catch(function () { return null; });
    }

    if (typeof AZORA_CLOUD === "undefined" || !AZORA_CLOUD.isReady()) {
        fromLocal();
        return;
    }
    var base = cloudBase();
    Promise.all([
        fetchMetaNode(base + "/azoraMeta/broadcast.json"),
        fetchMetaNode(base + "/azoraMeta/maintenance.json"),
        fetchMetaNode(base + "/azoraMeta/event.json")
    ]).then(function (vals) {
        var maintOn = isMaintenanceFlagOn(vals[1]);
        applyServerFlags({
            broadcast: vals[0],
            maintenance: maintOn,
            event: (isFirebaseErrorNode(vals[2]) ? null : vals[2])
        });
        // Cloud said OFF or missing — don't keep a leftover local ON flag
        if (!maintOn) {
            try {
                var flags = JSON.parse(localStorage.getItem("azoraServerFlags") || "{}");
                if (flags && flags.maintenance) {
                    flags.maintenance = false;
                    localStorage.setItem("azoraServerFlags", JSON.stringify(flags));
                }
            } catch (eClr) {}
        }
    }).catch(fromLocal);
}

window.loadServerFlags = loadServerFlags;
window.applyServerFlags = applyServerFlags;



// Create the container automatically
const container = document.createElement('div');
container.id = 'falling-text-container';
document.body.appendChild(container);

// Function to spawn a random word
function spawnWord() {
    if (!fallingTextActive) return;
    const word = document.createElement('div');
    word.className = 'falling-word';
    word.innerText = phrases[Math.floor(Math.random() * phrases.length)];
    
    word.style.left = Math.random() * 90 + 'vw';
    word.style.top = '-50px'; // Start just above the screen
    
    container.appendChild(word);
    
    let currentTop = -50;
    let currentRotation = 0;
    const rotationDirection = Math.random() > 0.5 ? 1 : -1; 

    const interval = setInterval(() => {
        currentTop += fallSpeed;
        currentRotation += rotationSpeed * rotationDirection;
        
        word.style.top = currentTop + 'px';
        word.style.transform = `rotate(${currentRotation}deg)`;
        
        if (currentTop > window.innerHeight) {
            clearInterval(interval);
            word.remove();
        }
    }, 20);
}

// Spawn a new word every 10.0 seconds
function startFallingPhrases() {
    // Feature retired: falling phrases increased lag in 3D games
    fallingTextActive = false;
    if (spawnInterval) { clearInterval(spawnInterval); spawnInterval = null; }
    var c = document.getElementById("falling-text-container");
    if (c) c.innerHTML = "";
}
function stopFallingPhrasesForGame() {
    fallingTextActive = false;
    if (spawnInterval) { clearInterval(spawnInterval); spawnInterval = null; }
    var c = document.getElementById("falling-text-container");
    if (c) { c.innerHTML = ""; c.style.display = "none"; }
}
