// --- 3D Avatar Global Variables ---
let scene, camera, renderer;
let headMesh, torsoMesh, leftArmMesh, rightArmMesh, leftLegMesh, rightLegMesh;
let faceGroup, neckMesh, avatarCharacterGroup;

/** Materials unlocked — textures + distinct materials used in games, closet, and Creator. */
var AZORA_MATERIALS_LOCKED = false;

function azoraGlossMaterial(color) {
    try {
        return new THREE.MeshPhongMaterial({
            color: color,
            shininess: 90,
            specular: 0xbfbfbf,
            reflectivity: 0.4
        });
    } catch (e) {
        try {
            return new THREE.MeshStandardMaterial({
                color: color,
                metalness: 0.15,
                roughness: 0.25
            });
        } catch (e2) {
            return ((typeof azoraGlossMaterial==="function")?azoraGlossMaterial(color ):new THREE.MeshLambertMaterial({color:color }));
        }
    }
}

/**
 * True rounded BOX: all 6 faces stay FLAT.
 * Only edges + corners are rounded (not a sphere, capsule, or extruded blob).
 */
function azoraRoundedBoxGeometry(w, h, d, radius) {
    w = Math.max(0.04, Number(w) || 0.3);
    h = Math.max(0.04, Number(h) || 0.3);
    d = Math.max(0.04, Number(d) || 0.3);

    // Keep radius modest so the middle of every face stays a flat plane
    var maxR = Math.min(w, h, d) * 0.18;
    var r = Math.min(Math.max(0.01, radius != null ? radius : Math.min(w, h, d) * 0.1), maxR);

    try {
        var seg = 4; // enough samples for smooth edge arcs
        var geo = new THREE.BoxGeometry(w, h, d, seg, seg, seg);
        var pos = geo.attributes.position;
        var hw = w / 2, hh = h / 2, hd = d / 2;
        // Inner box = the flat region of each face
        var ix = Math.max(0.001, hw - r);
        var iy = Math.max(0.001, hh - r);
        var iz = Math.max(0.001, hd - r);

        var v = new THREE.Vector3();
        for (var i = 0; i < pos.count; i++) {
            v.fromBufferAttribute(pos, i);
            var x = v.x, y = v.y, z = v.z;

            // Project onto the inner flat box
            var cx = Math.max(-ix, Math.min(ix, x));
            var cy = Math.max(-iy, Math.min(iy, y));
            var cz = Math.max(-iz, Math.min(iz, z));

            var dx = x - cx, dy = y - cy, dz = z - cz;
            var len = Math.sqrt(dx * dx + dy * dy + dz * dz);

            if (len > 1e-8) {
                // Edge / corner: push outward by exactly radius r
                // → flat faces, cylindrical edges, spherical corners
                var s = r / len;
                pos.setXYZ(i, cx + dx * s, cy + dy * s, cz + dz * s);
            } else {
                // Vertex already on the flat face interior — leave it
                pos.setXYZ(i, x, y, z);
            }
        }
        pos.needsUpdate = true;
        try { geo.computeVertexNormals(); } catch (eN) {}
        return geo;
    } catch (eEx) {
        return new THREE.BoxGeometry(w, h, d);
    }
}
window.azoraRoundedBoxGeometry = azoraRoundedBoxGeometry;

function makeBox(w, h, d, color) {
    var radius = Math.min(w, h, d) * 0.1;
    return new THREE.Mesh(
        azoraRoundedBoxGeometry(w, h, d, radius),
        azoraGlossMaterial(color)
    );
}

function buildAvatarFace(headColor, gender) {
    // Flat 2D face decal — Smile.png (boy) or female_smile.png (girl).
    // Transparent PNG. Plane stays hidden until texture loads.
    gender = gender || (typeof getAvatarGender === "function" ? getAvatarGender() : "boy");
    var faceUrl = (typeof faceTextureUrlForGender === "function")
        ? faceTextureUrlForGender(gender)
        : ((gender === "girl" || gender === "female") ? "female_smile.png" : "Smile.png");
    var face = new THREE.Group();
    face.name = "face";
    face.userData.gender = gender;

    var mat = new THREE.MeshBasicMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0,
        depthWrite: false,
        side: THREE.FrontSide,
        alphaTest: 0.2
    });

    // Plane is centered on the front of the head (head is ~0.65 cube)
    var plane = new THREE.Mesh(new THREE.PlaneGeometry(0.54, 0.54), mat);
    plane.name = "faceDecal";
    plane.position.set(0, 0, 0.34);
    plane.visible = false;
    face.add(plane);

    function showTex(tex) {
        if (!tex) return;
        tex.minFilter = THREE.LinearFilter;
        tex.magFilter = THREE.LinearFilter;
        tex.generateMipmaps = false;
        tex.needsUpdate = true;
        mat.map = tex;
        mat.transparent = true;
        mat.opacity = 1;
        mat.alphaTest = 0.15;
        mat.needsUpdate = true;
        plane.visible = true;
    }

    function showCenteredFromImage(img) {
        var centered = null;
        try {
            if (typeof textureFromCenteredFace === "function") {
                centered = textureFromCenteredFace(img);
            }
        } catch (e) {}
        if (centered) showTex(centered);
        else {
            try {
                var t = new THREE.Texture(img);
                t.needsUpdate = true;
                showTex(t);
            } catch (e2) {}
        }
    }

    // Prefer TextureLoader (works on https / PWA). Avoid crossOrigin on file:// so local tests work.
    function loadFaceImage(url, onFail) {
        try {
            var img = new Image();
            if (typeof location !== "undefined" && location.protocol !== "file:") {
                img.crossOrigin = "anonymous";
            }
            img.onload = function () {
                try {
                    if (typeof showCenteredFromImage === "function") {
                        showCenteredFromImage(img);
                    } else {
                        var t = new THREE.Texture(img);
                        t.needsUpdate = true;
                        showTex(t);
                    }
                } catch (e) {
                    try {
                        var t2 = new THREE.Texture(img);
                        t2.needsUpdate = true;
                        showTex(t2);
                    } catch (e2) {
                        if (onFail) onFail();
                    }
                }
            };
            img.onerror = function () { if (onFail) onFail(); };
            img.src = url;
        } catch (e) {
            if (onFail) onFail();
        }
    }

    // Prefer Image path so we can crop + center opaque face pixels on the head
    loadFaceImage(faceUrl, function () {
        loadFaceImage((faceUrl.charAt(0) === "." ? faceUrl : ("./" + faceUrl)), function () {
            console.warn("[Azora] face texture missing — face left blank");
        });
    });

    return face;
}


/** Blocky hair for girl avatars — sits on top of the head */
function makeAvatarHair(hairColor, headY, headSize, styleId) {
    if (typeof THREE === "undefined") return null;
    hairColor = hairColor || "#4a3728";
    headY = (typeof headY === "number") ? headY : 1.12;
    headSize = headSize || 0.65;
    styleId = styleId || "hair_girl_default";

    // No hair style
    if (styleId === "hair_boy_none" || styleId === "none") return null;

    var group = new THREE.Group();
    group.name = "hair";
    group.userData = group.userData || {};
    group.userData.hairStyle = styleId;
    var mat = (typeof azoraGlossMaterial === 'function') ? azoraGlossMaterial(hairColor) : ((typeof azoraGlossMaterial==="function")?azoraGlossMaterial(hairColor ):new THREE.MeshLambertMaterial({color:hairColor }));

    function addPart(name, x, y, z, w, h, d) {
        var radius = Math.min(w, h, d) * 0.08;
        var geo = (typeof azoraRoundedBoxGeometry === "function")
            ? azoraRoundedBoxGeometry(w, h, d, radius)
            : new THREE.BoxGeometry(w, h, d);
        var m = new THREE.Mesh(geo, mat.clone());
        m.position.set(x, y, z);
        m.name = name;
        group.add(m);
    }

    // ---- Girl styles ----
    if (styleId === "hair_girl_default") {
        addPart("hairCap", 0, headY + headSize * 0.38, -0.02, headSize * 1.18, headSize * 0.38, headSize * 1.12);
        addPart("hairBack", 0, headY + headSize * 0.05, -headSize * 0.42, headSize * 1.05, headSize * 0.7, headSize * 0.4);
        addPart("hairBangs", 0, headY + headSize * 0.22, headSize * 0.4, headSize * 0.95, headSize * 0.2, headSize * 0.2);
        addPart("hairSideL", -headSize * 0.58, headY - headSize * 0.35, 0.02, headSize * 0.28, headSize * 1.15, headSize * 0.3);
        addPart("hairSideR", headSize * 0.58, headY - headSize * 0.35, 0.02, headSize * 0.28, headSize * 1.15, headSize * 0.3);
        addPart("hairBackMid", 0, headY - headSize * 0.55, -headSize * 0.4, headSize * 0.9, headSize * 1.0, headSize * 0.28);
    } else if (styleId === "hair_girl_bob") {
        addPart("hairCap", 0, headY + headSize * 0.36, -0.02, headSize * 1.22, headSize * 0.36, headSize * 1.15);
        addPart("hairBack", 0, headY - headSize * 0.15, -headSize * 0.45, headSize * 1.1, headSize * 0.85, headSize * 0.42);
        addPart("hairBangs", 0, headY + headSize * 0.18, headSize * 0.42, headSize * 1.0, headSize * 0.18, headSize * 0.22);
        addPart("hairSideL", -headSize * 0.6, headY - headSize * 0.25, 0.05, headSize * 0.32, headSize * 0.95, headSize * 0.32);
        addPart("hairSideR", headSize * 0.6, headY - headSize * 0.25, 0.05, headSize * 0.32, headSize * 0.95, headSize * 0.32);
    } else if (styleId === "hair_girl_ponytail") {
        addPart("hairCap", 0, headY + headSize * 0.36, -0.02, headSize * 1.15, headSize * 0.36, headSize * 1.1);
        addPart("hairBangs", 0, headY + headSize * 0.2, headSize * 0.4, headSize * 0.9, headSize * 0.18, headSize * 0.18);
        addPart("hairSideL", -headSize * 0.55, headY - headSize * 0.15, 0.02, headSize * 0.24, headSize * 0.7, headSize * 0.24);
        addPart("hairSideR", headSize * 0.55, headY - headSize * 0.15, 0.02, headSize * 0.24, headSize * 0.7, headSize * 0.24);
        // Ponytail bun + long tail behind
        addPart("hairBun", 0, headY + headSize * 0.15, -headSize * 0.55, headSize * 0.4, headSize * 0.4, headSize * 0.4);
        addPart("hairTail", 0, headY - headSize * 0.7, -headSize * 0.6, headSize * 0.28, headSize * 1.5, headSize * 0.28);
    } else if (styleId === "hair_girl_pigtails") {
        addPart("hairCap", 0, headY + headSize * 0.36, -0.02, headSize * 1.15, headSize * 0.34, headSize * 1.1);
        addPart("hairBangs", 0, headY + headSize * 0.2, headSize * 0.4, headSize * 0.9, headSize * 0.18, headSize * 0.18);
        // Left pigtail
        addPart("pigL1", -headSize * 0.7, headY + headSize * 0.1, 0, headSize * 0.28, headSize * 0.28, headSize * 0.28);
        addPart("pigL2", -headSize * 0.85, headY - headSize * 0.35, 0.05, headSize * 0.24, headSize * 0.9, headSize * 0.24);
        // Right pigtail
        addPart("pigR1", headSize * 0.7, headY + headSize * 0.1, 0, headSize * 0.28, headSize * 0.28, headSize * 0.28);
        addPart("pigR2", headSize * 0.85, headY - headSize * 0.35, 0.05, headSize * 0.24, headSize * 0.9, headSize * 0.24);
    } else if (styleId === "hair_girl_bangs") {
        addPart("hairCap", 0, headY + headSize * 0.38, -0.02, headSize * 1.12, headSize * 0.36, headSize * 1.08);
        addPart("hairBack", 0, headY + headSize * 0.05, -headSize * 0.4, headSize * 1.0, headSize * 0.6, headSize * 0.35);
        // Heavy bangs
        addPart("hairBangs", 0, headY + headSize * 0.15, headSize * 0.45, headSize * 1.05, headSize * 0.28, headSize * 0.25);
        addPart("hairSideL", -headSize * 0.55, headY - headSize * 0.2, 0.02, headSize * 0.22, headSize * 0.8, headSize * 0.22);
        addPart("hairSideR", headSize * 0.55, headY - headSize * 0.2, 0.02, headSize * 0.22, headSize * 0.8, headSize * 0.22);
    }
    // ---- Boy styles ----
    else if (styleId === "hair_boy_short") {
        addPart("hairCap", 0, headY + headSize * 0.32, -0.02, headSize * 1.1, headSize * 0.28, headSize * 1.05);
        addPart("hairBack", 0, headY + headSize * 0.1, -headSize * 0.35, headSize * 0.95, headSize * 0.4, headSize * 0.3);
        addPart("hairSideL", -headSize * 0.5, headY + headSize * 0.05, 0, headSize * 0.2, headSize * 0.45, headSize * 0.25);
        addPart("hairSideR", headSize * 0.5, headY + headSize * 0.05, 0, headSize * 0.2, headSize * 0.45, headSize * 0.25);
    } else if (styleId === "hair_boy_spiky") {
        addPart("hairCap", 0, headY + headSize * 0.35, -0.02, headSize * 1.05, headSize * 0.25, headSize * 1.0);
        // Spikes
        addPart("spike1", 0, headY + headSize * 0.55, 0.05, headSize * 0.18, headSize * 0.35, headSize * 0.18);
        addPart("spike2", -headSize * 0.25, headY + headSize * 0.5, 0, headSize * 0.16, headSize * 0.3, headSize * 0.16);
        addPart("spike3", headSize * 0.25, headY + headSize * 0.5, 0, headSize * 0.16, headSize * 0.3, headSize * 0.16);
        addPart("spike4", -headSize * 0.4, headY + headSize * 0.42, -0.05, headSize * 0.14, headSize * 0.25, headSize * 0.14);
        addPart("spike5", headSize * 0.4, headY + headSize * 0.42, -0.05, headSize * 0.14, headSize * 0.25, headSize * 0.14);
    } else if (styleId === "hair_boy_side") {
        addPart("hairCap", 0, headY + headSize * 0.32, -0.05, headSize * 1.08, headSize * 0.28, headSize * 1.0);
        addPart("hairBack", 0, headY + headSize * 0.08, -headSize * 0.38, headSize * 0.95, headSize * 0.45, headSize * 0.32);
        // Side sweep to the right
        addPart("sweep", headSize * 0.35, headY + headSize * 0.15, headSize * 0.25, headSize * 0.55, headSize * 0.22, headSize * 0.3);
        addPart("sideL", -headSize * 0.48, headY + headSize * 0.05, 0, headSize * 0.18, headSize * 0.4, headSize * 0.22);
    } else if (styleId === "hair_boy_cap") {
        // Flat cap-like hair
        addPart("hairCap", 0, headY + headSize * 0.4, 0.05, headSize * 1.25, headSize * 0.22, headSize * 1.2);
        addPart("brim", 0, headY + headSize * 0.28, headSize * 0.35, headSize * 1.15, headSize * 0.12, headSize * 0.35);
        addPart("hairBack", 0, headY + headSize * 0.1, -headSize * 0.35, headSize * 1.0, headSize * 0.4, headSize * 0.3);
    } else {
        // Fallback: girl default short
        addPart("hairCap", 0, headY + headSize * 0.38, -0.02, headSize * 1.18, headSize * 0.38, headSize * 1.12);
        addPart("hairBack", 0, headY + headSize * 0.05, -headSize * 0.42, headSize * 1.05, headSize * 0.7, headSize * 0.4);
        addPart("hairBangs", 0, headY + headSize * 0.22, headSize * 0.4, headSize * 0.95, headSize * 0.2, headSize * 0.2);
        addPart("hairSideL", -headSize * 0.58, headY - headSize * 0.35, 0.02, headSize * 0.28, headSize * 1.15, headSize * 0.3);
        addPart("hairSideR", headSize * 0.58, headY - headSize * 0.35, 0.02, headSize * 0.28, headSize * 1.15, headSize * 0.3);
    }

    return group;
}


function removeAvatarHair(parent) {
    if (!parent) return;
    var existing = parent.getObjectByName("hair");
    if (existing) parent.remove(existing);
}

function applyGenderVisualsToCustomizer(gender, colors) {
    if (!avatarCharacterGroup) return;
    gender = gender || getAvatarGender();
    colors = colors || {};
    var realistic = (typeof getAvatarRenderStyle === "function" && getAvatarRenderStyle() === "realistic");
    removeAvatarHair(avatarCharacterGroup);
    // Also remove realistic hair group if present
    try {
        avatarCharacterGroup.traverse(function (o) {
            if (o && o.name === "hair" && o.parent) o.parent.remove(o);
        });
    } catch (eRH) {}
    var styleId = null;
    try {
        if (typeof getEquippedHairStyle === "function") styleId = getEquippedHairStyle();
    } catch (e) {}
    if (!styleId) styleId = (colors && colors.hairStyle) || "hair_boy_none";
    var hairCol = (colors && colors.hair) || "#4a3728";
    var isGirl = (gender === "girl" || gender === "female");
    if (realistic) {
        // Realistic: shop hair if equipped, else soft girl hair when girl
        var hasShop = styleId && styleId !== "hair_boy_none" && styleId !== "none" && styleId !== "hair_girl_default";
        if (hasShop && typeof makeAvatarHair === "function") {
            var hy = headMesh ? headMesh.position.y : 1.55;
            var hair = makeAvatarHair(hairCol, 0, 0.5, styleId);
            var headJoint = avatarCharacterGroup.userData && avatarCharacterGroup.userData.joints && avatarCharacterGroup.userData.joints.head;
            if (hair) { if (headJoint) headJoint.add(hair); else avatarCharacterGroup.add(hair); }
        } else if (isGirl && typeof makeRealisticHair === "function") {
            var hr = 0.25;
            try {
                if (headMesh && headMesh.geometry && headMesh.geometry.parameters) hr = headMesh.geometry.parameters.radius || 0.25;
            } catch (eHr) {}
            var rh = makeRealisticHair("girl", hairCol, hr);
            var hj = avatarCharacterGroup.userData && avatarCharacterGroup.userData.joints && avatarCharacterGroup.userData.joints.head;
            if (rh) { if (hj) hj.add(rh); else avatarCharacterGroup.add(rh); }
        }
    } else {
        // Blocky: both bald by default unless marketplace hair equipped
        if (styleId === "hair_girl_default") styleId = "hair_boy_none";
        if (styleId && styleId !== "hair_boy_none" && styleId !== "none") {
            var hy2 = headMesh ? headMesh.position.y : 1.28;
            var hair2 = makeAvatarHair(hairCol, hy2, 0.65, styleId);
            if (hair2) avatarCharacterGroup.add(hair2);
        }
    }
    // Blocky-only body shape tweaks (skip when realistic humanoid is active)
    if (!realistic) {
        try {
            var av = colors;
            try {
                var acc = JSON.parse(localStorage.getItem("azoraAccount") || "null");
                if (acc && acc.avatar) av = Object.assign({}, acc.avatar, colors || {});
            } catch (eA) {}
            if (typeof applyDefaultBodyShapeToMeshes === "function") {
                applyDefaultBodyShapeToMeshes(gender, av, {
                    head: headMesh, torso: torsoMesh, leftArm: leftArmMesh, rightArm: rightArmMesh,
                    leftLeg: leftLegMesh, rightLeg: rightLegMesh, group: avatarCharacterGroup
                });
            }
        } catch (eBody) {}
    }
    // Rebuild face decal for gender
    try {
        if (faceGroup) {
            // face may be parented under head group in realistic mode
            if (faceGroup.parent) faceGroup.parent.remove(faceGroup);
            else if (avatarCharacterGroup) avatarCharacterGroup.remove(faceGroup);
        }
        if (realistic && typeof buildWrappedSphereFace === "function") {
            var hr = 0.25;
            try {
                if (headMesh && headMesh.geometry && headMesh.geometry.parameters) {
                    hr = headMesh.geometry.parameters.radius || 0.25;
                }
            } catch (eR) {}
            faceGroup = buildWrappedSphereFace(gender, hr * 1.02, 0);
            faceGroup.position.set(0, 0, 0);
            var headJoint = avatarCharacterGroup.userData && avatarCharacterGroup.userData.joints && avatarCharacterGroup.userData.joints.head;
            if (headJoint) headJoint.add(faceGroup);
            else if (headMesh && headMesh.parent) headMesh.parent.add(faceGroup);
            else avatarCharacterGroup.add(faceGroup);
        } else {
            faceGroup = buildAvatarFace(colors.head || "#e0a870", gender);
            faceGroup.position.y = headMesh ? headMesh.position.y : 1.28;
            avatarCharacterGroup.add(faceGroup);
        }
    } catch (e) {}
}

window.makeAvatarHair = makeAvatarHair;
window.applyGenderVisualsToCustomizer = applyGenderVisualsToCustomizer;



// —— Avatar style test: blocky (default) ↔ realistic humanoid ——
// Avatar style tests removed — blocky only
window._avatarRenderStyle = "blocky";
function getAvatarRenderStyle() { return "blocky"; }
function setAvatarRenderStyle(style) {
    window._avatarRenderStyle = "blocky";
    try { sessionStorage.removeItem("azoraAvatarRenderStyle"); } catch (e) {}
    var btn = document.getElementById("avatarStyleTestBtn");
    if (btn) btn.style.display = "none";
}

function clearAvatarCharacterMeshes() {
    if (!avatarCharacterGroup) return;
    try {
        while (avatarCharacterGroup.children.length) {
            var ch = avatarCharacterGroup.children[0];
            avatarCharacterGroup.remove(ch);
            try {
                if (ch.geometry) ch.geometry.dispose();
                if (ch.material) {
                    if (Array.isArray(ch.material)) ch.material.forEach(function (m) { try { m.dispose(); } catch (e) {} });
                    else ch.material.dispose();
                }
            } catch (eD) {}
        }
    } catch (e) {}
    headMesh = torsoMesh = leftArmMesh = rightArmMesh = leftLegMesh = rightLegMesh = null;
    faceGroup = null;
    neckMesh = null;
}

function _azoraLimbMat(hex) {
    try {
        if (typeof azoraGlossMaterial === "function") return azoraGlossMaterial(hex);
    } catch (e) {}
    return new THREE.MeshLambertMaterial({ color: hex });
}

/** Classic blocky R6-style limbs (current default) */
function buildBlockyAvatarMeshes(gender, colors) {
    colors = colors || {};
    gender = (gender === "girl" || gender === "female") ? "girl" : "boy";
    var headC = colors.head || "#e0a870";
    var torsoC = colors.torso || "#1d4ed8";
    var laC = colors.leftArm || headC;
    var raC = colors.rightArm || headC;
    var llC = colors.leftLeg || "#334155";
    var rlC = colors.rightLeg || "#334155";

    torsoMesh = makeBox(0.78, 1.12, 0.42, torsoC);
    torsoMesh.name = "torso";
    torsoMesh.position.y = 0.42;
    avatarCharacterGroup.add(torsoMesh);

    neckMesh = makeBox(0.22, 0.18, 0.22, headC);
    neckMesh.name = "neck";
    neckMesh.position.y = 1.07;
    avatarCharacterGroup.add(neckMesh);

    var cvbBox = makeBox(0.05, 0.04, 0.05, "#6b7280");
    cvbBox.name = "cvbVoiceBox";
    cvbBox.position.y = 1.07;
    cvbBox.position.z = 0;
    try {
        if (cvbBox.material) {
            cvbBox.material.transparent = true;
            cvbBox.material.opacity = 0.35;
        }
    } catch (eCvbM) {}
    avatarCharacterGroup.add(cvbBox);
    avatarCharacterGroup.userData = avatarCharacterGroup.userData || {};
    avatarCharacterGroup.userData.cvbVoiceBox = cvbBox;

    headMesh = makeBox(0.52, 0.52, 0.52, headC);
    headMesh.name = "head";
    headMesh.position.y = 1.42;
    avatarCharacterGroup.add(headMesh);

    faceGroup = buildAvatarFace(headC, gender);
    faceGroup.position.y = 1.42;
    avatarCharacterGroup.add(faceGroup);

    leftArmMesh = makeBox(0.30, 1.08, 0.30, laC);
    leftArmMesh.name = "leftArm";
    leftArmMesh.position.set(-0.56, 0.42, 0);
    avatarCharacterGroup.add(leftArmMesh);

    rightArmMesh = makeBox(0.30, 1.08, 0.30, raC);
    rightArmMesh.name = "rightArm";
    rightArmMesh.position.set(0.56, 0.42, 0);
    avatarCharacterGroup.add(rightArmMesh);

    leftLegMesh = makeBox(0.30, 1.12, 0.30, llC);
    leftLegMesh.name = "leftLeg";
    leftLegMesh.position.set(-0.18, -0.70, 0);
    avatarCharacterGroup.add(leftLegMesh);

    rightLegMesh = makeBox(0.30, 1.12, 0.30, rlC);
    rightLegMesh.name = "rightLeg";
    rightLegMesh.position.set(0.18, -0.70, 0);
    avatarCharacterGroup.add(rightLegMesh);

    avatarCharacterGroup.userData = avatarCharacterGroup.userData || {};
    avatarCharacterGroup.userData.animStyle = "blocky";
    avatarCharacterGroup.userData.joints = null;

    try {
        if (typeof applyGenderVisualsToCustomizer === "function") {
            applyGenderVisualsToCustomizer(gender, colors);
        }
    } catch (eG) {}
    // Show parts saved from in-game inventory on the main Azora avatar
    try {
        if (typeof applySavedExtraPartsToMesh === "function") {
            var parts = (colors && colors.extraParts) ? colors.extraParts : (typeof getSavedExtraParts === "function" ? getSavedExtraParts() : []);
            applySavedExtraPartsToMesh(avatarCharacterGroup, parts);
        }
    } catch (ePartsMain) {}
}

/**
 * TEST: smoother humanoid made of spheres + cylinders.
 * Still family-friendly (no detailed anatomy) — just less blocky.
 */
/**
 * Face that wraps around a spherical head (curved shell, not a flat plane).
 * Uses the same face PNGs (Smile.png / female_smile / equipped faces).
 */
function buildWrappedSphereFace(gender, headRadius, headY) {
    gender = gender || "boy";
    headRadius = headRadius || 0.26;
    // headY ignored when parented to head group — always sit at head center
    var faceUrl = (typeof faceTextureUrlForGender === "function")
        ? faceTextureUrlForGender(gender)
        : ((gender === "girl" || gender === "female") ? "female_smile.png" : "Smile.png");
    try {
        if (typeof getEquippedFaceFile === "function") {
            var eq = getEquippedFaceFile();
            if (eq) faceUrl = eq;
        }
    } catch (eEq) {}

    var face = new THREE.Group();
    face.name = "face";
    face.userData.gender = gender;
    face.position.set(0, 0, 0);

    // Front spherical shell — same center as head, slightly larger so it hugs the surface
    // phi around Y-axis: centered on +Z (front). theta from top pole.
    var geo = new THREE.SphereGeometry(
        headRadius * 1.01,
        32, 24,
        -Math.PI * 0.5,   // phiStart: from -90° 
        Math.PI,          // phiLength: 180° front hemisphere around +Z
        Math.PI * 0.22,   // thetaStart: forehead
        Math.PI * 0.56    // thetaLength: down toward chin
    );

    var mat = new THREE.MeshBasicMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0,
        depthWrite: false,
        side: THREE.DoubleSide,
        alphaTest: 0.08
    });
    var shell = new THREE.Mesh(geo, mat);
    shell.name = "faceDecal";
    shell.visible = false;
    face.add(shell);

    function showTex(tex) {
        if (!tex) return;
        tex.minFilter = THREE.LinearFilter;
        tex.magFilter = THREE.LinearFilter;
        tex.generateMipmaps = false;
        tex.wrapS = THREE.ClampToEdgeWrapping;
        tex.wrapT = THREE.ClampToEdgeWrapping;
        tex.needsUpdate = true;
        mat.map = tex;
        mat.transparent = true;
        mat.opacity = 1;
        mat.alphaTest = 0.08;
        mat.needsUpdate = true;
        shell.visible = true;
    }

    function loadFace(url) {
        try {
            var img = new Image();
            if (typeof location !== "undefined" && location.protocol !== "file:") {
                img.crossOrigin = "anonymous";
            }
            img.onload = function () {
                try {
                    var centered = null;
                    if (typeof textureFromCenteredFace === "function") {
                        centered = textureFromCenteredFace(img);
                    }
                    if (centered) showTex(centered);
                    else {
                        var t = new THREE.Texture(img);
                        t.needsUpdate = true;
                        showTex(t);
                    }
                } catch (e) {
                    try {
                        var t2 = new THREE.Texture(img);
                        t2.needsUpdate = true;
                        showTex(t2);
                    } catch (e2) {}
                }
            };
            img.onerror = function () {
                try {
                    var loader = new THREE.TextureLoader();
                    loader.load(url, function (tex) { showTex(tex); });
                } catch (eL) {}
            };
            img.src = url;
        } catch (e) {}
    }
    loadFace(faceUrl);
    return face;
}
window.buildWrappedSphereFace = buildWrappedSphereFace;

/** Soft realistic hair for spherical heads (girl default in realistic mode) */
function makeRealisticHair(gender, hairColor, headR) {
    gender = (gender === "girl" || gender === "female") ? "girl" : "boy";
    if (gender !== "girl") return null;
    headR = headR || 0.26;
    hairColor = hairColor || "#4a3728";
    var mat = (typeof azoraGlossMaterial === "function")
        ? azoraGlossMaterial(hairColor)
        : new THREE.MeshLambertMaterial({ color: hairColor });
    var g = new THREE.Group();
    g.name = "hair";

    // Top cap (upper hemisphere)
    var cap = new THREE.Mesh(
        new THREE.SphereGeometry(headR * 1.12, 22, 16, 0, Math.PI * 2, 0, Math.PI * 0.58),
        mat
    );
    cap.position.y = headR * 0.08;
    cap.name = "hairCap";
    g.add(cap);

    // Back volume
    var back = new THREE.Mesh(
        new THREE.SphereGeometry(headR * 0.95, 18, 12, 0, Math.PI * 2, 0, Math.PI),
        mat
    );
    back.scale.set(1.05, 1.15, 0.7);
    back.position.set(0, -headR * 0.15, -headR * 0.55);
    back.name = "hairBack";
    g.add(back);

    // Side falls (longer for girl)
    var sideL = new THREE.Mesh(
        new THREE.SphereGeometry(headR * 0.42, 12, 10),
        mat
    );
    sideL.scale.set(0.7, 1.6, 0.75);
    sideL.position.set(-headR * 0.85, -headR * 0.55, 0.05);
    sideL.name = "hairSideL";
    g.add(sideL);

    var sideR = sideL.clone();
    sideR.position.x = headR * 0.85;
    sideR.name = "hairSideR";
    g.add(sideR);

    // Soft bangs
    var bangs = new THREE.Mesh(
        new THREE.SphereGeometry(headR * 0.55, 12, 10, 0, Math.PI * 2, 0, Math.PI * 0.6),
        mat
    );
    bangs.scale.set(1.15, 0.45, 0.55);
    bangs.position.set(0, headR * 0.15, headR * 0.75);
    bangs.name = "hairBangs";
    g.add(bangs);

    return g;
}
window.makeRealisticHair = makeRealisticHair;


/**
 * Improved realistic humanoid — hierarchical joints for idle animation.
 * Family-friendly proportions (not anatomical detail).
 */
function buildRealisticHumanoidMeshes(gender, colors) {
    colors = colors || {};
    gender = (gender === "girl" || gender === "female") ? "girl" : "boy";
    var isGirl = gender === "girl";
    var headC = colors.head || "#e0a870";
    var torsoC = colors.torso || "#1d4ed8";
    var laC = colors.leftArm || headC;
    var raC = colors.rightArm || headC;
    var llC = colors.leftLeg || "#334155";
    var rlC = colors.rightLeg || "#334155";

    // More natural humanoid proportions
    var shoulderW = isGirl ? 0.32 : 0.38;
    var chestW = isGirl ? 0.34 : 0.42;
    var waistW = isGirl ? 0.26 : 0.32;
    var hipW = isGirl ? 0.34 : 0.32;
    var headR = isGirl ? 0.23 : 0.25;
    var armLen = 0.46;
    var legLen = 0.52;

    function sphere(r, hex, name, seg) {
        var m = new THREE.Mesh(new THREE.SphereGeometry(r, seg || 20, seg || 16), _azoraLimbMat(hex));
        m.name = name || "";
        return m;
    }
    function cyl(rTop, rBot, h, hex, name, seg) {
        var m = new THREE.Mesh(new THREE.CylinderGeometry(rTop, rBot, h, seg || 14), _azoraLimbMat(hex));
        m.name = name || "";
        return m;
    }
    function box(w, h, d, hex, name) {
        var m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), _azoraLimbMat(hex));
        m.name = name || "";
        return m;
    }

    var joints = {};
    avatarCharacterGroup.userData = avatarCharacterGroup.userData || {};
    avatarCharacterGroup.userData.animStyle = "realistic";
    avatarCharacterGroup.userData.joints = joints;

    // —— Root (feet at ~-0.85) ——
    var root = new THREE.Group();
    root.name = "animRoot";
    avatarCharacterGroup.add(root);
    joints.root = root;

    // Hips
    var hipsG = new THREE.Group();
    hipsG.position.y = 0.55;
    root.add(hipsG);
    joints.hips = hipsG;
    var hipsMesh = sphere(hipW * 0.55, torsoC, "hips", 16);
    hipsMesh.scale.set(1.15, 0.55, 0.75);
    hipsG.add(hipsMesh);

    // Spine / torso group
    var torsoG = new THREE.Group();
    torsoG.position.y = 0.08;
    hipsG.add(torsoG);
    joints.torso = torsoG;

    // Waist
    var waist = cyl(waistW * 0.55, hipW * 0.5, 0.22, torsoC, "torso", 16);
    waist.position.y = 0.14;
    torsoG.add(waist);
    torsoMesh = waist;

    // Chest (wider upper body)
    var chest = cyl(chestW * 0.48, waistW * 0.55, 0.38, torsoC, "chest", 16);
    chest.position.y = 0.42;
    torsoG.add(chest);
    // Soft front plate so torso color reads clearly
    var plate = box(chestW * 0.9, 0.36, 0.18, torsoC, "chest");
    plate.position.set(0, 0.42, 0.12);
    torsoG.add(plate);

    // Shoulders bar
    var shY = 0.62;
    var shL = sphere(0.10, torsoC, "shoulderL", 14);
    shL.position.set(-shoulderW, shY, 0);
    torsoG.add(shL);
    var shR = sphere(0.10, torsoC, "shoulderR", 14);
    shR.position.set(shoulderW, shY, 0);
    torsoG.add(shR);

    // Neck
    neckMesh = cyl(0.07, 0.09, 0.14, headC, "neck", 12);
    neckMesh.position.y = shY + 0.14;
    torsoG.add(neckMesh);

    // Head group (for slight idle nod)
    var headG = new THREE.Group();
    headG.position.y = shY + 0.28;
    torsoG.add(headG);
    joints.head = headG;

    // Slightly oval head (more human than perfect ball)
    headMesh = sphere(headR, headC, "head", 28);
    headMesh.scale.set(0.95, 1.05, 0.98);
    headG.add(headMesh);

    // Face shell shares head center — wraps on the sphere surface
    faceGroup = buildWrappedSphereFace(gender, headR * 1.02, 0);
    headG.add(faceGroup);

    // —— Left arm (jointed) ——
    var armLG = new THREE.Group();
    armLG.position.set(-shoulderW, shY, 0);
    torsoG.add(armLG);
    joints.armL = armLG;

    var uAL = cyl(0.075, 0.065, armLen * 0.55, laC, "upperArmL", 12);
    uAL.position.y = -armLen * 0.28;
    // Slight natural hang angle
    armLG.rotation.z = 0.12;
    armLG.add(uAL);
    leftArmMesh = uAL;

    var elbowL = new THREE.Group();
    elbowL.position.y = -armLen * 0.55;
    armLG.add(elbowL);
    joints.elbowL = elbowL;
    elbowL.rotation.x = 0.15;

    var lAL = cyl(0.06, 0.05, armLen * 0.5, laC, "lowerArmL", 12);
    lAL.position.y = -armLen * 0.25;
    elbowL.add(lAL);
    var handL = sphere(0.065, laC, "handL", 12);
    handL.position.y = -armLen * 0.52;
    elbowL.add(handL);

    // —— Right arm ——
    var armRG = new THREE.Group();
    armRG.position.set(shoulderW, shY, 0);
    torsoG.add(armRG);
    joints.armR = armRG;
    armRG.rotation.z = -0.12;

    var uAR = cyl(0.075, 0.065, armLen * 0.55, raC, "upperArmR", 12);
    uAR.position.y = -armLen * 0.28;
    armRG.add(uAR);
    rightArmMesh = uAR;

    var elbowR = new THREE.Group();
    elbowR.position.y = -armLen * 0.55;
    armRG.add(elbowR);
    joints.elbowR = elbowR;
    elbowR.rotation.x = 0.15;

    var lAR = cyl(0.06, 0.05, armLen * 0.5, raC, "lowerArmR", 12);
    lAR.position.y = -armLen * 0.25;
    elbowR.add(lAR);
    var handR = sphere(0.065, raC, "handR", 12);
    handR.position.y = -armLen * 0.52;
    elbowR.add(handR);

    // —— Left leg ——
    var legLG = new THREE.Group();
    legLG.position.set(-hipW * 0.35, 0, 0);
    hipsG.add(legLG);
    joints.legL = legLG;

    var thL = cyl(0.095, 0.08, legLen * 0.55, llC, "thighL", 12);
    thL.position.y = -legLen * 0.28;
    legLG.add(thL);
    leftLegMesh = thL;

    var kneeL = new THREE.Group();
    kneeL.position.y = -legLen * 0.55;
    legLG.add(kneeL);
    joints.kneeL = kneeL;

    var shL2 = cyl(0.075, 0.06, legLen * 0.5, llC, "shinL", 12);
    shL2.position.y = -legLen * 0.25;
    kneeL.add(shL2);
    var footL = box(0.11, 0.06, 0.20, llC, "footL");
    footL.position.set(0, -legLen * 0.52, 0.04);
    kneeL.add(footL);

    // —— Right leg ——
    var legRG = new THREE.Group();
    legRG.position.set(hipW * 0.35, 0, 0);
    hipsG.add(legRG);
    joints.legR = legRG;

    var thR = cyl(0.095, 0.08, legLen * 0.55, rlC, "thighR", 12);
    thR.position.y = -legLen * 0.28;
    legRG.add(thR);
    rightLegMesh = thR;

    var kneeR = new THREE.Group();
    kneeR.position.y = -legLen * 0.55;
    legRG.add(kneeR);
    joints.kneeR = kneeR;

    var shR2 = cyl(0.075, 0.06, legLen * 0.5, rlC, "shinR", 12);
    shR2.position.y = -legLen * 0.25;
    kneeR.add(shR2);
    var footR = box(0.11, 0.06, 0.20, rlC, "footR");
    footR.position.set(0, -legLen * 0.52, 0.04);
    kneeR.add(footR);

    // Store rest poses for idle animation
    joints._rest = {
        armLz: armLG.rotation.z,
        armRz: armRG.rotation.z,
        elbowLx: elbowL.rotation.x,
        elbowRx: elbowR.rotation.x
    };

    // Hair: girls get soft realistic hair by default; boys stay bald unless marketplace hair equipped
    try {
        var hs = colors.hairStyle || "";
        var hairCol = colors.hair || "#4a3728";
        var hasShopHair = hs && hs !== "hair_boy_none" && hs !== "none" && hs !== "hair_girl_default" && hs !== "hair_realistic_girl";
        if (hasShopHair && typeof makeAvatarHair === "function") {
            var hair = makeAvatarHair(hairCol, 0, headR * 2, hs);
            if (hair) headG.add(hair);
        } else if (isGirl && typeof makeRealisticHair === "function") {
            var rh = makeRealisticHair("girl", hairCol, headR);
            if (rh) headG.add(rh);
        }
    } catch (eH) {}
}

/** Idle + subtle life for customizer avatars (blocky + realistic) */
window._avatarAnimClock = 0;
window._avatarAnimLast = 0;
function updateAvatarIdleAnimation() {
    if (!avatarCharacterGroup) return;
    var now = (typeof performance !== "undefined" && performance.now) ? performance.now() : Date.now();
    if (!window._avatarAnimLast) window._avatarAnimLast = now;
    var dt = Math.min(0.05, (now - window._avatarAnimLast) / 1000);
    window._avatarAnimLast = now;
    window._avatarAnimClock += dt;
    var t = window._avatarAnimClock;

    var style = (avatarCharacterGroup.userData && avatarCharacterGroup.userData.animStyle) || "blocky";
    var joints = avatarCharacterGroup.userData && avatarCharacterGroup.userData.joints;

    // Global gentle bob
    var breath = Math.sin(t * 1.7) * 0.015;
    var sway = Math.sin(t * 0.65) * 0.025;

    if (style === "realistic" && joints) {
        if (joints.root) {
            joints.root.position.y = breath;
            joints.root.rotation.y = sway * 0.3;
        }
        if (joints.torso) {
            joints.torso.rotation.x = Math.sin(t * 1.7) * 0.02;
            joints.torso.rotation.z = Math.sin(t * 0.9) * 0.015;
        }
        if (joints.head) {
            joints.head.rotation.y = Math.sin(t * 0.5) * 0.06;
            joints.head.rotation.x = Math.sin(t * 1.1) * 0.03;
        }
        var rest = joints._rest || {};
        if (joints.armL) {
            joints.armL.rotation.z = (rest.armLz || 0.12) + Math.sin(t * 1.3) * 0.06;
            joints.armL.rotation.x = Math.sin(t * 1.1 + 0.4) * 0.05;
        }
        if (joints.armR) {
            joints.armR.rotation.z = (rest.armRz || -0.12) - Math.sin(t * 1.3 + 0.5) * 0.06;
            joints.armR.rotation.x = Math.sin(t * 1.1) * 0.05;
        }
        if (joints.elbowL) joints.elbowL.rotation.x = (rest.elbowLx || 0.15) + Math.sin(t * 1.4) * 0.08;
        if (joints.elbowR) joints.elbowR.rotation.x = (rest.elbowRx || 0.15) + Math.sin(t * 1.4 + 0.6) * 0.08;
        if (joints.legL) joints.legL.rotation.x = Math.sin(t * 0.8) * 0.03;
        if (joints.legR) joints.legR.rotation.x = Math.sin(t * 0.8 + Math.PI) * 0.03;
        if (joints.hips) joints.hips.rotation.y = Math.sin(t * 0.55) * 0.02;
    } else {
        // Blocky idle: bob + slight limb sway using primary meshes
        avatarCharacterGroup.position.y = breath;
        if (!window._avatarSpinEnabled) {
            avatarCharacterGroup.rotation.y += Math.sin(t * 0.4) * 0.0008;
        }
        if (leftArmMesh) {
            leftArmMesh.rotation.x = Math.sin(t * 1.25) * 0.08;
            leftArmMesh.rotation.z = Math.sin(t * 0.9) * 0.04;
        }
        if (rightArmMesh) {
            rightArmMesh.rotation.x = Math.sin(t * 1.25 + Math.PI) * 0.08;
            rightArmMesh.rotation.z = -Math.sin(t * 0.9) * 0.04;
        }
        if (leftLegMesh) leftLegMesh.rotation.x = Math.sin(t * 0.85) * 0.04;
        if (rightLegMesh) rightLegMesh.rotation.x = Math.sin(t * 0.85 + Math.PI) * 0.04;
        if (torsoMesh) {
            torsoMesh.scale.y = 1 + Math.sin(t * 1.7) * 0.015;
        }
        if (headMesh) {
            headMesh.rotation.y = Math.sin(t * 0.55) * 0.05;
        }
    }
}
window.updateAvatarIdleAnimation = updateAvatarIdleAnimation;



function rebuildAvatarCustomizerMeshes() {
    if (!avatarCharacterGroup || typeof THREE === "undefined") return false;
    var gender = "boy";
    try {
        if (typeof getAvatarGender === "function") gender = getAvatarGender();
        var gEl = document.querySelector('input[name="avatarGenderCustom"]:checked');
        if (gEl) gender = gEl.value === "girl" ? "girl" : "boy";
    } catch (e) {}
    var colors = {};
    try {
        if (typeof readAvatarColorInputs === "function") colors = readAvatarColorInputs() || {};
    } catch (e2) {}
    colors.gender = gender;
    try {
        var acc = JSON.parse(localStorage.getItem("azoraAccount") || "null");
        if (acc && acc.avatar) {
            colors.hairStyle = acc.avatar.hairStyle || colors.hairStyle;
            colors.hair = acc.avatar.hair || colors.hair;
        }
    } catch (e3) {}

    clearAvatarCharacterMeshes();
    buildBlockyAvatarMeshes(gender, colors);
    try {
        if (typeof applyColorsToMeshes === "function") applyColorsToMeshes(colors);
    } catch (e4) {}
    try {
        if (renderer && scene && camera) renderer.render(scene, camera);
    } catch (e5) {}
    return true;
}

