function sendAturiusMessage() {
    var input = document.getElementById("aturiusInput");
    if (!input) return;
    var text = (input.value || "").trim();
    var att = _aturiusPendingAttach;
    if (!text && !att) return;
    if (text && typeof azoraAutoModerate === "function") {
        var mod = azoraAutoModerate(text);
        if (!mod.ok) {
            alert(mod.reason || "Message blocked by moderation.");
            return;
        }
    }
    input.value = "";
    currentChatFriend = AZORA_AI_ID;
    var me = "Player";
    try {
        me = (typeof getChatSenderId === "function" && getChatSenderId()) || (typeof getMyUsername === "function" && getMyUsername()) || "Player";
    } catch (eM) {}
    var store = ensureActiveAIChat();
    var chat = getActiveAIChat();
    if (!chat.messages) chat.messages = [];
    var msgObj = { from: me, text: text || (att ? ("Shared: " + att.name) : ""), at: Date.now(), isAI: false };
    if (att) {
        // Store lighter attachment copy (dataUrl included for preview test)
        msgObj.attachment = {
            name: att.name,
            type: att.type,
            size: att.size,
            isImage: !!att.isImage,
            width: att.width || 0,
            height: att.height || 0,
            dataUrl: att.dataUrl,
            textPreview: att.textPreview || ""
        };
    }
    chat.messages.push(msgObj);
    chat.updatedAt = Date.now();
    if (!chat.title || /^Chat \d+$/.test(chat.title)) {
        chat.title = (text || (att && att.name) || "Chat").slice(0, 24);
    }
    try {
        for (var i = 0; i < store.chats.length; i++) {
            if (store.chats[i].id === store.activeId) {
                store.chats[i] = chat;
                break;
            }
        }
    } catch (eS) {}
    saveAIChatStore(store);
    aturiusClearPendingAttach();
    try { adjustAturiusFeelingFromMessage(text); } catch (eFeel) {}
    try { aturiusReactToTopic(text); } catch (eTop) {}
    // Start laugh right away on joke / haha messages (don't wait for reply delay)
    try {
        if (aturiusIsJokeRequest(text)) startAturiusLaugh(3500);
    } catch (eLaughNow) {}
    try { paintAturiusFace(); } catch (eFace) {}
    renderAturiusMessages();
    renderAturiusHistoryList();
    scheduleAIReply(text, store.activeId, msgObj.attachment || null);
}

function aturiusReadLastMessage() {
    var chat = getActiveAIChat();
    if (!chat || !chat.messages || !chat.messages.length) return;
    var last = null;
    for (var i = chat.messages.length - 1; i >= 0; i--) {
        if (chat.messages[i].isAI || chat.messages[i].from === AZORA_AI_ID) {
            last = chat.messages[i];
            break;
        }
    }
    if (!last || !last.text) return;
    try {
        if (!window.speechSynthesis) {
            alert("Read to me is not supported on this device.");
            return;
        }
        window.speechSynthesis.cancel();
        var u = new SpeechSynthesisUtterance(String(last.text));
        applyAturiusVoiceToUtterance(u);
        setAturiusMood("talking");
        var shapeIdx = 0;
        var mouthTimer = setInterval(function () {
            // Mouth shapes only — eyes stay on current feeling/mood
            shapeIdx = (shapeIdx + 1) % _aturiusTalkShapes.length;
            _aturiusMouthShape = _aturiusTalkShapes[shapeIdx];
            try { paintAturiusFace(); } catch (e) {}
        }, 120);
        u.onend = function () {
            clearInterval(mouthTimer);
            _aturiusMouthShape = "smile";
            setAturiusMood("idle");
            try { paintAturiusFace(); } catch (e2) {}
        };
        u.onerror = function () {
            clearInterval(mouthTimer);
            _aturiusMouthShape = "smile";
            setAturiusMood("idle");
        };
        window.speechSynthesis.speak(u);
    } catch (e) {
        alert("Could not start voice reading.");
    }
}

function setAturiusMood(mood) {
    _aturiusMood = mood || "idle";
    var lab = document.getElementById("aturiusMoodLabel");
    if (lab) {
        if (_aturiusMood === "thinking") lab.textContent = "Thinking…";
        else if (_aturiusMood === "talking") lab.textContent = "Speaking…";
        else if (_aturiusMood === "laughing") lab.textContent = "Laughing!";
        else lab.textContent = "Looking at you";
    }
    try { paintAturiusFace(); } catch (e) {}
}

/** Detect joke / laugh requests (flexible phrasing) */
function aturiusIsJokeRequest(text) {
    var t = String(text || "").toLowerCase().trim();
    if (!t) return false;
    if (/\b(haha|hahaha|hehe|lol|lmao|rofl)\b/.test(t)) return true;
    if (/\b(joke|jokes|funny|hilarious)\b/.test(t)) return true;
    if (/\b(make me laugh|tell me a joke|give me a joke|make me a joke|say a joke|another joke)\b/.test(t)) return true;
    if (/\b(tell|give|make|say)\b.{0,20}\bjoke\b/.test(t)) return true;
    return false;
}
window.aturiusIsJokeRequest = aturiusIsJokeRequest;

/** Big laugh: look around hard + squash/stretch bounce */
function startAturiusLaugh(ms) {
    try {
        // Make sure 3D is up if panel is open
        try { initAturius3D(); } catch (eInit) {}
        var dur = Math.max(1500, Number(ms) || 3200);
        _aturiusLaughUntil = Date.now() + dur;
        _aturiusMood = "laughing";
        _aturiusLookDir = "wander";
        _aturiusTopicEye = "happy";
        _aturiusEyeStyle = "happy";
        _aturiusMouthShape = "smileBig";
        try { setAturiusFeeling("happy"); } catch (eF) {}
        var lab = document.getElementById("aturiusMoodLabel");
        if (lab) lab.textContent = "Laughing!";
        try { paintAturiusFace(); } catch (e) {}
        // After laugh ends, return to idle
        setTimeout(function () {
            if (Date.now() >= (_aturiusLaughUntil || 0)) {
                if (_aturiusMood === "laughing") {
                    _aturiusMood = "idle";
                    var lab2 = document.getElementById("aturiusMoodLabel");
                    if (lab2) lab2.textContent = "Looking at you";
                }
                if (_aturiusSphere) {
                    try {
                        _aturiusSphere.scale.set(1, 1, 1);
                        _aturiusSphere.position.y = 0;
                    } catch (eS) {}
                }
                if (_aturiusFaceMesh) {
                    try { _aturiusFaceMesh.scale.set(1, 1, 1); } catch (eF2) {}
                }
                try { paintAturiusFace(); } catch (eP) {}
            }
        }, dur + 80);
    } catch (err) {
        console.warn("[Aturius] laugh failed", err);
    }
}
window.startAturiusLaugh = startAturiusLaugh;

function equipAturiusCosmetic(kind, id) {
    var cos = getAturiusCosmetics();
    if (kind === "face") {
        if (!ownsItem(id) && id !== "aturius_face_default") {
            showAzoraToast("You don't own that face yet — check the Aturius AI marketplace tab.");
            return;
        }
        cos.face = id || "aturius_face_default";
    } else if (kind === "hat") {
        if (!ownsItem(id) && id !== "aturius_hat_none") {
            showAzoraToast("You don't own that hat yet.");
            return;
        }
        cos.hat = id || "aturius_hat_none";
    }
    saveAturiusCosmetics(cos);
    showAzoraToast("Equipped!");
}
