function paintAturiusFace() {
    if (!_aturiusFaceTex || !_aturiusFaceTex.image) return;
    var c = _aturiusFaceTex.image;
    var ctx = c.getContext("2d");
    var w = c.width, h = c.height;
    ctx.clearRect(0, 0, w, h);

    var thinking = _aturiusMood === "thinking";
    var talking = _aturiusMood === "talking";
    var laughing = _aturiusMood === "laughing" || Date.now() < (_aturiusLaughUntil || 0);
    var now = Date.now();
    var blinking = now < (_aturiusBlinkUntil || 0);

    // Equipped animated face style (marketplace)
    var cosFace = "aturius_face_default";
    try { cosFace = getAturiusCosmetics().face || "aturius_face_default"; } catch (eCF) {}

    // Eyes: feeling wins for sad/upset; otherwise topic eyes (entertaining)
    var feeling = _aturiusFeeling || getAturiusFeeling();
    var eyeStyle = _aturiusTopicEye || _aturiusEyeStyle || "normal";
    if (feeling === "sad") eyeStyle = "sad";
    else if (feeling === "upset") eyeStyle = "mad";
    else if (feeling === "happy" && (eyeStyle === "normal" || !eyeStyle)) eyeStyle = "happy";
    // Marketplace face styles
    if (cosFace === "aturius_face_happy" && feeling !== "sad" && feeling !== "upset") eyeStyle = "happy";
    if (cosFace === "aturius_face_cool" && feeling !== "sad" && feeling !== "upset") eyeStyle = "cool";
    if (cosFace === "aturius_face_wink" && feeling !== "sad" && feeling !== "upset" && !blinking) eyeStyle = "wink";
    if (cosFace === "aturius_face_spark" && feeling !== "sad" && feeling !== "upset") eyeStyle = "spark";
    // While talking/laughing and not sad/upset → happy smile-eyes (unless cool/wink equipped)
    if ((talking || laughing) && feeling !== "sad" && feeling !== "upset" && cosFace !== "aturius_face_cool" && cosFace !== "aturius_face_wink") {
        eyeStyle = "happy";
    }

    // Talking: smile cycle. Laughing: big smile. Idle: smile or frown by mood.
    var mouthShape = talking ? (_aturiusMouthShape || "smileBig") : (thinking ? "line" : "smile");
    if (laughing) mouthShape = (now % 400 < 200) ? "smileBig" : "oval";
    if (!talking && !thinking && !laughing && (feeling === "sad" || feeling === "upset")) {
        mouthShape = "frown";
    }
    if (talking && feeling !== "sad" && feeling !== "upset") {
        if (mouthShape === "line") mouthShape = "smile";
    }

    ctx.fillStyle = "#111111";
    ctx.strokeStyle = "#111111";
    ctx.lineCap = "round";
    ctx.lineJoin = "round";

    // ---- EYES (clean cartoon ovals — no big shiny dots) ----
    // Even spacing; same size; soft look so they don't feel "googly"
    var lookShiftX = 0, lookShiftY = 0;
    if (_aturiusLookDir === "left") lookShiftX = -w * 0.03;
    else if (_aturiusLookDir === "right") lookShiftX = w * 0.03;
    else if (_aturiusLookDir === "up") lookShiftY = -h * 0.028;
    else if (_aturiusLookDir === "down") lookShiftY = h * 0.022;

    // Slightly closer together + a bit smaller = less uncanny
    var lx = w * 0.36 + lookShiftX;
    var rx = w * 0.64 + lookShiftX;
    var eyeY = h * 0.40 + lookShiftY;
    var eyeRx = w * 0.072;
    var eyeRy = h * 0.082;

    function drawSolidEye(ex, ey, rxE, ryE, tilt) {
        ctx.fillStyle = "#111111";
        ctx.beginPath();
        ctx.ellipse(ex, ey, rxE, ryE, tilt || 0, 0, Math.PI * 2);
        ctx.fill();
        // Tiny soft highlight (very small — not big "googly" dots)
        ctx.fillStyle = "rgba(255,255,255,0.55)";
        ctx.beginPath();
        ctx.ellipse(ex - rxE * 0.28, ey - ryE * 0.32, rxE * 0.22, ryE * 0.22, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#111111";
    }

    if (blinking) {
        ctx.strokeStyle = "#111111";
        ctx.lineWidth = Math.max(5, w * 0.028);
        ctx.beginPath();
        ctx.moveTo(lx - eyeRx, eyeY);
        ctx.lineTo(lx + eyeRx, eyeY);
        ctx.moveTo(rx - eyeRx, eyeY);
        ctx.lineTo(rx + eyeRx, eyeY);
        ctx.stroke();
    } else if (eyeStyle === "happy") {
        // Closed happy arcs (no filled dots)
        ctx.strokeStyle = "#111111";
        ctx.lineWidth = Math.max(6, w * 0.038);
        ctx.beginPath();
        ctx.moveTo(lx - eyeRx, eyeY + eyeRy * 0.15);
        ctx.quadraticCurveTo(lx, eyeY - eyeRy * 1.05, lx + eyeRx, eyeY + eyeRy * 0.15);
        ctx.moveTo(rx - eyeRx, eyeY + eyeRy * 0.15);
        ctx.quadraticCurveTo(rx, eyeY - eyeRy * 1.05, rx + eyeRx, eyeY + eyeRy * 0.15);
        ctx.stroke();
    } else if (eyeStyle === "wink") {
        drawSolidEye(lx, eyeY, eyeRx, eyeRy, 0);
        ctx.strokeStyle = "#111111";
        ctx.lineWidth = Math.max(6, w * 0.038);
        ctx.beginPath();
        ctx.moveTo(rx - eyeRx, eyeY + eyeRy * 0.1);
        ctx.quadraticCurveTo(rx, eyeY - eyeRy * 0.9, rx + eyeRx, eyeY + eyeRy * 0.1);
        ctx.stroke();
    } else if (eyeStyle === "cool") {
        // Half-lidded ovals
        drawSolidEye(lx, eyeY + eyeRy * 0.15, eyeRx * 1.05, eyeRy * 0.55, 0);
        drawSolidEye(rx, eyeY + eyeRy * 0.15, eyeRx * 1.05, eyeRy * 0.55, 0);
    } else if (eyeStyle === "spark") {
        drawSolidEye(lx, eyeY, eyeRx, eyeRy, 0);
        drawSolidEye(rx, eyeY, eyeRx, eyeRy, 0);
        // Sparkle star accents
        ctx.fillStyle = "rgba(255,255,255,0.9)";
        var sp = (Math.floor(now / 180) % 2 === 0);
        if (sp) {
            ctx.beginPath();
            ctx.arc(lx + eyeRx * 0.9, eyeY - eyeRy * 1.1, w * 0.012, 0, Math.PI * 2);
            ctx.arc(rx - eyeRx * 0.9, eyeY - eyeRy * 1.15, w * 0.01, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.fillStyle = "#111111";
    } else if (eyeStyle === "curious" || eyeStyle === "lookUp") {
        drawSolidEye(lx, eyeY - h * 0.012, eyeRx * 1.02, eyeRy * 1.12, 0);
        drawSolidEye(rx, eyeY - h * 0.012, eyeRx * 1.02, eyeRy * 1.12, 0);
    } else if (eyeStyle === "lookLeft") {
        drawSolidEye(lx - w * 0.015, eyeY, eyeRx, eyeRy, 0);
        drawSolidEye(rx - w * 0.015, eyeY, eyeRx, eyeRy, 0);
    } else if (eyeStyle === "lookRight") {
        drawSolidEye(lx + w * 0.015, eyeY, eyeRx, eyeRy, 0);
        drawSolidEye(rx + w * 0.015, eyeY, eyeRx, eyeRy, 0);
    } else if (eyeStyle === "sad") {
        drawSolidEye(lx, eyeY + h * 0.008, eyeRx * 0.85, eyeRy * 1.0, 0.28);
        drawSolidEye(rx, eyeY + h * 0.008, eyeRx * 0.85, eyeRy * 1.0, -0.28);
    } else if (eyeStyle === "mad") {
        drawSolidEye(lx, eyeY, eyeRx * 0.85, eyeRy * 1.0, 0.32);
        drawSolidEye(rx, eyeY, eyeRx * 0.85, eyeRy * 1.0, -0.32);
        ctx.strokeStyle = "#111111";
        ctx.lineWidth = Math.max(5, w * 0.028);
        ctx.beginPath();
        ctx.moveTo(lx - eyeRx, eyeY - eyeRy * 1.15);
        ctx.lineTo(lx + eyeRx * 0.55, eyeY - eyeRy * 0.45);
        ctx.moveTo(rx + eyeRx, eyeY - eyeRy * 1.15);
        ctx.lineTo(rx - eyeRx * 0.55, eyeY - eyeRy * 0.45);
        ctx.stroke();
    } else {
        // Default calm eyes — matching pair, soft highlight
        drawSolidEye(lx, eyeY, eyeRx, eyeRy, 0);
        drawSolidEye(rx, eyeY, eyeRx, eyeRy, 0);
    }

    // ---- MOUTH ----
    var mouthY = h * 0.60;
    ctx.lineWidth = Math.max(7, w * 0.045);
    ctx.fillStyle = "#111111";
    ctx.strokeStyle = "#111111";

    // Mouth shapes match reference: solid circle, wide oval, thick smile curve
    if (mouthShape === "line") {
        ctx.beginPath();
        ctx.moveTo(w * 0.36, mouthY);
        ctx.lineTo(w * 0.64, mouthY);
        ctx.stroke();
    } else if (mouthShape === "o") {
        // Small solid circle (like reference dot)
        ctx.beginPath();
        ctx.arc(w * 0.5, mouthY + h * 0.02, w * 0.07, 0, Math.PI * 2);
        ctx.fill();
    } else if (mouthShape === "oval") {
        // Wide solid horizontal oval (like reference oval)
        ctx.beginPath();
        ctx.ellipse(w * 0.5, mouthY + h * 0.02, w * 0.16, h * 0.055, 0, 0, Math.PI * 2);
        ctx.fill();
    } else if (mouthShape === "openTop") {
        ctx.beginPath();
        ctx.ellipse(w * 0.5, mouthY, w * 0.12, h * 0.08, 0, 0, Math.PI * 2);
        ctx.fill();
    } else if (mouthShape === "openBottom") {
        ctx.beginPath();
        ctx.ellipse(w * 0.5, mouthY + h * 0.03, w * 0.14, h * 0.09, 0, 0, Math.PI * 2);
        ctx.fill();
    } else if (mouthShape === "frown") {
        // Mood: sad/upset — inverted curve
        ctx.lineWidth = Math.max(10, w * 0.055);
        ctx.beginPath();
        ctx.moveTo(w * 0.30, mouthY + h * 0.08);
        ctx.quadraticCurveTo(w * 0.5, mouthY - h * 0.08, w * 0.70, mouthY + h * 0.08);
        ctx.stroke();
    } else if (mouthShape === "smileBig") {
        // Thick filled smile arc (reference smile, bigger)
        ctx.lineWidth = Math.max(14, w * 0.07);
        ctx.beginPath();
        ctx.moveTo(w * 0.26, mouthY);
        ctx.quadraticCurveTo(w * 0.5, mouthY + h * 0.2, w * 0.74, mouthY);
        ctx.stroke();
    } else {
        // Default smile curve (reference smile)
        ctx.lineWidth = Math.max(12, w * 0.06);
        ctx.beginPath();
        ctx.moveTo(w * 0.28, mouthY);
        ctx.quadraticCurveTo(w * 0.5, mouthY + h * 0.16, w * 0.72, mouthY);
        ctx.stroke();
    }
    _aturiusFaceTex.needsUpdate = true;
}

function initAturius3D() {
    var canvas = document.getElementById("aturiusCanvas");
    if (!canvas || typeof THREE === "undefined") return;

    // Always rebuild face paint if already initialized
    if (_aturiusRenderer && _aturiusSphere) {
        try { paintAturiusFace(); } catch (e) {}
        return;
    }

    var w = canvas.clientWidth || canvas.width || 280;
    var h = canvas.clientHeight || canvas.height || 280;
    if (w < 50) w = 280;
    if (h < 50) h = 280;
    canvas.width = w;
    canvas.height = h;

    _aturiusRenderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true });
    _aturiusRenderer.setSize(w, h, false);
    _aturiusRenderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    _aturiusRenderer.setClearColor(0x000000, 0);

    _aturiusScene = new THREE.Scene();
    // Fixed camera — never moves
    _aturiusCamera = new THREE.PerspectiveCamera(40, w / h, 0.1, 100);
    _aturiusCamera.position.set(0, 0, 3.4);
    _aturiusCamera.lookAt(0, 0, 0);

    var light = new THREE.DirectionalLight(0xffffff, 1.1);
    light.position.set(2, 3, 5);
    _aturiusScene.add(light);
    _aturiusScene.add(new THREE.AmbientLight(0xffffff, 0.65));

    // Yellow sphere body
    var geo = new THREE.SphereGeometry(1, 48, 48);
    var mat = new THREE.MeshStandardMaterial({
        color: 0xffcc00,
        roughness: 0.4,
        metalness: 0.05
    });
    _aturiusSphere = new THREE.Mesh(geo, mat);
    _aturiusScene.add(_aturiusSphere);

    // Face sits IN FRONT of the sphere (not on the surface) so it never disappears
    var faceCanvas = document.createElement("canvas");
    faceCanvas.width = 512;
    faceCanvas.height = 512;
    _aturiusFaceTex = new THREE.CanvasTexture(faceCanvas);
    _aturiusFaceTex.minFilter = THREE.LinearFilter;
    _aturiusFaceTex.magFilter = THREE.LinearFilter;
    var faceMat = new THREE.MeshBasicMaterial({
        map: _aturiusFaceTex,
        transparent: true,
        depthTest: true,
        depthWrite: false,
        side: THREE.DoubleSide
    });
    _aturiusFaceMesh = new THREE.Mesh(new THREE.PlaneGeometry(1.35, 1.35), faceMat);
    // Position toward the camera, slightly in front of the sphere surface
    _aturiusFaceMesh.position.set(0, 0.05, 1.25);
    _aturiusScene.add(_aturiusFaceMesh); // NOT a child of the sphere
    paintAturiusFace();
    try { applyAturiusCosmeticsToScene(); } catch (eCos) {}

    // Load saved feeling for eyes
    try {
        _aturiusFeeling = getAturiusFeeling();
        setAturiusFeeling(_aturiusFeeling);
    } catch (eF) {}
    _aturiusNextBlink = Date.now() + 2000 + Math.random() * 3000;

    function tick(t) {
        _aturiusAnimId = requestAnimationFrame(tick);
        if (!_aturiusSphere || !_aturiusRenderer) return;
        _aturiusLookT = (t || 0) * 0.001;
        var now = Date.now();
        // Natural blink every ~2.5–5.5s (eyes close briefly)
        if (now >= (_aturiusNextBlink || 0) && now >= (_aturiusBlinkUntil || 0)) {
            _aturiusBlinkUntil = now + 120 + Math.random() * 60;
            _aturiusNextBlink = now + 2500 + Math.random() * 3000;
            try { paintAturiusFace(); } catch (eB) {}
        } else if (_aturiusBlinkUntil && now >= _aturiusBlinkUntil && now < _aturiusBlinkUntil + 40) {
            _aturiusBlinkUntil = 0;
            try { paintAturiusFace(); } catch (eB2) {}
        }
        // Look direction by topic (entertaining glances)
        var lookY = 0, lookX = 0;
        var dir = _aturiusLookDir || "wander";
        var isLaughing = _aturiusMood === "laughing" || now < (_aturiusLaughUntil || 0);

        if (isLaughing) {
            // HARD look: up, down, left, right — not slight
            var phase = (_aturiusLookT * 3.2) % (Math.PI * 2);
            lookY = Math.sin(phase) * 0.85;           // side to side — strong
            lookX = Math.cos(phase * 1.3) * 0.55;     // up / down — strong
            // Squash & stretch bounce: flatten then expand
            var bounce = Math.sin(_aturiusLookT * 10);
            var squashY = 1 + bounce * 0.18;   // expand up
            var squashX = 1 - bounce * 0.14;   // flatten sideways when tall
            _aturiusSphere.scale.set(squashX, squashY, squashX);
            _aturiusSphere.position.y = Math.abs(bounce) * 0.12; // hop up a bit
            // Happy laugh face (throttle paint so it stays smooth)
            if (Math.floor(_aturiusLookT * 8) % 2 === 0) {
                _aturiusMouthShape = "smileBig";
            } else {
                _aturiusMouthShape = "oval";
            }
            if (Math.floor(now / 80) !== Math.floor((now - 16) / 80)) {
                try { paintAturiusFace(); } catch (eL) {}
            }
        } else {
            // Reset scale when not laughing
            _aturiusSphere.scale.set(1, 1, 1);
            _aturiusSphere.position.y = 0;

            if (dir === "left") { lookY = -0.35; lookX = 0.05; }
            else if (dir === "right") { lookY = 0.35; lookX = 0.05; }
            else if (dir === "up") { lookX = -0.28; lookY = 0; }
            else if (dir === "down") { lookX = 0.22; lookY = 0; }
            else if (dir === "center") { lookX = 0; lookY = 0; }
            else {
                lookY = Math.sin(_aturiusLookT * 0.7) * 0.28;
                lookX = Math.sin(_aturiusLookT * 0.45) * 0.12;
            }
            if (_aturiusMood === "thinking") {
                lookY *= 0.6;
                lookX = 0.1 + Math.sin(_aturiusLookT) * 0.08;
            } else if (_aturiusMood === "talking") {
                lookY *= 0.45;
                lookX *= 0.4;
            }
        }

        _aturiusSphere.rotation.y = lookY;
        _aturiusSphere.rotation.x = lookX;
        // Face follows look a bit but still faces camera
        if (_aturiusFaceMesh) {
            _aturiusFaceMesh.position.x = lookY * 0.35 + Math.sin(_aturiusLookT * 0.5) * 0.02;
            _aturiusFaceMesh.position.y = 0.05 - lookX * 0.25 + Math.sin(_aturiusLookT * 0.35) * 0.02 + (isLaughing ? _aturiusSphere.position.y : 0);
            if (isLaughing) {
                // Face squashes with the body a little
                var b = Math.sin(_aturiusLookT * 10);
                _aturiusFaceMesh.scale.set(1 - b * 0.08, 1 + b * 0.1, 1);
            } else {
                _aturiusFaceMesh.scale.set(1, 1, 1);
            }
            _aturiusFaceMesh.lookAt(_aturiusCamera.position);
        }
        _aturiusRenderer.render(_aturiusScene, _aturiusCamera);
    }
    tick(0);
}

