// ============================================================
// Firebase real-time presence (online tracking)
// ============================================================
var _presenceHeartbeat = null;
var _presenceLastWrite = 0;

function presenceSafeUser(name) {
    return String(name || "").trim().toLowerCase().replace(/[.#$\[\]]/g, "_").slice(0, 48);
}

function writeFirebasePresence(status) {
    try {
        var acc = typeof getActiveAccount === "function" ? getActiveAccount() : null;
        var logged = localStorage.getItem("loggedIn");
        if (!acc || !acc.username || acc.isGuest || logged !== "true") return;
        var now = Date.now();
        // Always keep a fresh local mirror so same-device tabs / offline viewers see you
        var uname = acc.username;
        var safe = presenceSafeUser(uname);
        var isOff = status === "offline";
        var payload = {
            username: uname,
            userId: acc.userId || "",
            status: isOff ? "offline" : "online",
            online: !isOff,
            lastSeen: now,
            updatedAt: now
        };
        try {
            var all = JSON.parse(localStorage.getItem("azoraPresenceCache") || "{}");
            all[safe] = payload;
            localStorage.setItem("azoraPresenceCache", JSON.stringify(all));
        } catch (eL) {}
        // Cloud write (throttled while online)
        if (typeof AZORA_CLOUD === "undefined" || !AZORA_CLOUD.firebaseUrl) return;
        var base = String(AZORA_CLOUD.firebaseUrl || "").replace(/\/$/, "");
        if (!base) return;
        if (!isOff && now - _presenceLastWrite < 4000) return;
        _presenceLastWrite = now;
        fetch(base + "/azoraPresence/" + encodeURIComponent(safe) + ".json", {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload)
        }).catch(function () {});
    } catch (e) {}
}

function fetchFirebasePresence(username, cb) {
    cb = cb || function () {};
    try {
        var safe = presenceSafeUser(username);
        var cached = null;
        try {
            var all = JSON.parse(localStorage.getItem("azoraPresenceCache") || "{}");
            cached = all[safe] || null;
        } catch (eC) {}
        if (typeof AZORA_CLOUD === "undefined" || !AZORA_CLOUD.firebaseUrl) {
            cb(cached);
            return;
        }
        var base = String(AZORA_CLOUD.firebaseUrl || "").replace(/\/$/, "");
        if (!base) {
            cb(cached);
            return;
        }
        fetch(base + "/azoraPresence/" + encodeURIComponent(safe) + ".json?ts=" + Date.now())
            .then(function (r) {
                if (!r.ok) throw new Error("HTTP " + r.status);
                return r.json();
            })
            .then(function (data) {
                // Accept any object that has lastSeen / updatedAt (username field optional)
                if (data && typeof data === "object" && (data.lastSeen || data.updatedAt || data.username || data.online != null)) {
                    if (!data.username) data.username = username;
                    if (!data.lastSeen && data.updatedAt) data.lastSeen = data.updatedAt;
                    try {
                        var all = JSON.parse(localStorage.getItem("azoraPresenceCache") || "{}");
                        all[safe] = data;
                        localStorage.setItem("azoraPresenceCache", JSON.stringify(all));
                    } catch (e) {}
                    cb(data);
                } else {
                    cb(cached);
                }
            })
            .catch(function () { cb(cached); });
    } catch (e) { cb(null); }
}

function startPresenceHeartbeat() {
    try { if (_presenceHeartbeat) clearInterval(_presenceHeartbeat); } catch (e) {}
    writeFirebasePresence("online");
    // Faster heartbeat so "live" online is nearly real-time (~20s window)
    _presenceHeartbeat = setInterval(function () {
        var logged = localStorage.getItem("loggedIn");
        if (logged !== "true") return;
        var me = typeof getMyUsername === "function" ? getMyUsername() : null;
        if (!me) return;
        writeFirebasePresence("online");
    }, 20000);
    try {
        window.addEventListener("beforeunload", function () {
            writeFirebasePresence("offline");
        });
        document.addEventListener("visibilitychange", function () {
            if (document.visibilityState === "visible") {
                writeFirebasePresence("online");
            }
        });
    } catch (e2) {}
}

window.writeFirebasePresence = writeFirebasePresence;
window.fetchFirebasePresence = fetchFirebasePresence;
window.startPresenceHeartbeat = startPresenceHeartbeat;

// --- Notifications ---
function getNotifications(username) {
    try {
        var all = JSON.parse(localStorage.getItem("azoraNotifications") || "{}");
        return all[username] || [];
    } catch (e) { return []; }
}

function saveNotifications(username, list) {
    var all = {};
    try { all = JSON.parse(localStorage.getItem("azoraNotifications") || "{}"); } catch (e) {}
    all[username] = list.slice(0, 50); // keep last 50
    localStorage.setItem("azoraNotifications", JSON.stringify(all));
}

function pushNotification(toUsername, message, type, meta) {
    if (!toUsername) return;
    try { playAzoraSfx("notification"); } catch (e) {}
    var notif = {
        id: "n_" + Date.now() + "_" + Math.random().toString(36).slice(2, 6),
        message: message,
        type: type || "info",
        meta: meta || null,
        read: false,
        at: Date.now()
    };
    var list = getNotifications(toUsername);
    list.unshift(notif);
    saveNotifications(toUsername, list);
    try { pushNotifToCloud(toUsername, notif); } catch (e) {}
    // Update badge if it's me
    if (toUsername === getMyUsername()) updateNotifBadge();
}

function updateNotifBadge() {
    var me = getMyUsername();
    var badge = document.getElementById("notifBadge");
    if (!badge || !me) return;
    var list = getNotifications(me);
    var unread = list.filter(function (n) { return !n.read; }).length;
    if (unread > 0) {
        badge.style.display = "flex";
        badge.textContent = unread > 9 ? "9+" : String(unread);
    } else {
        badge.style.display = "none";
    }
}

function toggleNotifPanel() {
    try {
        var _nm = typeof getMyUsername === "function" ? getMyUsername() : null;
        if (_nm && typeof pullNotifsFromCloud === "function") {
            pullNotifsFromCloud(_nm, function () {
                try { if (typeof renderNotifications === "function") renderNotifications(); } catch (e) {}
                try { if (typeof updateNotifBadge === "function") updateNotifBadge(); } catch (e) {}
            });
        }
    } catch (e) {}

    var ov = document.getElementById("notifOverlay");
    if (ov.style.display === "flex") {
        closeNotifPanel();
    } else {
        openNotifPanel();
    }
}

function openNotifPanel() {
    if (localStorage.getItem("loggedIn") === "guest") {
        alert("Guests don't receive notifications. Create an account to stay updated!");
        return;
    }
    if (localStorage.getItem("loggedIn") !== "true") {
        alert("Please log in to see notifications!");
        return;
    }
    document.getElementById("notifOverlay").style.display = "flex";
    renderNotifList();
    try {
        var me = getMyUsername();
        if (me && typeof pullNotifsFromCloud === "function") {
            pullNotifsFromCloud(me, function () { renderNotifList(); updateNotifBadge(); });
        }
        if (me && typeof pullIncomingFriendRequests === "function") {
            pullIncomingFriendRequests(me, function () {});
        }
    } catch (e) {}
}

function closeNotifPanel() {
    document.getElementById("notifOverlay").style.display = "none";
}

function renderNotifList() {
    var listEl = document.getElementById("notifList");
    if (!listEl) return;
    var me = getMyUsername();
    var list = getNotifications(me);
    if (list.length === 0) {
        listEl.innerHTML = '<div class="notif-empty">No notifications yet.</div>';
        return;
    }
    listEl.innerHTML = "";
    var isOwner = false;
    try { isOwner = typeof isAzoraOwner === "function" && isAzoraOwner(); } catch (eO) {}
    list.forEach(function (n) {
        var div = document.createElement("div");
        div.className = "notif-item" + (n.read ? "" : " unread") + (n.type === "report" ? " notif-report" : "");
        var timeStr = new Date(n.at).toLocaleString();
        var html = escapeHtml(n.message) + '<span class="notif-time">' + timeStr + '</span>';
        if (isOwner && n.type === "report" && n.meta && n.meta.reported) {
            var reported = String(n.meta.reported).replace(/'/g, "");
            html += '<div class="notif-report-actions">' +
                '<button type="button" class="notif-btn-ban" onclick="event.stopPropagation();openOwnerModFromReport(\'' + reported + '\',\'ban\')">Ban user</button>' +
                '<button type="button" class="notif-btn-term" onclick="event.stopPropagation();openOwnerModFromReport(\'' + reported + '\',\'termination\')">Terminate</button>' +
                '</div>';
        }
        div.innerHTML = html;
        div.onclick = function () {
            n.read = true;
            saveNotifications(me, list);
            updateNotifBadge();
            renderNotifList();
        };
        listEl.appendChild(div);
    });
}

function openOwnerModFromReport(username, mode) {
    try { closeNotifPanel(); } catch (e) {}
    if (typeof openOwnerModConsole === "function") {
        openOwnerModConsole(username);
    }
    if (typeof setOwnerModMode === "function") {
        setOwnerModMode(mode === "termination" ? "termination" : "ban");
    }
    var input = document.getElementById("omUsername");
    if (input) input.value = username || "";
}
window.openOwnerModFromReport = openOwnerModFromReport;


function markAllNotifsRead() {
    var me = getMyUsername();
    var list = getNotifications(me);
    list.forEach(function (n) { n.read = true; });
    saveNotifications(me, list);
    updateNotifBadge();
    renderNotifList();
}

