/** Format coins for display — up to 1 decimal (realistic economy) */
function formatCoins(n) {
    n = Number(n) || 0;
    if (Math.abs(n - Math.round(n)) < 0.0005) return String(Math.round(n));
    // Show 2 decimals for small amounts (0.05, 0.12), else 1
    var r2 = Math.round(n * 100) / 100;
    if (Math.abs(r2) < 1) return r2.toFixed(2).replace(/0$/, "").replace(/\.0$/, "");
    if (Math.abs(r2 * 10 - Math.round(r2 * 10)) < 0.001) return (Math.round(n * 10) / 10).toFixed(1);
    return r2.toFixed(2);
}


/** —— Azora economy: per-account coins, platform cut, pending sales —— */
var AZORA_PLATFORM_FEE = 0.10; // 10% to official Azora, 90% to seller (only at 0.10+)
var AZORA_TAX_FREE_MAX = 0.09; // 0.05–0.09 (and below 0.10) are tax-free
var AZORA_SPLIT_MIN = 0.10;    // 90/10 split activates at exactly 0.10 AzoraCoins
var AZORA_OWNER_STARTING_COINS = 2642.62;
/** Official global launch date for platform-age airdrops (UTC). */
var AZORA_PLATFORM_LAUNCH_MS = Date.UTC(2026, 1, 1); // Feb 1, 2026
var AZORA_AIRDROP_EVERY_MONTHS = 5;
var AZORA_AIRDROP_AMOUNT = 0.50;

/**
 * Sale split rules:
 * - price < 0.10  → tax-free (creator 100%, platform 0)
 * - price >= 0.10 → 90% creator, 10% Azora
 * Example: 0.10 sale → seller 0.09, Azora 0.01
 */
function computeSaleSplit(price) {
    price = Math.round((Number(price) || 0) * 1000) / 1000;
    if (price <= 0) return { price: 0, fee: 0, seller: 0, taxFree: true };
    if (price < AZORA_SPLIT_MIN) {
        return { price: price, fee: 0, seller: price, taxFree: true };
    }
    var fee = Math.round(price * AZORA_PLATFORM_FEE * 1000) / 1000;
    // Keep fee readable at 2–3 decimals; never zero once split is active
    if (fee < 0.01) fee = 0.01;
    if (fee > price) fee = price;
    var seller = Math.round((price - fee) * 1000) / 1000;
    return { price: price, fee: fee, seller: seller, taxFree: false };
}

function describeSaleSplit(price) {
    var s = computeSaleSplit(price);
    if (s.taxFree) return "Tax-free sale — creator keeps 100%";
    return "90/10 split — creator " + (typeof formatCoins === "function" ? formatCoins(s.seller) : s.seller) +
        " · Azora " + (typeof formatCoins === "function" ? formatCoins(s.fee) : s.fee);
}

/** Whole months since official platform launch. */
function getPlatformAgeMonths() {
    try {
        var launch = new Date(AZORA_PLATFORM_LAUNCH_MS);
        var now = new Date();
        var months = (now.getUTCFullYear() - launch.getUTCFullYear()) * 12 +
            (now.getUTCMonth() - launch.getUTCMonth());
        if (now.getUTCDate() < launch.getUTCDate()) months -= 1;
        return Math.max(0, months);
    } catch (e) { return 0; }
}

/** How many 5-month airdrop milestones have fully elapsed. */
function getAirdropMilestoneCount() {
    return Math.floor(getPlatformAgeMonths() / AZORA_AIRDROP_EVERY_MONTHS);
}

function getAirdropsClaimedCount() {
    try {
        var n = parseInt(localStorage.getItem("azoraAirdropsClaimed") || "0", 10);
        return isNaN(n) ? 0 : Math.max(0, n);
    } catch (e) { return 0; }
}

function setAirdropsClaimedCount(n) {
    try { localStorage.setItem("azoraAirdropsClaimed", String(Math.max(0, n | 0))); } catch (e) {}
}

/**
 * Global platform airdrop: every 5 months of platform age,
 * every player receives +0.50 AzoraCoins (auto on load/login).
 */
function checkPlatformAirdrop() {
    try {
        var logged = localStorage.getItem("loggedIn");
        if (logged !== "true" && logged !== "guest") return;
        var due = getAirdropMilestoneCount();
        var claimed = getAirdropsClaimedCount();
        if (due <= claimed) return;
        var missed = due - claimed;
        var total = Math.round(missed * AZORA_AIRDROP_AMOUNT * 1000) / 1000;
        if (total > 0 && typeof addCoins === "function") {
            addCoins(total);
            var msg = missed === 1
                ? ("+0.50 AzoraCoins platform airdrop! 🎉 (" + due + "× 5-month milestone)")
                : ("+" + (typeof formatCoins === "function" ? formatCoins(total) : total) +
                    " AzoraCoins from " + missed + " platform airdrops! 🎉");
            if (typeof showAzoraToast === "function") showAzoraToast(msg);
        }
        setAirdropsClaimedCount(due);
    } catch (e) {
        console.warn("[Azora] airdrop", e);
    }
}

window.computeSaleSplit = computeSaleSplit;
window.describeSaleSplit = describeSaleSplit;
window.checkPlatformAirdrop = checkPlatformAirdrop;
window.getPlatformAgeMonths = getPlatformAgeMonths;

function getActiveAccount() {
    try {
        if (localStorage.getItem("loggedIn") !== "true") return null;
        return JSON.parse(localStorage.getItem("azoraAccount") || "null");
    } catch (e) { return null; }
}

function persistActiveAccount(acc) {
    if (!acc) return;
    try {
        localStorage.setItem("azoraAccount", JSON.stringify(acc));
        var map = getSavedAccounts();
        var key = acc.username || "";
        if (key) {
            map[key] = acc;
            // also store under exact owner name
            if (acc.isOwner || (typeof isOwnerUsername === "function" && isOwnerUsername(acc.username))) {
                map[AZORA_OWNER_NAME] = acc;
            }
            saveSavedAccounts(map);
        }
    } catch (e) {}
}

function getSalesLedger() {
    try {
        var list = JSON.parse(localStorage.getItem("azoraSalesLedger") || "[]");
        return Array.isArray(list) ? list : [];
    } catch (e) { return []; }
}

function saveSalesLedger(list) {
    try { localStorage.setItem("azoraSalesLedger", JSON.stringify(list || [])); } catch (e) {}
}

function pendingRowDelayMs(row) {
    if (!row) return (typeof AZORA_PENDING_DEFAULT_MS !== "undefined" ? AZORA_PENDING_DEFAULT_MS : 60000);
    if (row.kind === "donation" || row.type === "donation" || row.itemName === "Donation") {
        return (typeof AZORA_PENDING_DONATION_MS !== "undefined" ? AZORA_PENDING_DONATION_MS : 300000);
    }
    if (row.kind === "tshirt") {
        return (typeof AZORA_PENDING_TSHIRT_SALE_MS !== "undefined" ? AZORA_PENDING_TSHIRT_SALE_MS : 466560000);
    }
    return (typeof AZORA_PENDING_DEFAULT_MS !== "undefined" ? AZORA_PENDING_DEFAULT_MS : 60000);
}
function pendingRowAvailableAt(row) {
    if (!row) return Date.now();
    if (row.availableAt) return row.availableAt;
    return (row.at || 0) + pendingRowDelayMs(row);
}
function getPendingForUser(username, onlyMatured) {
    var u = String(username || "").trim().toLowerCase();
    var now = Date.now();
    return getSalesLedger().filter(function (row) {
        if (!row || row.collected) return false;
        if (String(row.toUser || "").trim().toLowerCase() !== u) return false;
        if (onlyMatured && now < pendingRowAvailableAt(row)) return false;
        return true;
    });
}

function sumPendingForUser(username) {
    var sum = 0;
    getPendingForUser(username).forEach(function (row) {
        sum += Number(row.amount) || 0;
    });
    return Math.round(sum * 1000) / 1000;
}

function collectPendingCoins() {
    var acc = getActiveAccount();
    if (!acc || acc.isGuest) {
        alert("Log in with an account to collect pending AzoraCoins.");
        return;
    }
    var pending = getPendingForUser(acc.username, true); // only matured
    if (!pending.length) {
        showAzoraToast("No pending AzoraCoins.");
        return;
    }
    var total = 0;
    var ledger = getSalesLedger();
    pending.forEach(function (p) {
        total += Number(p.amount) || 0;
        ledger.forEach(function (row) {
            if (row && row.id === p.id) row.collected = true;
        });
    });
    total = Math.round(total * 1000) / 1000;
    saveSalesLedger(ledger);
    setCoins(getCoins() + total);
    showAzoraToast("Collected " + formatCoins(total) + " AzoraCoins!");
    renderCoinsDropdown();
    updateCoinsUI();
}

/** Record a sale. amountToSeller goes pending for seller; amountToPlatform pending for Azora.
 *  opts.kind: "donation" | "tshirt" | "official" | other — sets availableAt delay
 */
function recordSale(opts) {
    opts = opts || {};
    var ledger = getSalesLedger();
    var ts = Date.now();
    var buyer = opts.buyerName || "Someone";
    var itemName = opts.itemName || "Item";
    var kind = opts.kind || "sale";
    var delay = AZORA_PENDING_DEFAULT_MS;
    if (kind === "donation") delay = AZORA_PENDING_DONATION_MS;
    else if (kind === "tshirt") delay = AZORA_PENDING_TSHIRT_SALE_MS;
    else if (kind === "official") delay = AZORA_PENDING_DEFAULT_MS;
    var availableAt = ts + delay;
    if (opts.amountToSeller > 0 && opts.sellerName) {
        ledger.unshift({
            id: "sale_" + ts + "_s",
            toUser: opts.sellerName,
            fromUser: buyer,
            itemName: itemName,
            amount: Math.round(opts.amountToSeller * 1000) / 1000,
            fee: false,
            collected: false,
            kind: kind,
            at: ts,
            availableAt: availableAt
        });
    }
    if (opts.amountToPlatform > 0) {
        ledger.unshift({
            id: "sale_" + ts + "_p",
            toUser: AZORA_OWNER_NAME,
            fromUser: buyer,
            itemName: itemName + " (platform fee)",
            amount: Math.round(opts.amountToPlatform * 1000) / 1000,
            fee: true,
            collected: false,
            kind: kind,
            at: ts,
            availableAt: availableAt
        });
    }
    if (ledger.length > 300) ledger = ledger.slice(0, 300);
    saveSalesLedger(ledger);
}

function creditOfficialCatalogSale(price, buyerName, itemName) {
    // Official hair/faces are By Azora → 100% to Azora (pending)
    var p = Math.round((Number(price) || 0) * 1000) / 1000;
    if (p <= 0) return;
    recordSale({
        sellerName: AZORA_OWNER_NAME,
        buyerName: buyerName,
        itemName: itemName,
        amountToSeller: p,
        amountToPlatform: 0
    });
}


function getCoins() {
    try {
        var acc = getActiveAccount();
        if (acc && !acc.isGuest) {
            var c = (typeof acc.coins === "number" && !isNaN(acc.coins)) ? acc.coins : 0;
            return Math.max(0, Math.round(c * 1000) / 1000);
        }
        // Guests / logged out only — do not leak other accounts' balances
        return 0;
    } catch (e) { return 0; }
}

function setCoins(n) {
    n = Math.max(0, Math.round((Number(n) || 0) * 1000) / 1000);
    try { localStorage.setItem("azoraCoins", String(n)); } catch (e) {}
    try {
        var acc = getActiveAccount();
        if (acc) {
            acc.coins = n;
            persistActiveAccount(acc);
        }
    } catch (e2) {}
    updateCoinsUI();
    return n;
}

function addCoins(amount) {
    return setCoins(getCoins() + (Number(amount) || 0));
}

function spendCoins(amount) {
    amount = Math.round((Number(amount) || 0) * 1000) / 1000;
    var cur = getCoins();
    if (cur + 1e-9 < amount) return false;
    setCoins(cur - amount);
    return true;
}


function toggleCoinsDropdown(ev) {
    if (ev) { ev.preventDefault(); ev.stopPropagation(); }
    var dd = document.getElementById("coinsDropdown");
    if (!dd) return;
    var open = dd.classList.contains("open");
    closeCoinsDropdown();
    if (!open) {
        renderCoinsDropdown();
        dd.classList.add("open");
        dd.setAttribute("aria-hidden", "false");
    }
}

function closeCoinsDropdown() {
    var dd = document.getElementById("coinsDropdown");
    if (dd) {
        dd.classList.remove("open");
        dd.setAttribute("aria-hidden", "true");
    }
    var panel = document.getElementById("pendingCoinsPanel");
    if (panel) panel.style.display = "none";
}

function renderCoinsDropdown() {
    var bal = document.getElementById("coinsDropBalance");
    if (bal) bal.textContent = formatCoins(getCoins());
    var pendSum = document.getElementById("coinsDropPending");
    var acc = getActiveAccount();
    var name = acc && acc.username ? acc.username : "";
    var pendingTotal = name ? sumPendingForUser(name) : 0;
    if (pendSum) pendSum.textContent = formatCoins(pendingTotal);
}

function openPendingCoins() {
    var panel = document.getElementById("pendingCoinsPanel");
    if (!panel) return;
    var acc = getActiveAccount();
    if (!acc || acc.isGuest) {
        panel.innerHTML = '<p class="pending-empty">Log in with an account to see pending AzoraCoins.</p>';
        panel.style.display = "block";
        return;
    }
    var rows = getPendingForUser(acc.username);
    var html = '<div class="pending-head"><strong>Pending AzoraCoins</strong>';
    html += '<button type="button" class="pending-collect-btn" onclick="collectPendingCoins()">Collect all</button></div>';
    if (!rows.length) {
        html += '<p class="pending-empty">No pending coins right now.</p>';
    } else {
        rows.forEach(function (row) {
            var when = row.at ? new Date(row.at).toLocaleString() : "";
            html += '<div class="pending-row">';
            html += '<div class="pending-amt">+' + formatCoins(row.amount) + ' 🪙</div>';
            html += '<div class="pending-meta">From <strong>' + (row.fromUser || "Someone") + '</strong>';
            html += '<br><span class="pending-item">' + (row.itemName || "Item") + '</span>';
            if (when) html += '<br><span class="pending-time">' + when + '</span>';
            html += '</div></div>';
        });
    }
    panel.innerHTML = html;
    panel.style.display = "block";
    renderCoinsDropdown();
}

(function bindCoinsDropdownClose() {
    if (window._azoraCoinsDropBound) return;
    window._azoraCoinsDropBound = true;
    document.addEventListener("click", function (e) {
        var dd = document.getElementById("coinsDropdown");
        var wrap = document.getElementById("coinsMenuWrap");
        if (!dd || !dd.classList.contains("open")) return;
        if (wrap && wrap.contains(e.target)) return;
        closeCoinsDropdown();
    });
})();


function updateCoinsUI() {
    try {
        var el = document.getElementById("bucks");
        if (el) el.textContent = formatCoins(getCoins());
        var bal = document.getElementById("marketCoinBalance");
        if (bal) bal.textContent = formatCoins(getCoins());
        var mBal = document.getElementById("memberCoinBalance");
        if (mBal) mBal.textContent = formatCoins(getCoins());
    } catch (e) {}
}

/** Daily login reward helpers */
function getTodayKey() {
    var d = new Date();
    return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
}

function getYesterdayKey() {
    var d = new Date();
    d.setDate(d.getDate() - 1);
    return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
}

function getLoginStreak() {
    try {
        return Math.max(0, parseInt(localStorage.getItem("azoraLoginStreak") || "0", 10) || 0);
    } catch (e) { return 0; }
}

function isDailyGiftClaimedToday() {
    try {
        return (localStorage.getItem("azoraLastDailyClaim") || "") === getTodayKey();
    } catch (e) { return false; }
}

function hasClaimedDailyToday() {
    try {
        if (typeof isDailyGiftClaimedToday === "function") return isDailyGiftClaimedToday();
        return (localStorage.getItem("azoraLastDailyClaim") || "") === (typeof getTodayKey === "function" ? getTodayKey() : "");
    } catch (e) {
        return false;
    }
}


function scheduleDailyClaimCheck() {
    // Wait until loading screen is gone, then show claim popup
    function tryShow() {
        try {
            var loading = document.getElementById("azoraLoadingScreen");
            if (loading && loading.style.display !== "none" && loading.classList.contains("show")) {
                setTimeout(tryShow, 400);
                return;
            }
            if (typeof checkDailyLoginReward === "function") checkDailyLoginReward();
        } catch (e) {
            try { if (typeof checkDailyLoginReward === "function") checkDailyLoginReward(); } catch (e2) {}
        }
    }
    setTimeout(tryShow, 3200);
}
window.scheduleDailyClaimCheck = scheduleDailyClaimCheck;
window.hasClaimedDailyToday = hasClaimedDailyToday;

/** Called on login / app load — does NOT auto-grant coins anymore; UI button claims. */
function checkDailyLoginReward() {
    try {
        if (typeof claimMembershipMonthlyYield === "function") {
            try { claimMembershipMonthlyYield(); } catch (e2) {}
        }
        if (typeof checkPlatformAirdrop === "function") {
            try { checkPlatformAirdrop(); } catch (e3) {}
        }
        try { refreshFunTopbar(); } catch (e4) {}
        // Show claim popup once per local calendar day (resets 12:00 AM local)
        try {
            var logged = localStorage.getItem("loggedIn");
            if (logged === "true" || logged === "guest") {
                if (!hasClaimedDailyToday()) {
                    setTimeout(function () { openDailyClaimPopup(); }, 900);
                }
            }
        } catch (e5) {}
    } catch (e) {
        console.warn("[Azora] daily check", e);
    }
}

function getDailyRewardAmount(streak) {
    // Base 0.05 for everyone; small streak bonus
    var reward = 0.05;
    streak = Number(streak) || 1;
    if (streak >= 7) reward = 0.12;
    else if (streak >= 3) reward = 0.08;
    return Math.round(reward * 1000) / 1000;
}

function openDailyClaimPopup(opts) {
    opts = opts || {};
    var ov = document.getElementById("dailyClaimOverlay");
    if (!ov) {
        console.warn("[Azora] dailyClaimOverlay missing from HTML");
        return;
    }
    if (hasClaimedDailyToday()) return;
    // Auto-popup respects "dismissed today"; manual claim (topbar) always opens
    if (!opts.force) {
        try {
            var dk = (typeof getTodayKey === "function") ? getTodayKey() : "";
            if (localStorage.getItem("azoraDailyClaimDismissed") === dk) return;
        } catch (eD) {}
    } else {
        try { localStorage.removeItem("azoraDailyClaimDismissed"); } catch (eClr) {}
    }
    try {
        ov.style.zIndex = "2147483000";
    } catch (eZ) {}
    var streak = getLoginStreak();
    var last = localStorage.getItem("azoraLastDailyClaim") || "";
    var yesterday = getYesterdayKey();
    var previewStreak = (last === yesterday) ? (streak + 1) : 1;
    var reward = getDailyRewardAmount(previewStreak);
    var title = document.getElementById("dailyClaimTitle");
    if (title) title.textContent = "You have just gotten " + reward.toFixed(2) + " AzoraCoins!";
    var btn = document.getElementById("dailyClaimBtn");
    var success = document.getElementById("dailyClaimSuccess");
    if (btn) { btn.style.display = "block"; btn.disabled = false; }
    if (success) success.style.display = "none";
    ov.style.display = "flex";
    ov.setAttribute("aria-hidden", "false");
}

function closeDailyClaimPopup() {
    var ov = document.getElementById("dailyClaimOverlay");
    if (ov) {
        ov.style.display = "none";
        ov.setAttribute("aria-hidden", "true");
    }
    // Prevent reopen loop until they claim or a new day
    try {
        var dk = (typeof getTodayKey === "function") ? getTodayKey() : String(Date.now());
        localStorage.setItem("azoraDailyClaimDismissed", dk);
    } catch (e) {}
}

function runDailyCoinAnimation(done) {
    var fx = document.getElementById("dailyClaimCoinsFx");
    if (!fx) { if (done) done(); return; }
    fx.innerHTML = "";
    var count = 10;
    for (var i = 0; i < count; i++) {
        (function (idx) {
            setTimeout(function () {
                var coin = document.createElement("div");
                coin.className = "daily-fly-coin";
                // Fly toward top-right (balance area) — slow then faster feel via duration
                var dx = 40 + Math.random() * 90;
                var dy = -80 - Math.random() * 70;
                var dur = (1.35 - idx * 0.07) + "s"; // later coins finish quicker
                coin.style.setProperty("--dx", dx + "px");
                coin.style.setProperty("--dy", dy + "px");
                coin.style.setProperty("--dur", dur);
                fx.appendChild(coin);
                // force reflow
                void coin.offsetWidth;
                coin.classList.add("go");
            }, idx * 90);
        })(i);
    }
    setTimeout(function () { if (done) done(); }, count * 90 + 1400);
}

function claimDailyGiftAnimated() {
    try {
        var logged = localStorage.getItem("loggedIn");
        if (!logged || logged === "") {
            showAzoraToast("Log in or continue as Guest to claim your gift!");
            return;
        }
        var today = getTodayKey();
        var last = localStorage.getItem("azoraLastDailyClaim") || "";
        if (last === today) {
            showAzoraToast("You already claimed today's gift. Come back tomorrow!");
            closeDailyClaimPopup();
            refreshFunTopbar();
            return;
        }
        var btn = document.getElementById("dailyClaimBtn");
        if (btn) btn.disabled = true;

        var yesterday = getYesterdayKey();
        var streak = getLoginStreak();
        if (last === yesterday) streak += 1;
        else streak = 1;
        var reward = getDailyRewardAmount(streak);

        // Grant after a short delay into the animation (slow start → speeds up visually)
        // Animate topbar coin number on top of transparent overlay while coins fly
        var startBal = (typeof getCoins === "function") ? getCoins() : 0;
        var targetBal = startBal + reward;
        var t0 = Date.now();
        var infl = setInterval(function () {
            var p = Math.min(1, (Date.now() - t0) / 1600);
            // ease-in then speed up
            var e = p < 0.4 ? (p * p * 1.2) : Math.min(1, 0.2 + (p - 0.4) * 1.6);
            var val = startBal + (targetBal - startBal) * e;
            var bucks = document.getElementById("bucks");
            if (bucks) bucks.textContent = (Math.round(val * 100) / 100).toString();
            var hero = document.getElementById("heroCoinsStat");
            if (hero) hero.textContent = (Math.round(val * 100) / 100).toString();
            if (p >= 1) clearInterval(infl);
        }, 40);

        runDailyCoinAnimation(function () {
            localStorage.setItem("azoraLoginStreak", String(streak));
            localStorage.setItem("azoraLastDailyClaim", today);
            try { localStorage.removeItem("azoraDailyClaimDismissed"); } catch (eD2) {}
            if (typeof addCoins === "function") addCoins(reward);
            try { if (typeof updateCoinsUI === "function") updateCoinsUI(); } catch (eU) {}
            try { refreshFunTopbar(); } catch (eR) {}
            try { if (typeof azoraSyncFunHome === "function") azoraSyncFunHome(); } catch (eH) {}
            if (btn) btn.style.display = "none";
            var success = document.getElementById("dailyClaimSuccess");
            if (success) success.style.display = "block";
            try {
                if (typeof playClickSound === "function") playClickSound();
                else if (typeof playUiClick === "function") playUiClick();
            } catch (eS) {}
        });
    } catch (e) {
        console.warn("[Azora] claim daily animated", e);
    }
}

function claimDailyGift() {
    // Topbar chip still works — opens the same claim flow (even if auto-popup was dismissed)
    try {
        if (hasClaimedDailyToday()) {
            showAzoraToast("You already claimed today's gift. Come back tomorrow!");
            refreshFunTopbar();
            return;
        }
        openDailyClaimPopup({ force: true });
    } catch (e) {
        console.warn("[Azora] claim daily", e);
    }
}

