function inventoryStorageKey(username) {
    var u = String(username || "").trim().toLowerCase();
    if (!u) return "azoraInventory__none";
    return "azoraInventory::" + u;
}

function emptyInventory() {
    return { items: [], equipped: { hair: null, face: null, shirt: null } };
}

function getInventory() {
    try {
        var acc = typeof getActiveAccount === "function" ? getActiveAccount() : null;
        var username = acc && acc.username ? acc.username : "";
        // Prefer inventory stored on the account object
        if (acc && acc.inventory && typeof acc.inventory === "object") {
            var rawA = acc.inventory;
            if (!Array.isArray(rawA.items)) rawA.items = [];
            if (!rawA.equipped || typeof rawA.equipped !== "object") rawA.equipped = { hair: null, face: null, shirt: null };
            if (!("shirt" in rawA.equipped)) rawA.equipped.shirt = null;
            return rawA;
        }
        var key = inventoryStorageKey(username);
        var raw = JSON.parse(localStorage.getItem(key) || "null");
        // Migration: only for owner, allow one-time read of legacy global inventory
        if ((!raw || typeof raw !== "object") && username && typeof isOwnerUsername === "function" && isOwnerUsername(username)) {
            try {
                var legacy = JSON.parse(localStorage.getItem("azoraInventory") || "null");
                if (legacy && typeof legacy === "object") raw = legacy;
            } catch (eL) {}
        }
        if (!raw || typeof raw !== "object") raw = emptyInventory();
        if (!Array.isArray(raw.items)) raw.items = [];
        if (!raw.equipped || typeof raw.equipped !== "object") raw.equipped = { hair: null, face: null, shirt: null };
        if (!("shirt" in raw.equipped)) raw.equipped.shirt = null;
        if (typeof raw.equipped.face === "undefined") raw.equipped.face = null;
        if (typeof raw.equipped.hair === "undefined") raw.equipped.hair = null;
        return raw;
    } catch (e) {
        return emptyInventory();
    }
}

function saveInventory(inv) {
    try {
        if (!inv || typeof inv !== "object") inv = emptyInventory();
        var acc = typeof getActiveAccount === "function" ? getActiveAccount() : null;
        var username = acc && acc.username ? acc.username : "";
        if (acc && !acc.isGuest) {
            acc.inventory = inv;
            if (typeof persistActiveAccount === "function") persistActiveAccount(acc);
            else {
                localStorage.setItem("azoraAccount", JSON.stringify(acc));
            }
        }
        if (username) {
            localStorage.setItem(inventoryStorageKey(username), JSON.stringify(inv));
        }
    } catch (e) {}
}


function getAllOfficialCatalogIds() {
    var ids = [];
    try {
        (AZORA_HAIR_CATALOG || []).forEach(function (it) { if (it && it.id) ids.push(it.id); });
        (AZORA_FACE_CATALOG || []).forEach(function (it) { if (it && it.id) ids.push(it.id); });
        (AZORA_TSHIRT_CATALOG || []).forEach(function (it) { if (it && it.id) ids.push(it.id); });
    } catch (e) {}
    return ids;
}

function grantAllOfficialItemsToOwner() {
    var isOwner = false;
    try {
        if (typeof isAzoraOwner === "function" && isAzoraOwner()) isOwner = true;
        var acc = null;
        try { acc = JSON.parse(localStorage.getItem("azoraAccount") || "null"); } catch (eA) {}
        if (acc && String(acc.username || "").toLowerCase() === "azora") isOwner = true;
        if (!isOwner && typeof isOwnerUsername === "function" && acc && isOwnerUsername(acc.username)) isOwner = true;
        if (!isOwner && localStorage.getItem("loggedIn") === "true" && acc && acc.isOwner) isOwner = true;
    } catch (e) {}
    if (!isOwner) return;
    var inv = getInventory();
    var ids = getAllOfficialCatalogIds();
    var changed = false;
    ids.forEach(function (id) {
        if (id && inv.items.indexOf(id) === -1) {
            inv.items.push(id);
            changed = true;
        }
    });
    // Defaults equipped so inventory isn't "empty looking" with nothing selected
    if (!inv.equipped) inv.equipped = { hair: null, face: null, shirt: null };
    if (!inv.equipped.hair) {
        inv.equipped.hair = "hair_boy_none";
        changed = true;
    }
    if (!inv.equipped.face) {
        inv.equipped.face = "face_smile";
        changed = true;
    }
    if (changed) saveInventory(inv);
    else saveInventory(inv); // still persist shape
}

function ownsItem(itemId) {
    // Official account owns every official catalog item (hair + faces + shirts + Aturius)
    try {
        if (typeof isAzoraOwner === "function" && isAzoraOwner()) {
            if (hairCatalogById(itemId) || faceCatalogById(itemId) ||
                aturiusMarketById(itemId) ||
                (typeof officialTShirtCatalogById === "function" && officialTShirtCatalogById(itemId))) {
                return true;
            }
        }
    } catch (e) {}
    // Free Aturius defaults always owned
    if (itemId === "aturius_face_default" || itemId === "aturius_hat_none" || itemId === "aturius_color_default") return true;
    var inv = getInventory();
    return inv.items.indexOf(itemId) !== -1;
}

