function buyMarketplaceItem(itemId) {
    if (localStorage.getItem("loggedIn") !== "true") {
        alert("Log in or create an account to buy items!");
        if (typeof openCreateAccount === "function") openCreateAccount();
        return;
    }
    if (typeof isAzoraOwner === "function" && isAzoraOwner()) {
        showAzoraToast("Azora already owns every official item.");
        return;
    }
    var item = hairCatalogById(itemId) || faceCatalogById(itemId) || aturiusMarketById(itemId);
    var isShirt = false;
    var isAturiusItem = !!(item && String(item.type || "").indexOf("aturius_") === 0);
    if (!item && typeof getTShirtById === "function") {
        item = getTShirtById(itemId);
        isShirt = !!item;
    }
    if (!item) { alert("Item not found."); return; }
    if (ownsItem(itemId) || (isShirt && ownsItem(itemId))) {
        showAzoraToast("You already own this!");
        return;
    }
    // Cannot buy your own T-Shirt
    if (isShirt) {
        var acc = getActiveAccount();
        if (acc && item.creator && String(item.creator).toLowerCase() === String(acc.username || "").toLowerCase()) {
            showAzoraToast("You already created this T-Shirt.");
            return;
        }
    }
    var price = Number(item.price) || 0;
    if (price > 0 && !spendCoins(price)) {
        alert("Not enough AzoraCoins! You need " + formatCoins(price) + " 🪙");
        return;
    }
    var inv = getInventory();
    if (inv.items.indexOf(itemId) === -1) inv.items.push(itemId);
    saveInventory(inv);

    var buyerName = "Someone";
    try {
        var a = getActiveAccount();
        if (a && a.username) buyerName = a.isGuest ? ("Guest " + (a.userId || "")) : a.username;
    } catch (e) {}

    var splitNote = "";
    if (isShirt && item.official) {
        // Official Azora T-Shirts → 100% to Azora (same as faces/hair)
        if (price > 0) {
            creditOfficialCatalogSale(price, buyerName, item.name || itemId);
            splitNote = " (to Azora)";
        }
    } else if (isShirt) {
        // Player-uploaded T-Shirts: tax-free under 0.10; 90/10 starting at 0.10
        var split = computeSaleSplit(price);
        recordSale({
            sellerName: item.creator || "Creator",
            buyerName: buyerName,
            itemName: item.name || "T-Shirt",
            amountToSeller: split.seller,
            amountToPlatform: split.fee,
            kind: "tshirt"
        });
        if (price > 0) {
            splitNote = split.taxFree
                ? " (tax-free for creator)"
                : (" (creator +" + formatCoins(split.seller) + ", Azora +" + formatCoins(split.fee) + ")");
        }
    } else if (isAturiusItem && price > 0) {
        try { creditOfficialCatalogSale(price, buyerName, item.name || itemId); } catch (eAt) {}
        splitNote = " (Aturius marketplace → Azora)";
    } else if (price > 0) {
        // Official catalog By Azora → 100% to Azora pending
        creditOfficialCatalogSale(price, buyerName, item.name || itemId);
    }

    showAzoraToast("Bought " + (item.name || "item") + "!" + splitNote + " Check Inventory to equip.");
    renderMarketplace();
    renderInventory();
    try { renderCoinsDropdown(); } catch (e3) {}
}

function equipInventoryItem(itemId) {
    if (!ownsItem(itemId)) {
        alert("You don't own this item yet. Buy it in the Marketplace!");
        return;
    }
    var inv = getInventory();
    var isFace = isFaceItemId(itemId);
    if (isFace) {
        inv.equipped.face = itemId;
    } else {
        inv.equipped.hair = itemId;
    }
    saveInventory(inv);

    // Apply live on avatar
    try {
        var gender = (typeof getAvatarGender === "function") ? getAvatarGender() : "boy";
        var colors = {};
        try {
            if (typeof readAvatarColorInputs === "function") colors = readAvatarColorInputs() || {};
        } catch (e) {}
        colors.hair = colors.hair || "#4a3728";
        if (typeof applyGenderVisualsToCustomizer === "function") {
            applyGenderVisualsToCustomizer(gender, colors);
        }
    } catch (e) {
        console.warn("[Azora] equip item", e);
    }

    // Persist on account avatar
    try {
        var acc = JSON.parse(localStorage.getItem("azoraAccount") || "null");
        if (acc) {
            if (!acc.avatar) acc.avatar = {};
            if (isFace) acc.avatar.faceStyle = itemId;
            else acc.avatar.hairStyle = itemId;
            localStorage.setItem("azoraAccount", JSON.stringify(acc));
            if (acc.username && typeof getSavedAccounts === "function") {
                var map = getSavedAccounts();
                if (map[acc.username]) {
                    map[acc.username].avatar = map[acc.username].avatar || {};
                    if (isFace) map[acc.username].avatar.faceStyle = itemId;
                    else map[acc.username].avatar.hairStyle = itemId;
                    if (typeof saveSavedAccounts === "function") saveSavedAccounts(map);
                }
            }
        }
        try {
            var av = JSON.parse(localStorage.getItem("azoraAvatar") || "{}");
            if (isFace) av.faceStyle = itemId;
            else av.hairStyle = itemId;
            localStorage.setItem("azoraAvatar", JSON.stringify(av));
        } catch (e2) {}
    } catch (e) {}

    showAzoraToast("Equipped! Save your avatar to keep it forever.");
    renderInventory();
}


var _marketplaceTab = "market"; // market | shop | aturius

function setMarketplaceTab(tab) {
    _marketplaceTab = tab || "market";
    var tM = document.getElementById("marketTabMarket");
    var tS = document.getElementById("marketTabShop");
    var tA = document.getElementById("marketTabAturius");
    if (tM) tM.classList.toggle("active", _marketplaceTab === "market");
    if (tS) tS.classList.toggle("active", _marketplaceTab === "shop");
    if (tA) tA.classList.toggle("active", _marketplaceTab === "aturius");
    var mainF = document.getElementById("marketMainFilters");
    var atF = document.getElementById("aturiusMarketFilters");
    var hint = document.getElementById("aturiusMarketHint");
    if (mainF) mainF.style.display = (_marketplaceTab === "aturius") ? "none" : "flex";
    if (atF) atF.style.display = (_marketplaceTab === "aturius") ? "flex" : "none";
    if (hint) hint.style.display = (_marketplaceTab === "aturius") ? "block" : "none";
    if (_marketplaceTab === "shop") {
        var cat = document.getElementById("marketCategory");
        if (cat) cat.value = "shirts";
    } else if (_marketplaceTab === "market") {
        var cat2 = document.getElementById("marketCategory");
        if (cat2 && cat2.value === "shirts") cat2.value = "hair";
    }
    renderMarketplace();
}
window.setMarketplaceTab = setMarketplaceTab;

function getMarketCategory() {
    if (_marketplaceTab === "aturius") {
        var a = document.getElementById("aturiusMarketCategory");
        return (a && a.value) ? a.value : "aturius_hats";
    }
    var el = document.getElementById("marketCategory");
    return (el && el.value) ? el.value : "hair";
}

function getInventoryCategory() {
    var el = document.getElementById("inventoryCategory");
    return (el && el.value) ? el.value : "hair";
}
window.getInventoryCategory = getInventoryCategory;


/** —— T-Shirts: official Azora catalog + user uploads (free to list, priced by creator) —— */
function getTShirtCatalog() {
    var official = (AZORA_TSHIRT_CATALOG || []).map(function (it) {
        return {
            id: it.id,
            name: it.name,
            price: it.price,
            creator: "Azora",
            by: "Azora",
            file: it.file,
            imageData: null,
            desc: it.desc || "",
            official: true,
            createdAt: 0
        };
    });
    var userList = [];
    try {
        userList = JSON.parse(localStorage.getItem("azoraTShirts") || "[]");
        if (!Array.isArray(userList)) userList = [];
    } catch (e) { userList = []; }
    // Official first, then player uploads (skip any upload that collides with official ids)
    var seen = {};
    official.forEach(function (o) { seen[o.id] = true; });
    var merged = official.slice();
    userList.forEach(function (u) {
        if (!u || !u.id || seen[u.id]) return;
        seen[u.id] = true;
        merged.push(u);
    });
    return merged;
}

function saveTShirtCatalog(list) {
    // Only persist user-uploaded shirts (never overwrite official catalog)
    var userOnly = (list || []).filter(function (it) {
        return it && it.id && !it.official && String(it.id).indexOf("shirt_") === 0 &&
            !(typeof officialTShirtCatalogById === "function" && officialTShirtCatalogById(it.id));
    });
    try { localStorage.setItem("azoraTShirts", JSON.stringify(userOnly)); } catch (e) {}
}

function getTShirtById(id) {
    var off = typeof officialTShirtCatalogById === "function" ? officialTShirtCatalogById(id) : null;
    if (off) {
        return {
            id: off.id,
            name: off.name,
            price: off.price,
            creator: "Azora",
            by: "Azora",
            file: off.file,
            imageData: null,
            desc: off.desc || "",
            official: true,
            createdAt: 0
        };
    }
    try {
        var list = JSON.parse(localStorage.getItem("azoraTShirts") || "[]");
        if (!Array.isArray(list)) list = [];
        for (var i = 0; i < list.length; i++) {
            if (list[i] && list[i].id === id) return list[i];
        }
    } catch (e) {}
    return null;
}

function openCreateTShirt() {
    if (localStorage.getItem("loggedIn") !== "true") {
        alert("Log in or create an account to upload a T-Shirt.");
        if (typeof openCreateAccount === "function") openCreateAccount();
        return;
    }
    var acc = getActiveAccount();
    if (acc && acc.isGuest) {
        alert("Guests cannot upload T-Shirts. Create an account first!");
        return;
    }
    var ov = document.getElementById("createTShirtOverlay");
    if (!ov) return;
    var nameEl = document.getElementById("tshirtNameInput");
    var priceEl = document.getElementById("tshirtPriceInput");
    var prev = document.getElementById("tshirtPreviewImg");
    var fileEl = document.getElementById("tshirtFileInput");
    if (nameEl) nameEl.value = "";
    if (priceEl) priceEl.value = "0.02";
    if (fileEl) fileEl.value = "";
    if (prev) { prev.removeAttribute("src"); prev.style.display = "none"; }
    window._azoraTShirtDataUrl = null;
    ov.style.display = "flex";
}

function closeCreateTShirt() {
    var ov = document.getElementById("createTShirtOverlay");
    if (ov) ov.style.display = "none";
}

function onTShirtFileChosen(input) {
    var file = input && input.files && input.files[0];
    if (!file) return;
    if (!/^image\//.test(file.type)) {
        alert("Please choose an image file.");
        return;
    }
    if (file.size > 1.5 * 1024 * 1024) {
        alert("Image is too large. Please use an image under 1.5 MB.");
        return;
    }
    var reader = new FileReader();
    reader.onload = function () {
        var dataUrl = String(reader.result || "");
        // Draw onto small canvas for torso decal size
        var img = new Image();
        img.onload = function () {
            var c = document.createElement("canvas");
            c.width = 128;
            c.height = 128;
            var ctx = c.getContext("2d");
            ctx.clearRect(0, 0, 128, 128);
            // cover fit
            var scale = Math.max(128 / img.width, 128 / img.height);
            var dw = img.width * scale, dh = img.height * scale;
            ctx.drawImage(img, (128 - dw) / 2, (128 - dh) / 2, dw, dh);
            window._azoraTShirtDataUrl = c.toDataURL("image/png");
            var prev = document.getElementById("tshirtPreviewImg");
            if (prev) {
                prev.src = window._azoraTShirtDataUrl;
                prev.style.display = "block";
            }
        };
        img.src = dataUrl;
    };
    reader.readAsDataURL(file);
}

function submitCreateTShirt() {
    var acc = getActiveAccount();
    if (!acc || acc.isGuest) {
        alert("Create an account to upload T-Shirts.");
        return;
    }
    var name = ((document.getElementById("tshirtNameInput") || {}).value || "").trim();
    if (!name) { alert("Please name your T-Shirt."); return; }
    if (name.length > 40) { alert("Name must be 40 characters or less."); return; }
    var price = parseFloat((document.getElementById("tshirtPriceInput") || {}).value || "0");
    if (isNaN(price) || price < 0) price = 0;
    price = Math.round(price * 1000) / 1000;
    if (price > 50) { alert("Price is too high. Max 50 AzoraCoins for now."); return; }
    if (!window._azoraTShirtDataUrl) {
        alert("Please choose an image for the front of the torso.");
        return;
    }
    var list = getTShirtCatalog();
    var id = "shirt_" + Date.now() + "_" + Math.floor(Math.random() * 9999);
    var item = {
        id: id,
        name: name,
        price: price,
        creator: acc.username,
        creatorId: acc.userId || "",
        imageData: window._azoraTShirtDataUrl,
        createdAt: Date.now(),
        by: acc.username
    };
    list.unshift(item);
    if (list.length > 80) list = list.slice(0, 80);
    saveTShirtCatalog(list);
    // Creator owns it
    var inv = getInventory();
    if (inv.items.indexOf(id) === -1) inv.items.push(id);
    saveInventory(inv);
    closeCreateTShirt();
    showAzoraToast("T-Shirt uploaded! Free to list. Sales under 0.10 are tax-free; 0.10+ use a 90/10 split.");
    try {
        var cat = document.getElementById("marketCategory");
        if (cat) cat.value = "shirts";
        renderMarketplace();
        openMarketplace();
    } catch (e) {}
}

function getEquippedTShirtId() {
    var inv = getInventory();
    return (inv.equipped && inv.equipped.shirt) || null;
}

function equipTShirt(itemId) {
    var inv = getInventory();
    // Owner auto-owns official shirts; ensure inventory has the id for equip
    if (ownsItem(itemId) && inv.items.indexOf(itemId) === -1) {
        inv.items.push(itemId);
        saveInventory(inv);
    }
    if (!ownsItem(itemId) && inv.items.indexOf(itemId) === -1) {
        showAzoraToast("You do not own this T-Shirt.");
        return;
    }
    inv.equipped = inv.equipped || {};
    inv.equipped.shirt = itemId;
    saveInventory(inv);
    showAzoraToast("T-Shirt equipped! Save Avatar to keep it.");
    renderInventory();
    try { if (typeof refreshAvatarPreview === "function") refreshAvatarPreview(); } catch (e) {}
}


function renderMarketplace() {
    var list = document.getElementById("marketplaceList");
    if (!list) return;
    var category = getMarketCategory();
    var filter = (document.getElementById("marketGenderFilter") || {}).value || "all";
    var coins = getCoins();
    var html = "";
    var isOwner = (typeof isAzoraOwner === "function" && isAzoraOwner());

    function buyBtn(id) {
        return '<button type="button" class="market-btn" data-buy="' + id + '">Buy</button>';
    }
    function ownedBtn() {
        return '<button type="button" class="market-btn owned-btn" disabled>Owned</button>';
    }

    // Gender filter only for hair
    var genderWrap = document.getElementById("marketGenderFilterWrap");
    if (genderWrap) genderWrap.style.display = (category === "hair") ? "" : "none";
    var uploadBtn = document.getElementById("uploadTShirtBtn");
    if (uploadBtn) uploadBtn.style.display = (category === "shirts") ? "" : "none";

    if (category === "aturius_hats" || category === "aturius_faces" || category === "aturius_colors") {
        var wantType = category === "aturius_hats" ? "aturius_hat" : (category === "aturius_faces" ? "aturius_face" : "aturius_color");
        ATURIUS_MARKET_CATALOG.forEach(function (item) {
            if (item.type !== wantType) return;
            var owned = ownsItem(item.id) || isOwner;
            var canBuy = !owned && !isOwner && (item.price === 0 || coins >= item.price);
            var priceLabel = item.price === 0 ? "Free" : (formatCoins(item.price) + " 🪙");
            html += '<div class="market-card' + (owned ? " owned" : "") + '">';
            if (item.color) {
                html += '<div style="width:36px;height:36px;border-radius:50%;background:' + item.color + ';border:2px solid #fff;margin-bottom:6px;"></div>';
            }
            html += '<div class="market-card-title">' + item.name + '</div>';
            html += '<div class="market-card-meta">Aturius · <span class="by-creator">By Azora</span></div>';
            html += '<div class="market-card-desc">' + (item.desc || "") + '</div>';
            html += '<div class="market-card-footer"><span class="market-price">' + priceLabel + '</span>';
            if (owned) html += ownedBtn();
            else if (canBuy) html += buyBtn(item.id);
            else html += '<button type="button" class="market-btn disabled" disabled>Buy</button>';
            html += '</div></div>';
        });
    } else if (category === "faces") {
        AZORA_FACE_CATALOG.forEach(function (item) {
            var owned = ownsItem(item.id) || isOwner;
            var canBuy = !owned && !isOwner && (item.price === 0 || coins >= item.price);
            var priceLabel = item.price === 0 ? "Free" : (formatCoins(item.price) + " 🪙");
            var file = item.file || "Smile.png";
            html += '<div class="market-card market-card-face' + (owned ? " owned" : "") + '">';
            html += '<div class="market-face-row">';
            html += '<div class="market-face-thumb" aria-hidden="true"><img src="' + file + '" alt="" loading="lazy" onerror="this.style.opacity=0.3"></div>';
            html += '<div class="market-face-info">';
            html += '<div class="market-card-title">' + item.name + '</div>';
            html += '<div class="market-card-meta">Faces · <span class="by-creator">By Azora</span></div>';
            html += '<div class="market-card-desc">' + (item.desc || "") + '</div>';
            html += '</div></div>';
            html += '<div class="market-card-footer"><span class="market-price">' + priceLabel + '</span>';
            if (owned) html += ownedBtn();
            else if (canBuy) html += buyBtn(item.id);
            else html += '<button type="button" class="market-btn disabled" disabled>Buy</button>';
            html += '</div></div>';
        });
    } else if (category === "shirts") {
        var shirts = (typeof getTShirtCatalog === "function") ? getTShirtCatalog() : [];
        if (!shirts.length) {
            html += '<p class="market-empty">No T-Shirts yet. Upload one for free and set your own price!</p>';
        }
        shirts.forEach(function (item) {
            var owned = ownsItem(item.id) || (isOwner && item.official);
            var canBuy = !owned && !isOwner && (item.price === 0 || coins >= item.price);
            var priceLabel = item.price === 0 ? "Free" : (formatCoins(item.price) + " 🪙");
            var by = item.official ? "Azora" : (item.creator || item.by || "Player");
            var thumbSrc = item.imageData || item.file || "";
            html += '<div class="market-card market-card-face' + (owned ? " owned" : "") + '">';
            html += '<div class="market-face-row">';
            html += '<div class="market-face-thumb market-shirt-thumb" aria-hidden="true">';
            if (thumbSrc) html += '<img src="' + thumbSrc + '" alt="" loading="lazy" onerror="this.style.opacity=0.3">';
            html += '</div>';
            html += '<div class="market-face-info">';
            html += '<div class="market-card-title">' + (item.name || "T-Shirt") + '</div>';
            html += '<div class="market-card-meta">T-Shirts · <span class="by-creator">By ' + by + '</span></div>';
            html += '<div class="market-card-desc">' + (item.desc || (item.official ? "Official Azora design · Front of torso" : "Front of torso · Under 0.10 tax-free · 0.10+ is 90/10")) + '</div>';
            html += '</div></div>';
            html += '<div class="market-card-footer"><span class="market-price">' + priceLabel + '</span>';
            if (owned) html += ownedBtn();
            else if (canBuy) html += buyBtn(item.id);
            else html += '<button type="button" class="market-btn disabled" disabled>Buy</button>';
            html += '</div></div>';
        });
    } else {
        // Hair (default)
        AZORA_HAIR_CATALOG.forEach(function (item) {
            if (filter === "girl" && item.gender !== "girl") return;
            if (filter === "boy" && item.gender !== "boy") return;
            var owned = ownsItem(item.id) || isOwner;
            var canBuy = !owned && !isOwner && (item.price === 0 || coins >= item.price);
            var priceLabel = item.price === 0 ? "Free" : (formatCoins(item.price) + " 🪙");
            html += '<div class="market-card' + (owned ? " owned" : "") + '">';
            html += '<div class="market-card-title">' + item.name + '</div>';
            html += '<div class="market-card-meta">Hair · <span class="by-creator">By Azora</span>' +
                (item.gender === "girl" ? " · Girl" : (item.gender === "boy" ? " · Boy" : "")) + '</div>';
            html += '<div class="market-card-desc">' + (item.desc || "") + '</div>';
            html += '<div class="market-card-footer"><span class="market-price">' + priceLabel + '</span>';
            if (owned) html += ownedBtn();
            else if (canBuy) html += buyBtn(item.id);
            else html += '<button type="button" class="market-btn disabled" disabled>Buy</button>';
            html += '</div></div>';
        });
    }
    list.innerHTML = html || '<p class="market-empty">Nothing here yet.</p>';
}


function renderInventory() {
    var list = document.getElementById("inventoryList");
    if (!list) return;
    try {
        if (typeof grantDefaultHairForGender === "function") grantDefaultHairForGender();
        if (typeof grantAllOfficialItemsToOwner === "function") grantAllOfficialItemsToOwner();
    } catch (eG) {}
    var inv = getInventory();
    if (!inv.equipped) inv.equipped = { hair: null, face: null, shirt: null };
    var category = (typeof getInventoryCategory === "function") ? getInventoryCategory() : "hair";
    var equippedHair = inv.equipped.hair;
    var equippedFace = inv.equipped.face;
    var equippedShirt = inv.equipped.shirt;
    var html = "";
    var shown = 0;

    // Owner (or username Azora): show full official catalog always
    var displayIds = (inv.items || []).slice();
    var treatAsOwner = false;
    try {
        if (typeof isAzoraOwner === "function" && isAzoraOwner()) treatAsOwner = true;
        var acc = JSON.parse(localStorage.getItem("azoraAccount") || "null");
        if (acc && String(acc.username || "").toLowerCase() === "azora") treatAsOwner = true;
    } catch (eO) {}
    try {
        if (treatAsOwner && typeof getAllOfficialCatalogIds === "function") {
            getAllOfficialCatalogIds().forEach(function (id) {
                if (id && displayIds.indexOf(id) === -1) displayIds.push(id);
            });
            // Also persist so bag stays filled next open
            getAllOfficialCatalogIds().forEach(function (id) {
                if (id && inv.items.indexOf(id) === -1) inv.items.push(id);
            });
            if (typeof saveInventory === "function") saveInventory(inv);
        }
    } catch (eD) {}

    // If still empty for non-owner, at least show free defaults already granted
    displayIds.forEach(function (id) {
        var isFace = isFaceItemId(id);
        var isShirt = String(id).indexOf("shirt_") === 0;
        if (category === "faces" && !isFace) return;
        if (category === "hair" && (isFace || isShirt)) return;
        if (category === "shirts" && !isShirt) return;
        if (category === "faces" && isShirt) return;

        var item = null;
        if (isShirt) item = (typeof getTShirtById === "function") ? getTShirtById(id) : null;
        else if (isFace) item = faceCatalogById(id);
        else item = hairCatalogById(id);

        if (!item) {
            var raw = String(id).replace(/^face_/, "").replace(/^hair_/, "").replace(/^shirt_/, "").replace(/_/g, " ");
            item = {
                id: id,
                name: raw.split(" ").map(function (w) {
                    return w ? (w.charAt(0).toUpperCase() + w.slice(1)) : "";
                }).join(" "),
                desc: isShirt ? "T-Shirt" : "Item"
            };
        }
        var isEq = isShirt ? (equippedShirt === id) : (isFace ? (equippedFace === id) : (equippedHair === id));
        var meta;
        if (isShirt) meta = 'T-Shirts · <span class="by-creator">By ' + (item.official ? "Azora" : (item.creator || item.by || "Player")) + '</span>';
        else if (isFace) meta = 'Faces · <span class="by-creator">By Azora</span>';
        else meta = 'Hair · <span class="by-creator">By Azora</span>' + (item.gender === "girl" ? " · Girl" : (item.gender === "boy" ? " · Boy" : ""));

        html += '<div class="market-card' + ((isFace || isShirt) ? " market-card-face" : "") + (isEq ? " equipped" : "") + '">';
        if (isFace) {
            var file = item.file || "Smile.png";
            html += '<div class="market-face-row"><div class="market-face-thumb" aria-hidden="true"><img src="' + file + '" alt="" loading="lazy"></div>';
            html += '<div class="market-face-info"><div class="market-card-title">' + item.name + (isEq ? " ✓" : "") + '</div>';
            html += '<div class="market-card-meta">' + meta + '</div></div></div>';
        } else if (isShirt) {
            var shirtSrc = item.imageData || item.file || "";
            html += '<div class="market-face-row"><div class="market-face-thumb market-shirt-thumb" aria-hidden="true">';
            if (shirtSrc) html += '<img src="' + shirtSrc + '" alt="" loading="lazy" onerror="this.style.opacity=0.3">';
            html += '</div><div class="market-face-info"><div class="market-card-title">' + (item.name || "T-Shirt") + (isEq ? " ✓" : "") + '</div>';
            html += '<div class="market-card-meta">' + meta + '</div></div></div>';
        } else {
            html += '<div class="market-card-title">' + item.name + (isEq ? " ✓" : "") + '</div>';
            html += '<div class="market-card-meta">' + meta + '</div>';
            html += '<div class="market-card-desc">' + (item.desc || "") + '</div>';
        }
        html += '<div class="market-card-footer">';
        if (isEq) html += '<button type="button" class="market-btn owned-btn" disabled>Equipped</button>';
        else if (isShirt) html += '<button type="button" class="market-btn" data-equip-shirt="' + id + '">Equip</button>';
        else html += '<button type="button" class="market-btn" data-equip="' + id + '">Equip</button>';
        html += '</div></div>';
        shown++;
    });

    if (!shown) {
        html = '<p class="market-empty">No items in this category yet.</p>';
    }
    list.innerHTML = html;
}



(function bindMarketInventoryClicks() {
    if (window._azoraMarketClicksBound) return;
    window._azoraMarketClicksBound = true;
    document.addEventListener("click", function (e) {
        var t = e.target;
        if (!t || !t.closest) return;
        var buy = t.closest("[data-buy]");
        if (buy) {
            e.preventDefault();
            var id = buy.getAttribute("data-buy");
            if (id && typeof buyMarketplaceItem === "function") buyMarketplaceItem(id);
            return;
        }
        var eq = t.closest("[data-equip]");
        if (eq) {
            e.preventDefault();
            var eid = eq.getAttribute("data-equip");
            if (eid && typeof equipInventoryItem === "function") equipInventoryItem(eid);
            return;
        }
        var es = t.closest("[data-equip-shirt]");
        if (es) {
            e.preventDefault();
            var sid = es.getAttribute("data-equip-shirt");
            if (sid && typeof equipTShirt === "function") equipTShirt(sid);
            return;
        }
    });
})();


