// ============================================================
// Azora Moderation + System Element (Aza: 2) + Owner badges
// ============================================================

function getModerationRecords() {
    try {
        var r = JSON.parse(localStorage.getItem("azoraModerationRecords") || "{}");
        if (!r || typeof r !== "object") r = {};
        if (!r.bans) r.bans = {};
        if (!r.terminations) r.terminations = {};
        if (!r.appeals) r.appeals = [];
        if (!r.systemInbox) r.systemInbox = [];
        return r;
    } catch (e) {
        return { bans: {}, terminations: {}, appeals: [], systemInbox: [] };
    }
}

function saveModerationRecords(r) {
    try { localStorage.setItem("azoraModerationRecords", JSON.stringify(r || {})); } catch (e) {}
    // Push to cloud so other devices / live sessions see bans immediately
    try {
        if (typeof AZORA_CLOUD !== "undefined" && AZORA_CLOUD.isReady && AZORA_CLOUD.isReady()) {
            var url = (AZORA_CLOUD.firebaseUrl || "").replace(/\/$/, "") + "/azoraModeration.json";
            fetch(url, {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(r || {})
            }).catch(function () {});
        }
    } catch (e2) {}
}

function pullModerationFromCloud(done) {
    try {
        if (typeof AZORA_CLOUD === "undefined" || !AZORA_CLOUD.isReady || !AZORA_CLOUD.isReady()) {
            if (done) done(false);
            return;
        }
        var url = (AZORA_CLOUD.firebaseUrl || "").replace(/\/$/, "") + "/azoraModeration.json?ts=" + Date.now();
        fetch(url, { cache: "no-store" })
            .then(function (r) { return r.json(); })
            .then(function (data) {
                if (data && typeof data === "object") {
                    // Merge cloud into local (cloud wins for bans/terms; keep local appeals too)
                    var local = getModerationRecords();
                    if (data.bans) local.bans = data.bans;
                    if (data.terminations) local.terminations = data.terminations;
                    if (Array.isArray(data.appeals)) {
                        // prefer longer list
                        local.appeals = data.appeals;
                    }
                    if (data.restores) local.restores = data.restores;
                    try { localStorage.setItem("azoraModerationRecords", JSON.stringify(local)); } catch (e) {}
                    if (done) done(true, local);
                    return;
                }
                if (done) done(false);
            })
            .catch(function () { if (done) done(false); });
    } catch (e) {
        if (done) done(false);
    }
}

/** Ensure System Element exists in registry / public search (not a real player) */
function ensureSystemElement() {
    try {
        var reg = JSON.parse(localStorage.getItem("azoraUserRegistry") || "[]");
        var found = false;
        for (var i = 0; i < reg.length; i++) {
            if (reg[i] && (String(reg[i].username).toLowerCase() === "system" || reg[i].userId === "Aza: 2")) {
                reg[i].username = "system";
                reg[i].userId = "Aza: 2";
                reg[i].isSystemElement = true;
                reg[i].isGuest = false;
                found = true;
                break;
            }
        }
        if (!found) {
            reg.push({
                username: "system",
                userId: "Aza: 2",
                isGuest: false,
                isSystemElement: true,
                createdAt: 0,
                note: "System Element — not a real player"
            });
        }
        localStorage.setItem("azoraUserRegistry", JSON.stringify(reg));
    } catch (e) {}

    try {
        if (typeof database !== "undefined" && database.users) {
            var has = database.users.some(function (u) {
                return u && String(u.username).toLowerCase() === "system";
            });
            if (!has) {
                database.users.push({
                    username: "system",
                    profileLink: "#",
                    userId: "Aza: 2",
                    isSystemElement: true
                });
            }
        }
    } catch (e2) {}
}

function isSystemUsername(name) {
    return String(name || "").trim().toLowerCase() === "system";
}

function formatBanDuration(ms) {
    if (ms == null || isNaN(ms)) return "unknown duration";
    if (ms <= 0) return "expired";
    var sec = Math.floor(ms / 1000);
    var min = Math.floor(sec / 60);
    var hours = Math.floor(min / 60);
    var days = Math.floor(hours / 24);
    var years = Math.floor(days / 365);
    var remDays = days - years * 365;
    var months = Math.floor(remDays / 30);
    remDays = remDays - months * 30;
    var weeks = Math.floor(remDays / 7);
    remDays = remDays - weeks * 7;
    var parts = [];
    if (years >= 1) parts.push(years + " year" + (years === 1 ? "" : "s"));
    if (months >= 1) parts.push(months + " month" + (months === 1 ? "" : "s"));
    if (weeks >= 1) parts.push(weeks + " week" + (weeks === 1 ? "" : "s"));
    if (remDays >= 1) parts.push(remDays + " day" + (remDays === 1 ? "" : "s"));
    if (parts.length) return parts.join(", ");
    if (hours >= 1) {
        var hm = min - hours * 60;
        return hours + " hour" + (hours === 1 ? "" : "s") + (hm ? (", " + hm + " minute" + (hm === 1 ? "" : "s")) : "");
    }
    if (min >= 1) return min + " minute" + (min === 1 ? "" : "s");
    return sec + " second" + (sec === 1 ? "" : "s");
}

function getActiveModerationForUser(username) {
    username = String(username || "").trim();
    if (!username) return null;
    var key = username; // store by exact username used at ban time; also try case-insensitive
    var r = getModerationRecords();
    var term = r.terminations[key];
    if (!term) {
        Object.keys(r.terminations).forEach(function (k) {
            if (k.toLowerCase() === key.toLowerCase()) term = r.terminations[k];
        });
    }
    if (term && term.active !== false) {
        return {
            active: true,
            kind: "termination",
            reason: term.reason || "Your account has been terminated.",
            reasonLabel: term.reasonLabel || term.reason || "Your account has been terminated.",
            reasonCode: term.reasonCode || "",
            note: term.note || "",
            at: term.at,
            by: term.by || "Azora",
            until: null
        };
    }
    var ban = r.bans[key];
    if (!ban) {
        Object.keys(r.bans).forEach(function (k) {
            if (k.toLowerCase() === key.toLowerCase()) ban = r.bans[k];
        });
    }
    if (ban && ban.active !== false) {
        var until = ban.until || 0;
        if (until && Date.now() >= until) {
            // expired
            ban.active = false;
            ban.expired = true;
            r.bans[ban.username || key] = ban;
            saveModerationRecords(r);
            return null;
        }
        return {
            active: true,
            kind: "ban",
            reason: ban.reason || "Your account is temporarily banned.",
            reasonLabel: ban.reasonLabel || ban.reason || "Your account is temporarily banned.",
            reasonCode: ban.reasonCode || "",
            note: ban.note || "",
            at: ban.at,
            by: ban.by || "Azora",
            until: until,
            remainingMs: until ? Math.max(0, until - Date.now()) : null,
            from: ban.from || ban.at,
            untilDate: until
        };
    }
    return null;
}

function ownerBanUser(username, opts) {
    opts = opts || {};
    if (!isAzoraOwner()) {
        alert("Only the Azora owner can ban users.");
        return false;
    }
    username = String(username || "").trim();
    if (!username) return false;
    if (isSystemUsername(username)) {
        alert("system is a System Element and cannot be banned.");
        return false;
    }

    var fromMs = opts.fromMs != null ? opts.fromMs : Date.now();
    var untilMs = opts.untilMs;
    if (untilMs == null && opts.durationMs != null) untilMs = fromMs + opts.durationMs;
    if (!untilMs || untilMs <= fromMs) {
        alert("Pick a valid ban end date/time after the start.");
        return false;
    }

    var r = getModerationRecords();
    var banEntry = {
        username: username,
        active: true,
        from: fromMs,
        until: untilMs,
        at: Date.now(),
        by: "Azora",
        reason: opts.reason || "Banned by Azora staff.",
        reasonCode: opts.reasonCode || "",
        reasonLabel: opts.reasonLabel || opts.reason || "Banned by Azora staff.",
        reviewMode: "owner",
        automated: false,
        note: opts.note || ""
    };
    r.bans[username] = banEntry;
    r.bans[username.toLowerCase()] = banEntry;
    // clear termination if any when issuing temp ban
    Object.keys(r.terminations || {}).forEach(function (k) {
        if (k.toLowerCase() === username.toLowerCase()) r.terminations[k].active = false;
    });
    saveModerationRecords(r);

    // notify system inbox
    r = getModerationRecords();
    r.systemInbox.unshift({
        kind: "ban_issued",
        target: username,
        from: fromMs,
        until: untilMs,
        by: "Azora",
        at: Date.now()
    });
    saveModerationRecords(r);

    alert(
        "Banned " + username + "\n" +
        "Duration: " + formatBanDuration(untilMs - fromMs) + "\n" +
        "Until: " + new Date(untilMs).toLocaleString()
    );
    return true;
}

function ownerTerminateUser(username, opts) {
    opts = opts || {};
    if (!isAzoraOwner()) {
        alert("Only the Azora owner can terminate users.");
        return false;
    }
    username = String(username || "").trim();
    if (!username) return false;
    if (isSystemUsername(username)) {
        alert("system is a System Element and cannot be terminated.");
        return false;
    }
    if (!confirm("Permanently terminate " + username + "?\nThey can appeal via the blue appeal link.")) return false;

    // Snapshot progress for possible appeal restore
    var snapshot = null;
    try {
        var mapT = getSavedAccounts();
        var keyT = Object.keys(mapT).find(function (k) {
            return String(k).toLowerCase() === String(username).toLowerCase();
        });
        if (keyT && mapT[keyT]) {
            snapshot = {
                coins: mapT[keyT].coins || 0,
                inventory: mapT[keyT].inventory || null,
                avatar: mapT[keyT].avatar || null,
                bio: mapT[keyT].bio || "",
                createdAt: mapT[keyT].createdAt || null
            };
        }
    } catch (eSnap) {}

    var r = getModerationRecords();
    r.terminations[username] = {
        username: username,
        active: true,
        at: Date.now(),
        by: "Azora",
        reason: opts.reason || "Account terminated by Azora staff.",
        reasonCode: opts.reasonCode || "",
        reasonLabel: opts.reasonLabel || opts.reason || "Account terminated by Azora staff.",
        reviewMode: "owner",
        automated: false,
        note: opts.note || "",
        snapshot: snapshot
    };
    if (r.bans[username]) r.bans[username].active = false;
    saveModerationRecords(r);

    r = getModerationRecords();
    r.systemInbox.unshift({
        kind: "termination_issued",
        target: username,
        by: "Azora",
        at: Date.now()
    });
    saveModerationRecords(r);

    alert("Terminated " + username + ".\nThey will see a blue appeal link to contact system.");
    return true;
}

function ownerClearModeration(username) {
    if (!isAzoraOwner()) return false;
    username = String(username || "").trim();
    var r = getModerationRecords();
    if (r.bans[username]) r.bans[username].active = false;
    if (r.terminations[username]) r.terminations[username].active = false;
    // case-insensitive clear
    Object.keys(r.bans).forEach(function (k) {
        if (k.toLowerCase() === username.toLowerCase()) r.bans[k].active = false;
    });
    Object.keys(r.terminations).forEach(function (k) {
        if (k.toLowerCase() === username.toLowerCase()) r.terminations[k].active = false;
    });
    if (!r.restores) r.restores = {};
    r.restores[username] = { at: Date.now(), by: "Azora" };
    r.restores[username.toLowerCase()] = { at: Date.now(), by: "Azora" };
    saveModerationRecords(r);
    // If clearing self (testing), show restore popup now
    try {
        var me = getMyUsername();
        if (me && me.toLowerCase() === username.toLowerCase()) {
            var lock = document.getElementById("moderationLockOverlay");
            if (lock) lock.style.display = "none";
            _liveModLastSig = "";
            showAccessRestoredPopup();
        }
    } catch (eS) {}
    alert("Cleared ban/termination for " + username + ". They will see: Your access has been restored!");
    return true;
}

function ownerOverrideRestoreAccess() {
    // HARD lock: only official Azora owner session may use this
    if (localStorage.getItem("loggedIn") !== "true") {
        alert("Owner override denied.");
        return;
    }
    var me = null;
    try { me = JSON.parse(localStorage.getItem("azoraAccount") || "null"); } catch (e) {}
    if (!me || me.isGuest || !isOwnerUsername(me.username) || !isAzoraOwner()) {
        alert("Owner override denied. Only the official Azora account can use this.");
        return;
    }
    // Must also match exact owner id when present
    if (me.userId && String(me.userId).replace(/\s/g, "") !== "Aza:0" && String(me.userId) !== "Aza: 0") {
        // still allow if username is Azora (legacy)
        if (!isOwnerUsername(me.username)) {
            alert("Owner override denied.");
            return;
        }
    }
    ownerClearModeration(me.username);
    var ov = document.getElementById("moderationLockOverlay");
    if (ov) ov.style.display = "none";
    location.reload();
}

function modLockSignOut() {
    try {
        localStorage.removeItem("loggedIn");
        // keep azoraAccount so appeal form can prefill if desired
    } catch (e) {}
    location.reload();
}

function showModerationLockScreen(mod, username) {
    var ov = document.getElementById("moderationLockOverlay");
    if (!ov) return;
    var title = document.getElementById("modLockTitle");
    var msg = document.getElementById("modLockMessage");
    var dur = document.getElementById("modLockDuration");
    var link = document.getElementById("modLockAppealLink");
    var own = document.getElementById("modLockOwnerOverride");
    var kind = document.getElementById("modLockKindTag");
    var reasonBox = document.getElementById("modLockReasonBox");

    ov.style.display = "flex";

    if (mod.kind === "termination") {
        if (kind) { kind.textContent = "Account Terminated"; kind.className = "mod-lock-kind termination"; }
        if (title) title.textContent = "Account Terminated";
        if (msg) msg.textContent = "Your access to Azora has been permanently restricted pending staff review of any appeal.";
        if (dur) {
            dur.style.display = "block";
            dur.innerHTML = "Status: <strong>Terminated</strong><br>This is not a timed restriction.";
        }
        if (link) {
            link.href = "appeal.html?user=" + encodeURIComponent(username) + "&type=termination";
            link.textContent = "Submit an appeal";
        }
    } else {
        if (kind) { kind.textContent = "Temporary Ban"; kind.className = "mod-lock-kind ban"; }
        if (title) title.textContent = "You have been banned";
        if (msg) msg.textContent = "Your account is temporarily restricted from using Azora.";
        var left = mod.remainingMs != null ? formatBanDuration(mod.remainingMs) : "";
        var untilStr = mod.until ? new Date(mod.until).toLocaleString() : "";
        var total = (mod.from && mod.until) ? formatBanDuration(mod.until - mod.from) : "";
        if (dur) {
            dur.style.display = "block";
            dur.innerHTML =
                (total ? ("Ban length: <strong>" + total + "</strong><br>") : "") +
                (left ? ("Time remaining: <strong>" + left + "</strong><br>") : "") +
                (untilStr ? ("Ban ends: " + untilStr) : "");
        }
        if (link) {
            link.href = "appeal.html?user=" + encodeURIComponent(username) + "&type=ban";
            link.textContent = "Submit an appeal";
        }
    }

    if (reasonBox) {
        var label = mod.reasonLabel || mod.reason || "";
        // Prefer clean reason without appended note
        if (mod.note && label.indexOf(" — ") !== -1) {
            label = label.split(" — ")[0];
        }
        if (label) {
            reasonBox.style.display = "block";
            reasonBox.innerHTML = "<strong>Reason:</strong> " + String(label).replace(/</g, "&lt;");
        } else {
            reasonBox.style.display = "none";
            reasonBox.innerHTML = "";
        }
    }

    var noteBox = document.getElementById("modLockNoteBox");
    if (noteBox) {
        var noteText = mod.note || "";
        if (!noteText && mod.reason && String(mod.reason).indexOf(" — ") !== -1) {
            noteText = String(mod.reason).split(" — ").slice(1).join(" — ");
        }
        if (noteText) {
            noteBox.style.display = "block";
            noteBox.innerHTML = "<strong>Note:</strong> " + String(noteText).replace(/</g, "&lt;");
        } else {
            noteBox.style.display = "none";
            noteBox.innerHTML = "";
        }
    }

    if (own) {
        // Only the real Azora owner session sees override — never other players
        var showOverride = false;
        try {
            showOverride = isOwnerUsername(username) && isAzoraOwner() && localStorage.getItem("loggedIn") === "true";
        } catch (eO) { showOverride = false; }
        own.style.display = showOverride ? "block" : "none";
    }
}

function checkModerationOnBoot() {
    try {
        try { refreshOwnerModButton(); } catch (eR) {}
        ensureSystemElement();
        if (localStorage.getItem("loggedIn") !== "true") return;
        var acc = JSON.parse(localStorage.getItem("azoraAccount") || "null");
        if (!acc || !acc.username || acc.isGuest) return;
        var mod = getActiveModerationForUser(acc.username);
        if (mod && mod.active) {
            showModerationLockScreen(mod, acc.username);
        }
    } catch (e) {}
}

function renderProfileBadges(username) {
    var el = document.getElementById("profileBadges");
    if (!el) return;
    el.innerHTML = "";
    el.style.display = "none";
    username = String(username || "");

    if (isSystemUsername(username)) {
        el.style.display = "flex";
        el.innerHTML =
            '<span class="azora-badge system">⚙️ System Element</span>' +
            '<span class="azora-badge staff">Aza: 2</span>';
        return;
    }

    if (!isOwnerUsername(username)) return;

    el.style.display = "flex";
    el.innerHTML =
        '<span class="azora-badge verified">✓ Verified</span>' +
        '<span class="azora-badge founder">★ Founder</span>' +
        '<span class="azora-badge dev">🛠️ Main Developer</span>' +
        '<span class="azora-badge admin">🛡️ Super Admin</span>' +
        '<span class="azora-badge staff">Official</span>';
}

function appendOwnerModPanel(actionsEl, targetUsername) {
    if (!actionsEl) return;
    if (!isAzoraOwner()) return;
    if (isSystemUsername(targetUsername)) {
        var note = document.createElement("p");
        note.style.cssText = "color:#6366f1;font-size:13px;margin-top:10px;";
        note.textContent = "system is a System Element (Aza: 2) — not a real player.";
        actionsEl.appendChild(note);
        return;
    }
    if (!actionsEl.querySelector(".owner-security-msg-btn")) {
        var msgBtn = document.createElement("button");
        msgBtn.type = "button";
        msgBtn.className = "owner-security-msg-btn";
        msgBtn.textContent = "📨 Security message (notification)";
        msgBtn.style.cssText = "width:100%;margin-top:10px;background:linear-gradient(180deg,#1e3a5f,#0f172a);color:#7dd3fc;border:1px solid #38bdf8;font-weight:700;";
        msgBtn.onclick = function (e) {
            if (e) { e.preventDefault(); e.stopPropagation(); }
            openOwnerSecurityMessage(targetUsername);
        };
        actionsEl.appendChild(msgBtn);
    }
    if (actionsEl.querySelector(".owner-mod-open-btn")) return;
    var btn = document.createElement("button");
    btn.type = "button";
    btn.className = "owner-mod-open-btn";
    btn.textContent = "🛡️ Moderate this user…";
    btn.style.cssText = "width:100%;margin-top:10px;background:#111;color:#fff;border:1px solid #444;";
    btn.onclick = function (e) {
        if (e) { e.preventDefault(); e.stopPropagation(); }
        openOwnerModConsole(targetUsername);
    };
    actionsEl.appendChild(btn);
}

/** Owner-only: send a security notification to any player (no friendship required). */
function openOwnerSecurityMessage(targetUsername) {
    if (typeof isAzoraOwner === "function" && !isAzoraOwner()) {
        alert("Only the Azora owner can send security messages.");
        return;
    }
    targetUsername = String(targetUsername || "").trim();
    if (!targetUsername) return;
    // Prefer resolved safe name
    try {
        if (typeof resolvePublicUsername === "function") {
            var r = resolvePublicUsername(targetUsername);
            if (r && !(typeof isEmailLikeString === "function" && isEmailLikeString(r))) targetUsername = r;
        }
    } catch (e) {}

    var existing = document.getElementById("ownerSecurityMsgOverlay");
    if (existing) existing.remove();
    var ov = document.createElement("div");
    ov.id = "ownerSecurityMsgOverlay";
    ov.className = "overlay";
    ov.style.cssText = "display:flex;z-index:12050;background:rgba(15,23,42,0.85);";
    ov.innerHTML =
        '<div class="popup" style="max-width:min(400px,calc(100vw - 24px));text-align:left;background:#0f172a;border:1px solid #38bdf8;color:#e2e8f0;">' +
        '<h2 style="margin:0 0 8px;color:#7dd3fc !important;">📨 Security message</h2>' +
        '<p style="margin:0 0 10px;font-size:13px;color:#94a3b8 !important;">To: <strong style="color:#fff;">' +
        String(targetUsername).replace(/</g, "&lt;") +
        '</strong><br>Appears in their <strong>Notifications</strong>. Friendship not required. For security / account notices only.</p>' +
        '<textarea id="ownerSecurityMsgText" maxlength="400" placeholder="Write your security message…" style="width:100%;min-height:110px;box-sizing:border-box;padding:10px;border-radius:8px;border:1px solid #334155;background:#1e293b;color:#f1f5f9;resize:vertical;"></textarea>' +
        '<p id="ownerSecurityMsgStatus" style="display:none;font-size:12px;margin:8px 0 0;"></p>' +
        '<button type="button" id="ownerSecurityMsgSend" style="width:100%;margin-top:12px;background:linear-gradient(180deg,#38bdf8,#0284c7);color:#fff;border:none;padding:12px;border-radius:10px;font-weight:700;">Send notification</button>' +
        '<button type="button" id="ownerSecurityMsgCancel" class="secondary" style="width:100%;margin-top:8px;">Cancel</button>' +
        '</div>';
    document.body.appendChild(ov);
    document.getElementById("ownerSecurityMsgCancel").onclick = function () { ov.remove(); };
    document.getElementById("ownerSecurityMsgSend").onclick = function () {
        var ta = document.getElementById("ownerSecurityMsgText");
        var st = document.getElementById("ownerSecurityMsgStatus");
        var msg = ta ? String(ta.value || "").trim() : "";
        if (!msg) {
            if (st) { st.style.display = "block"; st.style.color = "#f87171"; st.textContent = "Write a message first."; }
            return;
        }
        if (msg.length > 400) msg = msg.slice(0, 400);
        var full = "🛡️ Security notice from Azora: " + msg;
        try {
            if (typeof pushNotification === "function") {
                pushNotification(targetUsername, full, "security", {
                    from: "Azora",
                    ownerSecurity: true,
                    at: Date.now()
                });
            }
        } catch (eN) {}
        // Cloud mirror so other devices see it
        try {
            if (typeof pushNotifToCloud === "function") {
                pushNotifToCloud(targetUsername, {
                    id: "sec_" + Date.now(),
                    message: full,
                    type: "security",
                    meta: { from: "Azora", ownerSecurity: true },
                    read: false,
                    at: Date.now()
                });
            }
        } catch (eC) {}
        if (st) { st.style.display = "block"; st.style.color = "#34d399"; st.textContent = "Sent to " + targetUsername + "’s notifications."; }
        if (typeof playClickSound === "function") playClickSound();
        setTimeout(function () { ov.remove(); }, 900);
    };
}
window.openOwnerSecurityMessage = openOwnerSecurityMessage;


function getPublicUserId_systemPatch(username) {
    if (isSystemUsername(username)) return "Aza: 2";
    return null;
}

// Patch getPublicUserId if present
(function patchGetPublicUserId() {
    if (typeof getPublicUserId !== "function") return;
    var _orig = getPublicUserId;
    window.getPublicUserId = function (username, accountHint) {
        if (isSystemUsername(username)) return "Aza: 2";
        return _orig(username, accountHint);
    };
})();

// Enrich search — local + cloud registry (finds users on other devices)
(function patchPerformSearch() {
    if (typeof performSearch !== "function") return;

    var _cloudUserCache = null;
    var _cloudUserCacheAt = 0;

    function mergeLocalRegistry(list) {
        try {
            var reg = JSON.parse(localStorage.getItem("azoraUserRegistry") || "[]");
            if (!Array.isArray(reg)) reg = [];
            var byName = {};
            reg.forEach(function (u) {
                if (u && u.username) byName[String(u.username).toLowerCase()] = u;
            });
            (list || []).forEach(function (u) {
                if (!u || !u.username) return;
                byName[String(u.username).toLowerCase()] = Object.assign({}, byName[String(u.username).toLowerCase()] || {}, u);
            });
            var out = Object.keys(byName).map(function (k) { return byName[k]; });
            localStorage.setItem("azoraUserRegistry", JSON.stringify(out));
            return out;
        } catch (e) {
            return list || [];
        }
    }

    function gatherLocalUsers() {
        var map = {};
        function addU(u) {
            if (!u) return;
            var name = u.username || u.name || "";
            if (!name) return;
            // Drop email-as-username ghosts from public search list (owner tools still use private map)
            if (typeof isEmailLikeString === "function" && isEmailLikeString(name)) {
                try {
                    var emap = JSON.parse(localStorage.getItem("azoraPrivateEmails") || "{}");
                    var mapped = emap["email:" + String(name).toLowerCase()];
                    if (mapped) name = mapped;
                    else return; // no public row for unresolved email usernames
                } catch (eE) { return; }
            }
            var key = String(name).toLowerCase();
            var prev = map[key] || {};
            map[key] = {
                username: name,
                userId: u.userId || prev.userId || "",
                email: u.email || prev.email || "",
                isSystemElement: !!(u.isSystemElement || prev.isSystemElement),
                isOwner: !!(u.isOwner || prev.isOwner),
                createdAt: u.createdAt || prev.createdAt || null
            };
        }
        try {
            if (typeof database !== "undefined" && database.users) database.users.forEach(addU);
        } catch (e0) {}
        try {
            var reg = JSON.parse(localStorage.getItem("azoraUserRegistry") || "[]");
            if (Array.isArray(reg)) reg.forEach(addU);
        } catch (e1) {}
        try {
            var accounts = (typeof getSavedAccounts === "function")
                ? getSavedAccounts()
                : JSON.parse(localStorage.getItem("azoraAccounts") || "{}");
            Object.keys(accounts || {}).forEach(function (k) {
                var a = accounts[k];
                if (!a || a.isGuest) return;
                addU({
                    username: a.username || k,
                    userId: a.userId,
                    email: a.email || "",
                    isOwner: !!(a.isOwner || String(a.username || k).toLowerCase() === "azora"),
                    createdAt: a.createdAt
                });
            });
        } catch (e2) {}
        try {
            var social = typeof getSocialData === "function" ? getSocialData() : {};
            Object.keys(social || {}).forEach(function (k) { addU({ username: k }); });
        } catch (e3) {}
        try {
            var acc = JSON.parse(localStorage.getItem("azoraAccount") || "null");
            if (acc && !acc.isGuest && acc.username) {
                addU({ username: acc.username, userId: acc.userId, email: acc.email || "" });
            }
        } catch (e4) {}
        addU({ username: "system", userId: "Aza: 2", isSystemElement: true });
        addU({ username: "Azora", userId: "Aza: 0", isOwner: true });
        if (_cloudUserCache && Array.isArray(_cloudUserCache)) {
            _cloudUserCache.forEach(addU);
        }
        try {
            if (window._azoraCloudUsers && Array.isArray(window._azoraCloudUsers)) {
                window._azoraCloudUsers.forEach(addU);
            }
        } catch (eCloud) {}
        return Object.keys(map).map(function (k) { return map[k]; });
    }

    function userMatchesQuery(u, query) {
        if (!query) return true;
        var un = String(u.username || "").toLowerCase();
        var id = String(u.userId || "").toLowerCase();
        // Public search never matches against private email fields
        // If username itself looks like an email, only owner search can find the local-part
        var isOwner = false;
        try { isOwner = typeof isAzoraOwner === "function" && isAzoraOwner(); } catch (eO) {}
        if (un.indexOf("@") !== -1) {
            // Email-as-username: hide from normal search; owner can still find by full string or local-part
            if (!isOwner) return false;
            if (un.indexOf(query) !== -1) return true;
            var localPart = un.split("@")[0] || "";
            if (localPart && localPart.indexOf(query) !== -1) return true;
        } else {
            if (un.indexOf(query) !== -1) return true;
        }
        if (id.indexOf(query) !== -1) return true;
        // Owner-only: match private email index
        if (isOwner) {
            var em = String(u.email || "").toLowerCase();
            if (em && em.indexOf(query) !== -1) return true;
        }
        var q2 = query.replace(/\s+/g, " ");
        if (id.replace(/\s+/g, " ").indexOf(q2) !== -1) return true;
        return false;
    }

    function renderUserResults(results, resultsContainer) {
        if (!results.length) {
            resultsContainer.innerHTML = "<div class='no-results'>No results found.</div>";
            return;
        }
        results.forEach(function (item) {
            var row = document.createElement("div");
            row.className = "search-result-item";
            var extra = "";
            try {
                if (item.isSystemElement || (typeof isSystemUsername === "function" && isSystemUsername(item.username))) {
                    extra = " <span class='sys-tag'>System Element</span>";
                } else if (item.isOwner || (typeof isOwnerUsername === "function" && isOwnerUsername(item.username))) {
                    extra = " <span class='sys-tag'>Owner</span>";
                }
            } catch (eX) {}
            var idBit = item.userId ? (' <span style="opacity:0.7;font-size:12px;">' + String(item.userId).replace(/</g, "&lt;") + "</span>") : "";
            var displayName = (typeof publicUsernameLabel === "function") ? publicUsernameLabel(item.username) : item.username;
            var isOwner = false;
            try { isOwner = typeof isAzoraOwner === "function" && isAzoraOwner(); } catch (eO2) {}
            // Owner sees a privacy note if the stored username was an email
            if (isOwner && String(item.username || "").indexOf("@") !== -1) {
                extra += ' <span class="sys-tag">email-as-username (private)</span>';
            }
            row.innerHTML = "👤 <strong>" + String(displayName).replace(/</g, "&lt;") + "</strong>" + idBit + extra + " ";
            var viewBtn = document.createElement("a");
            viewBtn.href = "#";
            viewBtn.className = "search-action-btn";
            viewBtn.textContent = "View";
            viewBtn.onclick = function (e) {
                e.preventDefault();
                try { closeSearch(); } catch (err) {}
                // Profile lookup still uses the real stored key
                if (typeof openUserProfile === "function") openUserProfile(item.username);
            };
            row.appendChild(viewBtn);
            resultsContainer.appendChild(row);
        });
    }

    function refreshCloudUsers(done) {
        done = done || function () {};
        if (typeof fetchGlobalRegistry !== "function") {
            done([]);
            return;
        }
        // Cache 15s while typing; openSearch forces refresh via fetchGlobalRegistry
        if (_cloudUserCache && (Date.now() - _cloudUserCacheAt) < 15000) {
            done(_cloudUserCache);
            return;
        }
        fetchGlobalRegistry(function (err, list) {
            list = Array.isArray(list) ? list : [];
            _cloudUserCache = list;
            _cloudUserCacheAt = Date.now();
            try { mergeLocalRegistry(list); } catch (e) {}
            done(list);
        });
    }

    window.performSearch = function () {
        try {
            if (typeof ensureSystemElement === "function") ensureSystemElement();
        } catch (eS) {}
        var input = document.getElementById("searchInput");
        var resultsContainer = document.getElementById("searchResultsContainer");
        if (!resultsContainer) return;
        var query = (input && input.value ? input.value : "").trim().toLowerCase();
        resultsContainer.innerHTML = "";

        if (currentSearchTab === "users") {
            // Local-first immediate results
            var localList = gatherLocalUsers();
            var localHits = localList.filter(function (u) { return userMatchesQuery(u, query); });
            if (localHits.length) {
                renderUserResults(localHits, resultsContainer);
            } else {
                resultsContainer.innerHTML = "<div class='no-results'>Searching…</div>";
            }
            // Then refresh from cloud and re-render
            refreshCloudUsers(function () {
                var all = gatherLocalUsers();
                var hits = all.filter(function (u) { return userMatchesQuery(u, query); });
                resultsContainer.innerHTML = "";
                renderUserResults(hits, resultsContainer);
            });
            return;
        }

        // Games tab
        var games = (typeof database !== "undefined" && database.games) ? database.games.slice() : [];
        try {
            if (typeof azaFnGames !== "undefined" && Array.isArray(azaFnGames)) {
                azaFnGames.forEach(function (g) {
                    if (!g || g.deleted) return;
                    if (g.published === false) return;
                    games.push({
                        title: g.title || "Untitled",
                        author: g.creator || "Player",
                        link: "#",
                        type: "feed",
                        id: g.id
                    });
                });
            }
        } catch (eG) {}
        var gHits = games.filter(function (g) {
            if (!query) return true;
            return String(g.title || "").toLowerCase().indexOf(query) !== -1 ||
                String(g.author || "").toLowerCase().indexOf(query) !== -1;
        });
        if (!gHits.length) {
            resultsContainer.innerHTML = "<div class='no-results'>No results found.</div>";
            return;
        }
        gHits.forEach(function (item) {
            var row = document.createElement("div");
            row.className = "search-result-item";
            row.innerHTML = "🎮 <strong>" + String(item.title).replace(/</g, "&lt;") +
                "</strong> <span class=\"creator-by\">by " + String(item.author).replace(/</g, "&lt;") + "</span> ";
            var play = document.createElement("a");
            play.href = "#";
            play.className = "search-action-btn";
            play.textContent = "Play";
            play.onclick = function (e) {
                e.preventDefault();
                try { closeSearch(); } catch (err) {}
                try {
                    if (item.id && typeof openGamePreview === "function") openGamePreview(item.id);
                    else if (typeof openNormGames === "function") openNormGames();
                } catch (e2) {}
            };
            row.appendChild(play);
            resultsContainer.appendChild(row);
        });
    };
})();

