// ============================================================
// Profile 3D spinning avatar (separate from customizer scene)
// ============================================================
var _profile3d = {
    renderer: null,
    scene: null,
    camera: null,
    group: null,
    raf: 0,
    spinning: true,
    username: null
};

function getAvatarDataForUsername(username) {
    username = String(username || "").trim();
    var me = "";
    try { me = typeof getMyUsername === "function" ? String(getMyUsername() || "") : ""; } catch (eM) {}
    var viewingSelf = !!(me && username && me.toLowerCase() === username.toLowerCase());

    function cloneAvatar(src, genderHint) {
        src = src || {};
        var g = (src.gender === "girl" || src.gender === "female" || genderHint === "girl" || genderHint === "female") ? "girl" : "boy";
        var base = (typeof defaultAvatarForGender === "function") ? defaultAvatarForGender(g) : {
            gender: g, head: "#ffcc00", torso: "#1e60ff", leftArm: "#ffcc00", rightArm: "#ffcc00",
            leftLeg: "#00ebd4", rightLeg: "#00ebd4", hair: "#3b2f2f", face: "default"
        };
        // Explicit field copy — never keep a live reference to someone else's (or my) account object
        return {
            gender: g,
            head: src.head || base.head,
            torso: src.torso || base.torso,
            leftArm: src.leftArm || base.leftArm,
            rightArm: src.rightArm || base.rightArm,
            leftLeg: src.leftLeg || base.leftLeg,
            rightLeg: src.rightLeg || base.rightLeg,
            hair: src.hair || base.hair,
            hairStyle: src.hairStyle || "hair_boy_none",
            face: src.face || base.face || "default",
            faceFile: src.faceFile || null,
            scales: src.scales ? {
                head: src.scales.head || 1,
                torso: src.scales.torso || 1,
                arms: src.scales.arms || 1,
                legs: src.scales.legs || 1
            } : { head: 1, torso: 1, arms: 1, legs: 1 }
        };
    }

    // A) Viewing yourself — only then may we use the live session account
    if (viewingSelf) {
        try {
            var cur = JSON.parse(localStorage.getItem("azoraAccount") || "null");
            if (cur && !cur.isGuest && cur.avatar) {
                return cloneAvatar(cur.avatar, cur.gender);
            }
        } catch (eSelf) {}
    }

    // B) Public avatar cache (written when anyone saves, or pulled from cloud)
    try {
        var pub = JSON.parse(localStorage.getItem("azoraPublicAvatars") || "{}");
        var hit = pub[username] || pub[username.toLowerCase()];
        if (hit && typeof hit === "object") {
            // Ignore cache entries that were wrongly tagged with the viewer's data for another user
            var ownerTag = hit._forUser || hit.username || null;
            if (ownerTag && String(ownerTag).toLowerCase() !== username.toLowerCase()) {
                hit = null;
            }
            if (hit) return cloneAvatar(hit, hit.gender);
        }
    } catch (ePub) {}

    // C) Local account map — ONLY if this exact username owns that entry
    try {
        var map = typeof getSavedAccounts === "function" ? getSavedAccounts() : JSON.parse(localStorage.getItem("azoraAccounts") || "{}");
        var keys = Object.keys(map || {});
        for (var i = 0; i < keys.length; i++) {
            var a = map[keys[i]];
            if (!a || a.isGuest || !a.avatar) continue;
            var un = String(a.username || keys[i] || "");
            if (un.toLowerCase() !== username.toLowerCase()) continue;
            // Do not use MY account data when viewing someone else
            if (!viewingSelf && me && un.toLowerCase() === me.toLowerCase()) continue;
            return cloneAvatar(a.avatar, a.gender);
        }
    } catch (e1) {}

    // D) Social blob avatar (if synced)
    try {
        var social = typeof getSocialData === "function" ? getSocialData() : {};
        var skey = Object.keys(social || {}).find(function (k) { return String(k).toLowerCase() === username.toLowerCase(); });
        if (skey && social[skey] && social[skey].avatar) {
            return cloneAvatar(social[skey].avatar, social[skey].avatar.gender);
        }
    } catch (e3) {}

    // E) Neutral default for that user — NEVER fall back to the viewer's avatar
    if (typeof isOwnerUsername === "function" && isOwnerUsername(username)) {
        return cloneAvatar({
            gender: "boy", head: "#ffcc00", torso: "#1e60ff", leftArm: "#ffcc00", rightArm: "#ffcc00",
            leftLeg: "#00ebd4", rightLeg: "#00ebd4", hair: "#3b2f2f", hairStyle: "hair_boy_none"
        }, "boy");
    }
    return cloneAvatar(null, "boy");
}

/** Persist a user's avatar so other profiles on this device (and cloud) can show it. */
function publishPublicAvatar(username, avatar) {
    username = String(username || "").trim();
    if (!username || !avatar) return;
    try {
        var pub = JSON.parse(localStorage.getItem("azoraPublicAvatars") || "{}");
        var copy = {
            _forUser: username,
            username: username,
            gender: avatar.gender || "boy",
            head: avatar.head, torso: avatar.torso,
            leftArm: avatar.leftArm, rightArm: avatar.rightArm,
            leftLeg: avatar.leftLeg, rightLeg: avatar.rightLeg,
            hair: avatar.hair, hairStyle: avatar.hairStyle, face: avatar.face,
            faceFile: avatar.faceFile || null,
            scales: avatar.scales || null,
            updatedAt: Date.now()
        };
        pub[username] = copy;
        pub[username.toLowerCase()] = copy;
        localStorage.setItem("azoraPublicAvatars", JSON.stringify(pub));
    } catch (e) {}
    // Cloud path for cross-device profile previews
    try {
        if (typeof isCloudSocialReady === "function" && isCloudSocialReady() && typeof cloudBase === "function" && typeof cloudPutJson === "function") {
            var safe = encodeURIComponent(username.toLowerCase().replace(/[.#$\/\[\]]/g, "_"));
            var url = cloudBase() + "/azoraAvatars/" + safe + ".json";
            cloudPutJson(url, {
                username: username,
                avatar: {
                    gender: avatar.gender || "boy",
                    head: avatar.head, torso: avatar.torso,
                    leftArm: avatar.leftArm, rightArm: avatar.rightArm,
                    leftLeg: avatar.leftLeg, rightLeg: avatar.rightLeg,
                    hair: avatar.hair, hairStyle: avatar.hairStyle, face: avatar.face,
                    faceFile: avatar.faceFile || null,
                    scales: avatar.scales || null
                },
                updatedAt: Date.now()
            }).catch(function () {});
        }
    } catch (eC) {}
}
window.publishPublicAvatar = publishPublicAvatar;

/** Fetch another player's public avatar from cloud, then refresh profile 3D. */
function fetchPublicAvatarFromCloud(username, callback) {
    callback = callback || function () {};
    username = String(username || "").trim();
    if (!username) { callback(null); return; }
    try {
        if (!(typeof isCloudSocialReady === "function" && isCloudSocialReady())) { callback(null); return; }
        var safe = encodeURIComponent(username.toLowerCase().replace(/[.#$\/\[\]]/g, "_"));
        var url = cloudBase() + "/azoraAvatars/" + safe + ".json";
        cloudFetchJson(url).then(function (data) {
            if (data && data.avatar && typeof data.avatar === "object") {
                // Local cache only — do not re-upload
                try {
                    var pub = JSON.parse(localStorage.getItem("azoraPublicAvatars") || "{}");
                    pub[username] = data.avatar;
                    pub[username.toLowerCase()] = data.avatar;
                    localStorage.setItem("azoraPublicAvatars", JSON.stringify(pub));
                } catch (eL) {}
                callback(data.avatar);
            } else {
                callback(null);
            }
        }).catch(function () { callback(null); });
    } catch (e) { callback(null); }
}
window.fetchPublicAvatarFromCloud = fetchPublicAvatarFromCloud;
window.getAvatarDataForUsername = getAvatarDataForUsername;

function _profile3dMat(color) {
    try {
        if (typeof azoraGlossMaterial === "function") return azoraGlossMaterial(color);
    } catch (e) {}
    try {
        return new THREE.MeshPhongMaterial({ color: color, shininess: 80, specular: 0xaaaaaa });
    } catch (e2) {
        return new THREE.MeshLambertMaterial({ color: color });
    }
}

function _profile3dBox(w, h, d, color) {
    var radius = Math.min(w, h, d) * 0.08;
    var geo = (typeof azoraRoundedBoxGeometry === "function")
        ? azoraRoundedBoxGeometry(w, h, d, radius)
        : new THREE.BoxGeometry(w, h, d);
    return new THREE.Mesh(geo, _profile3dMat(color));
}

function buildProfile3DCharacter(avatar) {
    avatar = avatar || {};
    var gender = (avatar.gender === "girl" || avatar.gender === "female") ? "girl" : "boy";
    var headC = avatar.head || (gender === "girl" ? "#ffcc99" : "#ffcc00");
    var torsoC = avatar.torso || (gender === "girl" ? "#ff6eb4" : "#1e60ff");
    var la = avatar.leftArm || headC;
    var ra = avatar.rightArm || headC;
    var ll = avatar.leftLeg || (gender === "girl" ? "#c084fc" : "#00ebd4");
    var rl = avatar.rightLeg || ll;
    var hairC = avatar.hair || (gender === "girl" ? "#4a3728" : "#3b2f2f");

    var group = new THREE.Group();

    var head = _profile3dBox(0.65, 0.65, 0.65, headC);
    head.position.y = 1.12;
    group.add(head);

    // Face decal — ONLY from THIS avatar, never the viewer's equipped inventory
    try {
        var faceUrl = null;
        if (avatar.faceFile && typeof avatar.faceFile === "string") {
            faceUrl = avatar.faceFile;
        } else if (avatar.face && String(avatar.face).indexOf(".png") !== -1) {
            faceUrl = avatar.face;
        } else if (avatar.face && avatar.face !== "default" && avatar.face !== "male" && avatar.face !== "female") {
            // shop face id → file
            try {
                if (typeof faceCatalogById === "function") {
                    var fi = faceCatalogById(avatar.face);
                    if (fi && fi.file) faceUrl = fi.file;
                }
            } catch (eCat) {}
        }
        if (!faceUrl) {
            faceUrl = (gender === "girl") ? "female_smile.png" : "Smile.png";
        }
        var loader = new THREE.TextureLoader();
        loader.load(faceUrl, function (tex) {
            try {
                tex.minFilter = THREE.LinearFilter;
                tex.magFilter = THREE.LinearFilter;
                tex.generateMipmaps = false;
                var mat = new THREE.MeshBasicMaterial({
                    map: tex, transparent: true, depthWrite: false, alphaTest: 0.15, side: THREE.FrontSide
                });
                var plane = new THREE.Mesh(new THREE.PlaneGeometry(0.54, 0.54), mat);
                plane.position.set(0, 1.12, 0.34);
                group.add(plane);
            } catch (eF) {}
        }, undefined, function () {});
    } catch (eFace) {}

    var girlDef = gender === "girl" && (typeof isDefaultGirlBody !== "function" || isDefaultGirlBody(avatar, gender));
    // Less-chibi base: smaller head, taller torso/legs. Girl: slightly narrower.
    var torsoW = girlDef ? 0.68 : 0.78;
    var torsoH = girlDef ? 1.14 : 1.12;
    var torsoD = girlDef ? 0.40 : 0.42;
    var armS = girlDef ? 0.26 : 0.30;
    var legS = girlDef ? 0.26 : 0.30;
    var armX = girlDef ? 0.50 : 0.56;
    var legX = girlDef ? 0.14 : 0.18;
    var headS = girlDef ? 0.50 : 0.52;
    var headY = 1.28;
    var torsoY = 0.42;
    var armY = 0.42;
    var legY = -0.70;

    // Rebuild head with correct size for both genders
    try { group.remove(head); } catch (eRh) {}
    head = _profile3dBox(headS, headS, headS, headC);
    head.position.y = headY;
    group.add(head);

    var torso = _profile3dBox(torsoW, torsoH, torsoD, torsoC);
    torso.position.y = torsoY;
    group.add(torso);

    if (girlDef) {
        try {
            var flare = _profile3dBox(0.80, 0.24, 0.44, torsoC);
            flare.position.set(0, -0.02, 0);
            flare.name = "girlHipFlare";
            group.add(flare);
        } catch (eFl) {}
    }

    var leftArm = _profile3dBox(armS, 1.08, armS, la);
    leftArm.position.set(-armX, armY, 0);
    group.add(leftArm);
    var rightArm = _profile3dBox(armS, 1.08, armS, ra);
    rightArm.position.set(armX, armY, 0);
    group.add(rightArm);

    var leftLeg = _profile3dBox(legS, 1.12, legS, ll);
    leftLeg.position.set(-legX, legY, 0);
    group.add(leftLeg);
    var rightLeg = _profile3dBox(legS, 1.12, legS, rl);
    rightLeg.position.set(legX, legY, 0);
    group.add(rightLeg);

    // Hair only if equipped — default boys AND girls are bald
    try {
        var styleId = avatar.hairStyle || "hair_boy_none";
        if (styleId === "hair_girl_default") styleId = "hair_boy_none";
        if (typeof makeAvatarHair === "function" && styleId && styleId !== "hair_boy_none" && styleId !== "none") {
            var hair = makeAvatarHair(hairC, 1.12, headS, styleId);
            if (hair) group.add(hair);
        }
    } catch (eH) {}

    return group;
}

function disposeProfile3DAvatar() {
    try {
        if (_profile3d.raf) {
            cancelAnimationFrame(_profile3d.raf);
            _profile3d.raf = 0;
        }
    } catch (e) {}
    try {
        if (_profile3d.renderer) {
            _profile3d.renderer.dispose();
            var canvas = document.getElementById("profile3dCanvas");
            if (canvas && _profile3d.renderer.domElement && _profile3d.renderer.domElement.parentNode === canvas.parentNode) {
                // we render onto the existing canvas via { canvas: ... }
            }
        }
    } catch (e2) {}
    try {
        if (_profile3d.scene) {
            _profile3d.scene.traverse(function (obj) {
                if (obj.geometry) obj.geometry.dispose();
                if (obj.material) {
                    if (Array.isArray(obj.material)) obj.material.forEach(function (m) { try { m.dispose(); } catch (e) {} });
                    else try { obj.material.dispose(); } catch (e) {}
                }
            });
        }
    } catch (e3) {}
    _profile3d.renderer = null;
    _profile3d.scene = null;
    _profile3d.camera = null;
    _profile3d.group = null;
    _profile3d.username = null;
}
window.disposeProfile3DAvatar = disposeProfile3DAvatar;

function showProfile3DAvatar(username) {
    try {
        if (typeof THREE === "undefined") {
            console.warn("[Azora] THREE.js not loaded — profile 3D avatar skipped");
            return;
        }
        var canvas = document.getElementById("profile3dCanvas");
        var wrap = document.getElementById("profile3dWrap");
        if (!canvas || !wrap) {
            console.warn("[Azora] profile3dCanvas missing");
            return;
        }
        wrap.style.display = "flex";

        disposeProfile3DAvatar();
        _profile3d.username = username;
        _profile3d.spinning = true;

        // Force visible size (CSS may still be settling)
        var w = Math.max(canvas.clientWidth || 0, wrap.clientWidth || 0, 200);
        var h = Math.max(canvas.clientHeight || 0, 240);
        canvas.style.width = w + "px";
        canvas.style.height = h + "px";

        var scene = new THREE.Scene();
        var camera = new THREE.PerspectiveCamera(35, w / h, 0.1, 100);
        // Character spans roughly y=-1.2 to y=1.5 — frame full body
        camera.position.set(0, 0.4, 3.6);
        camera.lookAt(0, 0.25, 0);

        var renderer;
        try {
            renderer = new THREE.WebGLRenderer({
                canvas: canvas,
                alpha: true,
                antialias: true,
                preserveDrawingBuffer: true
            });
        } catch (eGL) {
            console.warn("[Azora] WebGLRenderer failed", eGL);
            return;
        }
        renderer.setSize(w, h, false);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
        renderer.setClearColor(0x0b1a3a, 0); // transparent over CSS gradient

        var amb = new THREE.AmbientLight(0xffffff, 1.0);
        scene.add(amb);
        var dir = new THREE.DirectionalLight(0xffffff, 0.9);
        dir.position.set(2.5, 5, 3);
        scene.add(dir);
        var fill = new THREE.DirectionalLight(0xa5d8ff, 0.45);
        fill.position.set(-3, 2, -2);
        scene.add(fill);

        var avatarData = (typeof getAvatarDataForUsername === "function")
            ? getAvatarDataForUsername(username)
            : { gender: "boy", head: "#ffcc00", torso: "#1e60ff", leftArm: "#ffcc00", rightArm: "#ffcc00", leftLeg: "#00ebd4", rightLeg: "#00ebd4" };

        var group = buildProfile3DCharacter(avatarData);
        group.position.set(0, -0.2, 0);
        scene.add(group);

        // Soft ground disc so character doesn't float in void
        try {
            var disc = new THREE.Mesh(
                new THREE.CircleGeometry(0.9, 32),
                new THREE.MeshBasicMaterial({ color: 0x1e60ff, transparent: true, opacity: 0.18 })
            );
            disc.rotation.x = -Math.PI / 2;
            disc.position.y = -1.25;
            scene.add(disc);
        } catch (eD) {}

        _profile3d.scene = scene;
        _profile3d.camera = camera;
        _profile3d.renderer = renderer;
        _profile3d.group = group;

        function tick() {
            if (!_profile3d.renderer || _profile3d.username !== username) return;
            _profile3d.raf = requestAnimationFrame(tick);
            if (_profile3d.spinning && _profile3d.group) {
                _profile3d.group.rotation.y += 0.014;
            }
            try {
                _profile3d.renderer.render(_profile3d.scene, _profile3d.camera);
            } catch (eR) {}
        }
        tick();

        canvas.style.cursor = "pointer";
        canvas.onclick = function (e) {
            if (e) { e.preventDefault(); e.stopPropagation(); }
            _profile3d.spinning = !_profile3d.spinning;
        };

        // One immediate render so something appears even before next frame
        try { renderer.render(scene, camera); } catch (e0) {}
        console.log("[Azora] profile 3D avatar ready for", username, {
            head: avatarData.head, torso: avatarData.torso, gender: avatarData.gender, faceFile: avatarData.faceFile || avatarData.face
        });
    } catch (err) {
        console.warn("[Azora] showProfile3DAvatar error", err);
    }
}
window.showProfile3DAvatar = showProfile3DAvatar;
window.getAvatarDataForUsername = getAvatarDataForUsername;


