// Fun home hub — keep hero stats in sync
(function azoraFunHomeBoot() {
    function syncHero() {
        try {
            var coinsEl = document.getElementById("heroCoinsStat");
            var streakEl = document.getElementById("heroStreakStat");
            var coins = 0;
            try {
                var acc = JSON.parse(localStorage.getItem("azoraAccount") || "null");
                if (acc && typeof acc.coins === "number") coins = acc.coins;
                else coins = parseFloat(localStorage.getItem("azoraCoins") || "0") || 0;
            } catch (e) {}
            if (coinsEl) coinsEl.textContent = (Math.round(coins * 100) / 100).toString();
            var streak = 0;
            try { streak = parseInt(localStorage.getItem("azoraDailyStreak") || "0", 10) || 0; } catch (e2) {}
            if (streakEl) streakEl.textContent = String(streak);
            var dailyText = document.getElementById("azoraDailyFunText");
            if (dailyText) {
                var tips = [
                    "Come back every day for coins, streaks, and new things to try.",
                    "Jump into Azora Roleplay and say hi in chat!",
                    "Remix your avatar colors — then show up in a Norm Game.",
                    "Publish a Creator Studio world to Norm Games for friends to Join.",
                    "Open Shop for faces & hair, then equip them from Inventory."
                ];
                var i = Math.floor(Date.now() / 60000) % tips.length;
                dailyText.textContent = tips[i];
            }
        } catch (e) {}
    }
    if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", syncHero);
    else syncHero();
    setInterval(syncHero, 15000);
    window.azoraSyncFunHome = syncHero;
})();


// Remove AI product entry points from UI (AzaFn + AI Avatar). Arrow Friend stays.
(function removeAiProductUi() {
    function scrub() {
        ["azafnButton", "aiAvatarBtn", "azafnOverlay", "aiAvatarOverlay"].forEach(function (id) {
            var el = document.getElementById(id);
            if (!el) return;
            if (id.indexOf("Overlay") !== -1) {
                el.style.display = "none";
                try { el.remove(); } catch (e) { el.innerHTML = ""; }
            } else {
                el.style.display = "none";
                try { el.remove(); } catch (e2) {}
            }
        });
    }
    if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", scrub);
    else scrub();
    setTimeout(scrub, 500);
})();


// ============================================================
// Azora app update checker (PWA / service worker)
// ============================================================
var AZORA_APP_VERSION = "70.2";
var _azoraSwReg = null;
var _azoraUpdateWaiting = false;
var _azoraUpdateApplying = false;

function showAzoraUpdateBanner() {
    _azoraUpdateWaiting = true;
    var b = document.getElementById("azoraUpdateBanner");
    if (b) {
        b.classList.add("show");
        b.style.display = "block";
    }
    var st = document.getElementById("checkForUpdatesStatus");
    if (st) {
        st.textContent = "Oh I need to update my app! A newer version is ready.";
        st.style.color = "#fbbf24";
    }
}

function dismissAzoraUpdateBanner() {
    var b = document.getElementById("azoraUpdateBanner");
    if (b) {
        b.classList.remove("show");
        b.style.display = "none";
    }
}

/** Force-close current session and open the updated app */
function applyAzoraAppUpdate() {
    if (_azoraUpdateApplying) return;
    _azoraUpdateApplying = true;
    var btn = document.getElementById("azoraUpdateNowBtn");
    if (btn) {
        btn.disabled = true;
        btn.textContent = "Updating… closing Azora…";
    }
    try {
        if (typeof playClickSound === "function") playClickSound();
    } catch (e) {}

    function hardReload() {
        try {
            // Clear only the app cache keys so the next open is fresh
            if (window.caches && caches.keys) {
                caches.keys().then(function (keys) {
                    return Promise.all(keys.map(function (k) {
                        if (String(k).indexOf("azora") !== -1) return caches.delete(k);
                    }));
                }).finally(function () {
                    window.location.href = window.location.href.split("#")[0].split("?")[0] + "?updated=" + Date.now();
                });
                return;
            }
        } catch (e2) {}
        window.location.reload(true);
    }

    try {
        if (navigator.serviceWorker && navigator.serviceWorker.controller) {
            var reloaded = false;
            navigator.serviceWorker.addEventListener("controllerchange", function () {
                if (reloaded) return;
                reloaded = true;
                hardReload();
            });
        }
        if (_azoraSwReg && _azoraSwReg.waiting) {
            _azoraSwReg.waiting.postMessage({ type: "SKIP_WAITING" });
            // Fallback if controllerchange is slow
            setTimeout(hardReload, 1200);
            return;
        }
        if (_azoraSwReg) {
            _azoraSwReg.update().then(function () {
                if (_azoraSwReg.waiting) {
                    _azoraSwReg.waiting.postMessage({ type: "SKIP_WAITING" });
                    setTimeout(hardReload, 1200);
                } else {
                    hardReload();
                }
            }).catch(hardReload);
            return;
        }
    } catch (e3) {}
    hardReload();
}

function onAzoraServiceWorkerReady(reg) {
    _azoraSwReg = reg;
    try {
        if (reg.waiting) showAzoraUpdateBanner();
        reg.addEventListener("updatefound", function () {
            var installing = reg.installing;
            if (!installing) return;
            installing.addEventListener("statechange", function () {
                if (installing.state === "installed" && navigator.serviceWorker.controller) {
                    // New version ready while old one still controls page
                    showAzoraUpdateBanner();
                }
            });
        });
        // Periodic quiet check every 15 minutes
        setInterval(function () {
            try { reg.update(); } catch (e) {}
        }, 15 * 60 * 1000);
    } catch (e) {}
}

/** Manual "Check for updates" from Settings */
function checkForAzoraUpdates(fromSettings) {
    var st = document.getElementById("checkForUpdatesStatus");
    if (st) {
        st.textContent = "Checking for updates…";
        st.style.color = "#94a3b8";
    }
    if (!("serviceWorker" in navigator)) {
        if (st) st.textContent = "This browser cannot install app updates here. Refresh the page instead.";
        return;
    }
    var done = function (found) {
        if (found) {
            showAzoraUpdateBanner();
            if (st) {
                st.textContent = "Oh I need to update my app! Tap the update button below (or the banner).";
                st.style.color = "#fbbf24";
            }
            if (fromSettings && typeof showAzoraToast === "function") {
                showAzoraToast("Oh I need to update my app!");
            }
        } else {
            if (st) {
                st.textContent = "You're on the latest version of Azora (v" + AZORA_APP_VERSION + ").";
                st.style.color = "#86efac";
            }
            if (fromSettings && typeof showAzoraToast === "function") {
                showAzoraToast("You're up to date!");
            }
        }
    };
    navigator.serviceWorker.getRegistration("./sw-azora.js").then(function (reg) {
        if (!reg) {
            // Try default scope
            return navigator.serviceWorker.getRegistration().then(function (r2) { return r2; });
        }
        return reg;
    }).then(function (reg) {
        if (!reg) {
            // No SW — hard refresh suggestion still useful
            if (st) st.textContent = "No app service worker yet. Refresh the page to load the newest files.";
            return;
        }
        _azoraSwReg = reg;
        if (reg.waiting) {
            done(true);
            return;
        }
        return reg.update().then(function () {
            // After update(), waiting worker appears if a new one installed
            setTimeout(function () {
                if (reg.waiting) done(true);
                else if (reg.installing) {
                    reg.installing.addEventListener("statechange", function () {
                        if (reg.waiting || (reg.installing && reg.installing.state === "installed")) done(true);
                    });
                    setTimeout(function () {
                        if (reg.waiting) done(true);
                        else done(false);
                    }, 2500);
                } else {
                    done(false);
                }
            }, 600);
        });
    }).catch(function () {
        if (st) st.textContent = "Could not check right now. Try again on Wi‑Fi.";
    });
}

window.showAzoraUpdateBanner = showAzoraUpdateBanner;
window.dismissAzoraUpdateBanner = dismissAzoraUpdateBanner;
window.applyAzoraAppUpdate = applyAzoraAppUpdate;
window.checkForAzoraUpdates = checkForAzoraUpdates;
window.onAzoraServiceWorkerReady = onAzoraServiceWorkerReady;

// ============================================================

// CORNER SOFT-BLEND COLOR BLOOM
// Solid base color. From a random CORNER only, a new color expands
// as a soft circle whose OUTER EDGE fades to fully transparent so it
// blends into the color underneath (no hard cut between colors).
// ============================================================
(function initAzoraEdgeColorWipe() {
    var LIGHT_COLORS = [
        "#c026d3", "#a855f7", "#7c3aed", "#6366f1",
        "#2563eb", "#3b82f6", "#0ea5e9", "#06b6d4",
        "#8b5cf6", "#d946ef"
    ];
    var DARK_COLORS = [
        "#2e1065", "#4c1d95", "#1e1b4b", "#312e81",
        "#1e3a8a", "#172554", "#0f172a", "#3b0764",
        "#1e293b", "#4c1d95"
    ];

    // ONLY corners — never mid top / bottom / left / right
    var CORNERS = [
        { name: "top-left",     x: "0%",   y: "0%" },
        { name: "top-right",    x: "100%", y: "0%" },
        { name: "bottom-left",  x: "0%",   y: "100%" },
        { name: "bottom-right", x: "100%", y: "100%" }
    ];

    var baseEl = null;
    var waveEl = null;
    var currentColor = LIGHT_COLORS[2];
    var lastCorner = null;
    var timer = null;
    var rafId = null;
    var running = false;

    function palette() {
        try {
            if (document.documentElement.getAttribute("data-theme") === "dark") return DARK_COLORS;
        } catch (e) {}
        return LIGHT_COLORS;
    }

    function pickColor(avoid) {
        var list = palette();
        var pool = list.filter(function (c) { return c.toLowerCase() !== String(avoid || "").toLowerCase(); });
        if (!pool.length) pool = list;
        return pool[Math.floor(Math.random() * pool.length)];
    }

    function pickCorner() {
        var pool = CORNERS.filter(function (c) { return c.name !== lastCorner; });
        if (!pool.length) pool = CORNERS;
        var c = pool[Math.floor(Math.random() * pool.length)];
        lastCorner = c.name;
        return c;
    }

    function hexToRgba(hex, a) {
        var h = String(hex || "#000").replace("#", "");
        if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
        var n = parseInt(h, 16);
        if (!isFinite(n)) return "rgba(0,0,0," + a + ")";
        var r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
        return "rgba(" + r + "," + g + "," + b + "," + a + ")";
    }

    /**
     * Soft-blend radial gradient from a corner.
     * Core = new color. Toward the edge it becomes more transparent
     * so it mixes with the base color underneath — no hard cut-off.
     */
    function softBlendGradient(color, corner, radiusPx) {
        var r = Math.max(1, radiusPx);
        return "radial-gradient(circle at " + corner.x + " " + corner.y + ", " +
            color + " 0px, " +
            color + " " + (r * 0.10) + "px, " +
            hexToRgba(color, 0.82) + " " + (r * 0.26) + "px, " +
            hexToRgba(color, 0.55) + " " + (r * 0.42) + "px, " +
            hexToRgba(color, 0.32) + " " + (r * 0.58) + "px, " +
            hexToRgba(color, 0.14) + " " + (r * 0.74) + "px, " +
            "transparent " + r + "px)";
    }

    function ensureEls() {
        baseEl = document.getElementById("azoraBgBase");
        waveEl = document.getElementById("azoraBgWave");
        if (!baseEl || !waveEl) {
            var root = document.getElementById("azoraBgWipe");
            if (!root) {
                root = document.createElement("div");
                root.id = "azoraBgWipe";
                root.setAttribute("aria-hidden", "true");
                document.body.insertBefore(root, document.body.firstChild);
            }
            if (!baseEl) {
                baseEl = document.createElement("div");
                baseEl.className = "azora-bg-base";
                baseEl.id = "azoraBgBase";
                root.appendChild(baseEl);
            }
            if (!waveEl) {
                waveEl = document.createElement("div");
                waveEl.className = "azora-bg-wave";
                waveEl.id = "azoraBgWave";
                root.appendChild(waveEl);
            }
        }
        return !!(baseEl && waveEl);
    }

    function setSolid(el, color) {
        if (!el) return;
        el.style.background = color;
    }

    function maxRadiusNeeded() {
        var w = window.innerWidth || 1200;
        var h = window.innerHeight || 800;
        return Math.sqrt(w * w + h * h) * 1.4;
    }

    function easeInOut(t) {
        return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    }

    function runCycle() {
        if (!running || !ensureEls()) return;

        var next = pickColor(currentColor);
        var corner = pickCorner();
        var maxR = maxRadiusNeeded();
        var duration = 18000 + Math.floor(Math.random() * 10000); // 18–28s
        var startTime = performance.now();

        // Full-screen wave layer; only the soft radial grows from the corner
        waveEl.style.transition = "none";
        waveEl.style.inset = "0";
        waveEl.style.width = "100%";
        waveEl.style.height = "100%";
        waveEl.style.left = "0";
        waveEl.style.top = "0";
        waveEl.style.right = "0";
        waveEl.style.bottom = "0";
        waveEl.style.borderRadius = "0";
        waveEl.style.transform = "none";
        waveEl.style.clipPath = "none";
        waveEl.style.background = softBlendGradient(next, corner, 0);

        if (rafId) cancelAnimationFrame(rafId);

        function frame(now) {
            if (!running) return;
            var t = Math.min(1, (now - startTime) / duration);
            var eased = easeInOut(t);
            var r = maxR * eased;
            waveEl.style.background = softBlendGradient(next, corner, r);

            if (t < 1) {
                rafId = requestAnimationFrame(frame);
            } else {
                currentColor = next;
                setSolid(baseEl, currentColor);
                try { document.body.style.background = currentColor; } catch (e) {}
                waveEl.style.background = "transparent";

                var pause = 2200 + Math.floor(Math.random() * 2800);
                clearTimeout(timer);
                timer = setTimeout(runCycle, pause);
            }
        }

        rafId = requestAnimationFrame(frame);
    }

    function start() {
        if (running) return;
        if (!ensureEls()) {
            setTimeout(start, 200);
            return;
        }
        running = true;
        currentColor = pickColor(null);
        setSolid(baseEl, currentColor);
        try { document.body.style.background = currentColor; } catch (e) {}
        waveEl.style.background = "transparent";
        waveEl.style.inset = "0";
        waveEl.style.width = "100%";
        waveEl.style.height = "100%";
        waveEl.style.transform = "none";
        timer = setTimeout(runCycle, 900);
    }

    function stop() {
        running = false;
        clearTimeout(timer);
        if (rafId) cancelAnimationFrame(rafId);
    }

    window.startAzoraEdgeColorWipe = start;
    window.stopAzoraEdgeColorWipe = stop;

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", start);
    } else {
        start();
    }
})();

/* ===== Player Ads: free text / 5-coin picture / 35-coin spotlight ===== */
(function () {
    var DAY = 24 * 60 * 60 * 1000;
    var AD_TIERS = {
        text: { id: "text", name: "Text Ad", price: 0, maxImages: 0, durationMs: 1 * DAY, label: "Free text" },
        picture: { id: "picture", name: "Picture Ad", price: 5, maxImages: 1, durationMs: 3 * DAY, label: "Picture" },
        spotlight: { id: "spotlight", name: "Spotlight Ad", price: 35, maxImages: 3, durationMs: 7 * DAY, label: "Spotlight" }
    };
    var selectedTier = "text";
    var pendingImages = [];
    var pendingAd = null;
    var boardFilter = "all";
    var cloudPullAt = 0;

    function officialAds() {
        return [
            {
                id: "official_welcome",
                tier: "text",
                title: "Welcome to Azora!",
                body: "Play games, customize your avatar, and make friends. Family-friendly fun starts here.",
                author: "Azora",
                official: true,
                createdAt: 1,
                expiresAt: 0
            },
            {
                id: "official_roleplay",
                tier: "spotlight",
                title: "Azora Roleplay is live",
                tagline: "Hang out in 3D",
                body: "Join the official multiplayer world. Explore the city, chat, and meet other players.",
                author: "Azora",
                official: true,
                gameId: "azora-roleplay",
                images: [],
                createdAt: 2,
                expiresAt: 0
            }
        ];
    }

    function loadLocalAds() {
        try {
            var list = JSON.parse(localStorage.getItem("azoraAds") || "[]");
            return Array.isArray(list) ? list : [];
        } catch (e) { return []; }
    }

    function saveLocalAds(list) {
        try { localStorage.setItem("azoraAds", JSON.stringify(list || [])); } catch (e) {}
    }

    function isExpired(ad, now) {
        if (!ad) return true;
        if (ad.official && !ad.expiresAt) return false;
        if (!ad.expiresAt) return false;
        return now >= ad.expiresAt;
    }

    function mergeAds(localList, cloudMap) {
        var byId = {};
        officialAds().forEach(function (a) { byId[a.id] = a; });
        (localList || []).forEach(function (a) { if (a && a.id) byId[a.id] = a; });
        if (cloudMap && typeof cloudMap === "object") {
            Object.keys(cloudMap).forEach(function (k) {
                var a = cloudMap[k];
                if (a && a.id) byId[a.id] = a;
            });
        }
        var now = Date.now();
        return Object.keys(byId).map(function (k) { return byId[k]; }).filter(function (a) {
            return !isExpired(a, now);
        });
    }

    function getAds() {
        return mergeAds(loadLocalAds(), window._azoraCloudAds || null);
    }

    function currentUsername() {
        try {
            var acc = typeof getActiveAccount === "function" ? getActiveAccount() : null;
            if (acc && acc.username) return String(acc.username);
        } catch (e) {}
        return "";
    }

    function isGuestUser() {
        try {
            var acc = typeof getActiveAccount === "function" ? getActiveAccount() : null;
            if (acc && acc.isGuest) return true;
            if (localStorage.getItem("loggedIn") === "guest") return true;
        } catch (e) {}
        return false;
    }

    function canCreateAds() {
        if (localStorage.getItem("loggedIn") !== "true") return false;
        if (isGuestUser()) return false;
        return !!currentUsername();
    }

    function showAdError(msg) {
        var el = document.getElementById("adFormError");
        if (!el) return;
        if (!msg) { el.style.display = "none"; el.textContent = ""; return; }
        el.style.display = "block";
        el.textContent = msg;
    }

    function setAdBalanceLabel() {
        var el = document.getElementById("adCreateBalance");
        if (el && typeof getCoins === "function" && typeof formatCoins === "function") {
            el.textContent = formatCoins(getCoins());
        }
    }

    function fillAdGameSelect() {
        var sel = document.getElementById("adGameSelect");
        if (!sel) return;
        var html = '<option value="">No game button</option>';
        try {
            if (typeof NORM_GAMES === "object" && NORM_GAMES) {
                Object.keys(NORM_GAMES).forEach(function (id) {
                    var g = NORM_GAMES[id];
                    if (!g) return;
                    html += '<option value="' + escapeHtml(id) + '">' + escapeHtml(g.title || id) + "</option>";
                });
            }
        } catch (e) {}
        sel.innerHTML = html;
    }

    function selectAdTier(id) {
        if (!AD_TIERS[id]) id = "text";
        selectedTier = id;
        var cards = document.querySelectorAll(".azora-ad-tier-card");
        for (var i = 0; i < cards.length; i++) {
            cards[i].classList.toggle("selected", cards[i].getAttribute("data-ad-tier") === id);
        }
        var tier = AD_TIERS[id];
        var imgWrap = document.getElementById("adImagesWrap");
        var tagWrap = document.getElementById("adTaglineWrap");
        var gameWrap = document.getElementById("adGameWrap");
        var hint = document.getElementById("adImageHint");
        if (imgWrap) imgWrap.style.display = tier.maxImages > 0 ? "block" : "none";
        if (tagWrap) tagWrap.style.display = id === "spotlight" ? "block" : "none";
        if (gameWrap) gameWrap.style.display = id === "spotlight" ? "block" : "none";
        if (hint) {
            hint.textContent = tier.maxImages === 1 ? "(1 picture)" : ("(up to " + tier.maxImages + " pictures)");
        }
        if (tier.maxImages === 0) {
            pendingImages = [];
            renderAdPreviews();
        } else if (pendingImages.length > tier.maxImages) {
            pendingImages = pendingImages.slice(0, tier.maxImages);
            renderAdPreviews();
        }
        showAdError("");
    }

    function renderAdPreviews() {
        var box = document.getElementById("adImagePreviews");
        if (!box) return;
        box.innerHTML = pendingImages.map(function (src) {
            return '<img src="' + src + '" alt="Ad preview">';
        }).join("");
    }

    function compressAdImage(file, maxSide, cb) {
        var reader = new FileReader();
        reader.onload = function () {
            var img = new Image();
            img.onload = function () {
                var w = img.width || 1, h = img.height || 1;
                var scale = Math.min(1, maxSide / Math.max(w, h));
                var c = document.createElement("canvas");
                c.width = Math.max(1, Math.round(w * scale));
                c.height = Math.max(1, Math.round(h * scale));
                var ctx = c.getContext("2d");
                ctx.fillStyle = "#0f172a";
                ctx.fillRect(0, 0, c.width, c.height);
                ctx.drawImage(img, 0, 0, c.width, c.height);
                cb(c.toDataURL("image/jpeg", 0.72));
            };
            img.onerror = function () { cb(""); };
            img.src = String(reader.result || "");
        };
        reader.onerror = function () { cb(""); };
        reader.readAsDataURL(file);
    }

    function onAdFilesChosen(input) {
        var files = input && input.files ? Array.prototype.slice.call(input.files) : [];
        var tier = AD_TIERS[selectedTier] || AD_TIERS.text;
        if (tier.maxImages <= 0) {
            showAdError("Text ads cannot include images. Pick Picture or Spotlight.");
            if (input) input.value = "";
            return;
        }
        files = files.filter(function (f) { return f && /^image\//.test(f.type); });
        if (!files.length) {
            showAdError("Please choose an image file.");
            return;
        }
        var room = Math.max(0, tier.maxImages - pendingImages.length);
        if (room <= 0) {
            showAdError("This ad type only allows " + tier.maxImages + " image" + (tier.maxImages === 1 ? "" : "s") + ".");
            if (input) input.value = "";
            return;
        }
        files = files.slice(0, room);
        var left = files.length;
        files.forEach(function (file) {
            if (file.size > 2.5 * 1024 * 1024) {
                showAdError("One image is too large. Please use images under 2.5 MB.");
                left -= 1;
                if (left <= 0) renderAdPreviews();
                return;
            }
            compressAdImage(file, selectedTier === "spotlight" ? 480 : 360, function (dataUrl) {
                if (dataUrl) pendingImages.push(dataUrl);
                left -= 1;
                if (left <= 0) renderAdPreviews();
            });
        });
        if (input) input.value = "";
    }

    function moderateAdText(text, label) {
        text = String(text || "").trim();
        if (!text) return { ok: false, reason: "Please add a " + label + "." };
        if (typeof azoraAutoModerate === "function") {
            var mod = azoraAutoModerate(text);
            if (mod && mod.ok === false) return { ok: false, reason: mod.reason || "That text is not allowed." };
        }
        var lower = text.toLowerCase().replace(/\s+/g, "");
        if (text.indexOf("@") >= 0 || /\b(gmail|yahoo|outlook|hotmail|\.com|\.net|\.org|\.edu)\b/i.test(lower)) {
            return { ok: false, reason: "Ads cannot include emails or website addresses." };
        }
        return { ok: true, text: text };
    }

    function openCreateAd() {
        if (!canCreateAds()) {
            alert("Create an account or log in to post an ad. Guests can look at ads, but cannot publish them.");
            if (typeof openCreateAccount === "function") openCreateAccount();
            return;
        }
        var ov = document.getElementById("createAdOverlay");
        if (!ov) return;
        pendingImages = [];
        pendingAd = null;
        var title = document.getElementById("adTitleInput");
        var body = document.getElementById("adBodyInput");
        var tag = document.getElementById("adTaglineInput");
        var file = document.getElementById("adFileInput");
        if (title) title.value = "";
        if (body) body.value = "";
        if (tag) tag.value = "";
        if (file) file.value = "";
        var count = document.getElementById("adBodyCount");
        if (count) count.textContent = "0";
        fillAdGameSelect();
        selectAdTier("text");
        setAdBalanceLabel();
        showAdError("");
        renderAdPreviews();
        ov.style.display = "flex";
    }

    function closeCreateAd() {
        var ov = document.getElementById("createAdOverlay");
        if (ov) ov.style.display = "none";
        pendingAd = null;
    }

    function openAdsBoard() {
        var board = document.getElementById("azoraAdsBoard");
        if (board && board.scrollIntoView) board.scrollIntoView({ behavior: "smooth", block: "start" });
        renderAdsBoard();
        pullCloudAds();
    }

    function setAdsBoardFilter(id) {
        boardFilter = id || "all";
        ["all", "text", "picture", "spotlight", "mine"].forEach(function (key) {
            var map = { all: "adsTabAll", text: "adsTabText", picture: "adsTabPicture", spotlight: "adsTabSpotlight", mine: "adsTabMine" };
            var el = document.getElementById(map[key]);
            if (el) el.classList.toggle("active", key === boardFilter);
        });
        renderAdsBoard();
    }

    function remainingLabel(ad) {
        if (ad.official && !ad.expiresAt) return "Always on";
        var ms = (ad.expiresAt || 0) - Date.now();
        if (ms <= 0) return "Ending soon";
        var h = Math.ceil(ms / (60 * 60 * 1000));
        if (h < 24) return h + " hour" + (h === 1 ? "" : "s") + " left";
        var d = Math.ceil(h / 24);
        return d + " day" + (d === 1 ? "" : "s") + " left";
    }

    function renderAdsBoard() {
        var listEl = document.getElementById("azoraAdsList");
        if (!listEl) return;
        var me = currentUsername().toLowerCase();
        var ads = getAds().sort(function (a, b) {
            var rank = { spotlight: 3, picture: 2, text: 1 };
            var ra = (a.official ? 4 : 0) + (rank[a.tier] || 0);
            var rb = (b.official ? 4 : 0) + (rank[b.tier] || 0);
            if (rb !== ra) return rb - ra;
            return (b.createdAt || 0) - (a.createdAt || 0);
        });
        if (boardFilter === "mine") {
            ads = ads.filter(function (a) { return String(a.author || "").toLowerCase() === me; });
        } else if (boardFilter !== "all") {
            ads = ads.filter(function (a) { return a.tier === boardFilter; });
        }
        if (!ads.length) {
            listEl.innerHTML = '<div class="azora-ads-empty">No ads yet! Be the first to post one — text ads are free.</div>';
            return;
        }
        listEl.innerHTML = ads.map(function (ad) {
            var tier = AD_TIERS[ad.tier] || AD_TIERS.text;
            var mine = me && String(ad.author || "").toLowerCase() === me && !ad.official;
            var imgs = (ad.images || []).slice(0, tier.maxImages).map(function (src) {
                return '<img src="' + src + '" alt="">';
            }).join("");
            var gameBtn = "";
            if (ad.tier === "spotlight" && ad.gameId) {
                var gTitle = ad.gameId;
                try { if (NORM_GAMES && NORM_GAMES[ad.gameId]) gTitle = NORM_GAMES[ad.gameId].title || ad.gameId; } catch (e) {}
                gameBtn = '<button type="button" class="azora-ad-game-btn" onclick="joinAdGame(\'' + escapeHtml(ad.gameId) + '\')">Play ' + escapeHtml(gTitle) + "</button>";
            }
            var del = mine
                ? '<button type="button" class="azora-ad-delete" title="Remove my ad" onclick="deleteMyAd(\'' + escapeHtml(ad.id) + '\')">✕</button>'
                : "";
            return '<article class="azora-ad-card ' + escapeHtml(ad.tier) + '">' +
                del +
                '<span class="azora-ad-badge">' + escapeHtml(tier.label) + (ad.official ? " · Official" : "") + "</span>" +
                "<h3>" + escapeHtml(ad.title || "Ad") + "</h3>" +
                (ad.tagline ? '<p class="azora-ad-tagline">' + escapeHtml(ad.tagline) + "</p>" : "") +
                '<p class="azora-ad-body">' + escapeHtml(ad.body || "") + "</p>" +
                (imgs ? '<div class="azora-ad-images">' + imgs + "</div>" : "") +
                gameBtn +
                '<div class="azora-ad-meta">By ' + escapeHtml(ad.author || "Player") + " · " + remainingLabel(ad) + "</div>" +
                "</article>";
        }).join("");
    }

    function joinAdGame(id) {
        if (typeof joinNormGame === "function") joinNormGame(id);
    }

    function pushAdToCloud(ad) {
        if (!ad || !ad.id) return;
        try {
            if (typeof isCloudSocialReady === "function" && isCloudSocialReady() && typeof cloudPutJson === "function" && typeof cloudBase === "function") {
                cloudPutJson(cloudBase() + "/azoraAds/" + encodeURIComponent(ad.id) + ".json", ad).catch(function () {});
            }
        } catch (e) {}
    }

    function deleteAdFromCloud(id) {
        try {
            if (typeof isCloudSocialReady === "function" && isCloudSocialReady() && typeof cloudDeleteJson === "function" && typeof cloudBase === "function") {
                cloudDeleteJson(cloudBase() + "/azoraAds/" + encodeURIComponent(id) + ".json").catch(function () {});
            }
        } catch (e) {}
    }

    function pullCloudAds() {
        var now = Date.now();
        if (now - cloudPullAt < 8000) return;
        cloudPullAt = now;
        try {
            if (!(typeof isCloudSocialReady === "function" && isCloudSocialReady() && typeof cloudFetchJson === "function" && typeof cloudBase === "function")) return;
            cloudFetchJson(cloudBase() + "/azoraAds.json").then(function (data) {
                window._azoraCloudAds = data && typeof data === "object" ? data : {};
                renderAdsBoard();
            }).catch(function () {});
        } catch (e) {}
    }

    function submitCreateAd() {
        showAdError("");
        if (!canCreateAds()) {
            showAdError("Log in with an account to publish an ad.");
            return;
        }
        var tier = AD_TIERS[selectedTier] || AD_TIERS.text;
        var titleMod = moderateAdText((document.getElementById("adTitleInput") || {}).value, "title");
        if (!titleMod.ok) { showAdError(titleMod.reason); return; }
        var bodyMod = moderateAdText((document.getElementById("adBodyInput") || {}).value, "message");
        if (!bodyMod.ok) { showAdError(bodyMod.reason); return; }
        var tagline = "";
        if (tier.id === "spotlight") {
            var rawTag = String((document.getElementById("adTaglineInput") || {}).value || "").trim();
            if (rawTag) {
                var tagMod = moderateAdText(rawTag, "tagline");
                if (!tagMod.ok) { showAdError(tagMod.reason); return; }
                tagline = tagMod.text;
            }
        }
        if (tier.maxImages > 0 && pendingImages.length < 1) {
            showAdError("Please add " + (tier.maxImages === 1 ? "a picture" : "at least one picture") + " for this ad.");
            return;
        }
        if (pendingImages.length > tier.maxImages) {
            showAdError("Too many pictures for this category.");
            return;
        }
        var gameId = "";
        if (tier.id === "spotlight") {
            gameId = String((document.getElementById("adGameSelect") || {}).value || "");
        }
        var price = tier.price;
        if (price > 0 && typeof getCoins === "function" && getCoins() + 1e-9 < price) {
            showAdError("Not enough AzoraCoins. This ad costs " + (typeof formatCoins === "function" ? formatCoins(price) : price) + " 🪙");
            return;
        }
        pendingAd = {
            id: "ad_" + Date.now() + "_" + Math.random().toString(36).slice(2, 7),
            tier: tier.id,
            title: titleMod.text,
            body: bodyMod.text,
            tagline: tagline,
            images: pendingImages.slice(),
            gameId: gameId,
            author: currentUsername(),
            official: false,
            createdAt: Date.now(),
            expiresAt: Date.now() + tier.durationMs,
            pricePaid: price
        };
        var cov = document.getElementById("adConfirmOverlay");
        var txt = document.getElementById("adConfirmText");
        if (txt) {
            txt.textContent = price <= 0
                ? "Publish this free text ad? It will stay on the board for 1 day."
                : ("Publish this " + tier.name + " for " + (typeof formatCoins === "function" ? formatCoins(price) : price) + " AzoraCoins?");
        }
        if (cov) cov.style.display = "flex";
    }

    function confirmPublishAd(yes) {
        var cov = document.getElementById("adConfirmOverlay");
        if (cov) cov.style.display = "none";
        if (!yes) { pendingAd = null; return; }
        if (!pendingAd) return;
        var ad = pendingAd;
        pendingAd = null;
        if (ad.pricePaid > 0) {
            if (typeof spendCoins !== "function" || !spendCoins(ad.pricePaid)) {
                showAdError("Transaction failed. You do not have enough AzoraCoins.");
                return;
            }
        }
        var list = loadLocalAds();
        list.unshift(ad);
        list = list.slice(0, 80);
        saveLocalAds(list);
        pushAdToCloud(ad);
        closeCreateAd();
        boardFilter = "all";
        setAdsBoardFilter("all");
        if (typeof showAzoraToast === "function") {
            showAzoraToast(ad.pricePaid > 0
                ? ("Ad published! Spent " + (typeof formatCoins === "function" ? formatCoins(ad.pricePaid) : ad.pricePaid) + " 🪙")
                : "Free text ad published!");
        }
        var board = document.getElementById("azoraAdsBoard");
        if (board && board.scrollIntoView) board.scrollIntoView({ behavior: "smooth", block: "start" });
    }

    function deleteMyAd(id) {
        var me = currentUsername().toLowerCase();
        var list = loadLocalAds().filter(function (a) {
            if (!a || a.id !== id) return true;
            if (String(a.author || "").toLowerCase() !== me) return true;
            return false;
        });
        saveLocalAds(list);
        try {
            if (window._azoraCloudAds && window._azoraCloudAds[id]) delete window._azoraCloudAds[id];
        } catch (e) {}
        deleteAdFromCloud(id);
        renderAdsBoard();
        if (typeof showAzoraToast === "function") showAzoraToast("Ad removed.");
    }

    function bindAdForm() {
        var body = document.getElementById("adBodyInput");
        if (body && !body._azoraBound) {
            body._azoraBound = true;
            body.addEventListener("input", function () {
                var c = document.getElementById("adBodyCount");
                if (c) c.textContent = String((body.value || "").length);
            });
        }
        renderAdsBoard();
        pullCloudAds();
    }

    window.openCreateAd = openCreateAd;
    window.closeCreateAd = closeCreateAd;
    window.openAdsBoard = openAdsBoard;
    window.selectAdTier = selectAdTier;
    window.onAdFilesChosen = onAdFilesChosen;
    window.submitCreateAd = submitCreateAd;
    window.confirmPublishAd = confirmPublishAd;
    window.setAdsBoardFilter = setAdsBoardFilter;
    window.deleteMyAd = deleteMyAd;
    window.joinAdGame = joinAdGame;
    window.renderAdsBoard = renderAdsBoard;

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", function () { setTimeout(bindAdForm, 400); });
    } else {
        setTimeout(bindAdForm, 400);
    }
})();


// ============================================================
// Chat Voice Box (CVB) + 10-second teaching moderation scan
// ============================================================
// Hidden blocked-word line (not shown in the UI — the scanner reads this):
var AZORA_HIDDEN_BLOCK_LINE = "kys|kill yourself|nigger|faggot|fuck|shit|bitch|asshole|porn|onlyfans|sexchat|nude|naked|suicide|die already|hate you|shut up idiot";

var _cvbScanTimer = null;
var _cvbScanHintTimer = null;
var _cvbChatPollTimer = null;
var _cvbFixIndex = 0;
var _cvbLastHits = [];

function getNormCvbSettings() {
    var s = { enabled: true, voice: "light" };
    try {
        var raw = JSON.parse(localStorage.getItem("azoraCvbSettings") || "null");
        if (raw && typeof raw === "object") {
            s.enabled = raw.enabled !== false;
            s.voice = (raw.voice === "dark") ? "dark" : "light";
        }
    } catch (e) {}
    return s;
}

function saveNormCvbSettings() {
    var en = document.getElementById("cvbEnabledToggle");
    var vt = document.getElementById("cvbVoiceType");
    var s = {
        enabled: en ? !!en.checked : true,
        voice: (vt && vt.value === "dark") ? "dark" : "light"
    };
    try { localStorage.setItem("azoraCvbSettings", JSON.stringify(s)); } catch (e) {}
    return s;
}

function loadNormCvbSettingsIntoUi() {
    var s = getNormCvbSettings();
    var en = document.getElementById("cvbEnabledToggle");
    var vt = document.getElementById("cvbVoiceType");
    if (en) en.checked = s.enabled;
    if (vt) vt.value = s.voice;
}

function toggleNormGameSettings(ev) {
    if (ev && ev.stopPropagation) ev.stopPropagation();
    var pan = document.getElementById("normGameSettingsPanel");
    if (!pan) return;
    var open = pan.style.display === "none" || !pan.style.display;
    pan.style.display = open ? "block" : "none";
    if (open) loadNormCvbSettingsIntoUi();
}

function testNormCvbVoice() {
    saveNormCvbSettings();
    playCvbSpeech("Hello! This is my Chat Voice Box.", _normLocalMesh, true);
}

function setNormChatRowState(state) {
    var row = document.getElementById("normChatInputRow");
    if (!row) return;
    row.classList.remove("cvb-scan", "cvb-bad", "cvb-ok");
    if (state) row.classList.add(state);
}

function setNormChatScanning(on) {
    var input = document.getElementById("normChatInput");
    var btn = document.getElementById("normChatSendBtn");
    var hint = document.getElementById("normChatScanHint");
    if (input) {
        input.dataset.cvbScanning = on ? "1" : "0";
        input.disabled = !!on;
        if (on) input.placeholder = "Looking through the code for blocked words...";
        else if (!input.placeholder || /Looking through|Checking this|Almost done/.test(input.placeholder)) {
            input.placeholder = "Say something…";
        }
    }
    if (btn) {
        btn.disabled = !!on;
        btn.textContent = on ? "Scanning…" : "Send";
    }
    if (hint) {
        hint.style.display = on ? "block" : "none";
        if (on) hint.textContent = "Looking through the code for blocked words...";
    }
    if (_cvbScanHintTimer) {
        clearInterval(_cvbScanHintTimer);
        _cvbScanHintTimer = null;
    }
    if (on) {
        var lines = [
            "Looking through the code for blocked words...",
            "Checking this message against Azora's hidden word list...",
            "Almost done scanning..."
        ];
        var i = 0;
        _cvbScanHintTimer = setInterval(function () {
            i = (i + 1) % lines.length;
            if (input && input.dataset.cvbScanning === "1") input.placeholder = lines[i];
            if (hint) hint.textContent = lines[i];
        }, 2800);
    }
}

function normalizeCvbToken(w) {
    return String(w || "")
        .toLowerCase()
        .replace(/[^a-z0-9]/g, "")
        .replace(/0/g, "o")
        .replace(/1/g, "i")
        .replace(/3/g, "e")
        .replace(/4/g, "a")
        .replace(/5/g, "s")
        .replace(/7/g, "t")
        .replace(/\$/g, "s");
}

function scanAzoraChatMessage(text) {
    text = String(text || "");
    var hits = [];
    var tokens = String(AZORA_HIDDEN_BLOCK_LINE || "").split("|");
    var tokenSet = {};
    tokens.forEach(function (t) {
        var n = normalizeCvbToken(t);
        if (n) tokenSet[n] = t;
    });
    var re = /[A-Za-z0-9'@]+/g;
    var m;
    while ((m = re.exec(text))) {
        var raw = m[0];
        var norm = normalizeCvbToken(raw);
        if (!norm) continue;
        if (tokenSet[norm]) {
            hits.push({ word: raw, start: m.index, end: m.index + raw.length });
        }
    }
    // Phrase checks
    var phrases = [
        /kill\s*yourself/i,
        /die\s*already/i,
        /hate\s*you/i,
        /shut\s*up/i
    ];
    phrases.forEach(function (rx) {
        var pm = rx.exec(text);
        if (pm) {
            var already = hits.some(function (h) { return h.start === pm.index; });
            if (!already) hits.push({ word: pm[0], start: pm.index, end: pm.index + pm[0].length });
        }
    });
    hits.sort(function (a, b) { return a.start - b.start; });
    return { ok: hits.length === 0, hits: hits, count: hits.length };
}

function showNormChatReview(text, hits) {
    var box = document.getElementById("normChatReview");
    if (!box) return;
    _cvbLastHits = hits || [];
    _cvbFixIndex = 0;
    if (!_cvbLastHits.length) {
        box.style.display = "none";
        box.innerHTML = "";
        return;
    }
    var pieces = [];
    var cursor = 0;
    _cvbLastHits.forEach(function (h, idx) {
        if (h.start > cursor) pieces.push(escapeCvbHtml(text.slice(cursor, h.start)));
        pieces.push('<button type="button" class="cvb-bad-word' + (idx === 0 ? " active" : "") + '" data-cvb-i="' + idx + '" onclick="focusCvbBadWord(' + idx + ')">' + escapeCvbHtml(h.word) + "</button>");
        cursor = h.end;
    });
    if (cursor < text.length) pieces.push(escapeCvbHtml(text.slice(cursor)));
    var n = _cvbLastHits.length;
    box.innerHTML =
        '<span class="cvb-count">Found ' + n + ' word' + (n === 1 ? "" : "s") + " that don't follow the rules.</span>" +
        "<div>" + pieces.join("") + "</div>" +
        '<div class="cvb-guide">No punishment — just fix them. Word 1 of ' + n +
        ': change “' + escapeCvbHtml(_cvbLastHits[0].word) + '”, then Send again.</div>';
    box.style.display = "block";
}

function escapeCvbHtml(s) {
    return String(s || "").replace(/&/g, "&").replace(/</g, "<").replace(/>/g, ">");
}

function focusCvbBadWord(idx) {
    var input = document.getElementById("normChatInput");
    var hits = _cvbLastHits || [];
    if (!input || !hits[idx]) return;
    _cvbFixIndex = idx;
    try {
        input.focus();
        input.setSelectionRange(hits[idx].start, hits[idx].end);
    } catch (e) {}
    var box = document.getElementById("normChatReview");
    if (box) {
        var btns = box.querySelectorAll(".cvb-bad-word");
        for (var i = 0; i < btns.length; i++) {
            if (Number(btns[i].getAttribute("data-cvb-i")) === idx) btns[i].classList.add("active");
            else btns[i].classList.remove("active");
        }
        var g = box.querySelector(".cvb-guide");
        if (g) {
            g.textContent = "Fix word " + (idx + 1) + " of " + hits.length +
                ': change “' + hits[idx].word + '”, then Send again.';
        }
    }
}

function beginNormChatScan(msg) {
    var input = document.getElementById("normChatInput");
    var review = document.getElementById("normChatReview");
    if (review) review.style.display = "none";
    setNormChatRowState("cvb-scan");
    setNormChatScanning(true);
    if (_cvbScanTimer) clearTimeout(_cvbScanTimer);
    var wait = 9000 + Math.floor(Math.random() * 2500);
    _cvbScanTimer = setTimeout(function () {
        _cvbScanTimer = null;
        setNormChatScanning(false);
        var result = scanAzoraChatMessage(msg);
        if (!result.ok) {
            setNormChatRowState("cvb-bad");
            showNormChatReview(msg, result.hits);
            if (input) {
                input.value = msg;
                focusCvbBadWord(0);
            }
            return;
        }
        if (review) { review.style.display = "none"; review.innerHTML = ""; }
        setNormChatRowState("cvb-ok");
        setTimeout(function () { setNormChatRowState(""); }, 2800);
        finishSendNormChat(msg, false);
    }, wait);
}

function finishSendNormChat(msg, isCmd) {
    var input = document.getElementById("normChatInput");
    var name = (typeof getNormDisplayName === "function") ? getNormDisplayName() : "Player";
    var cmd = String(msg || "").trim().toLowerCase();

    if (cmd === "/c hi" || cmd === "/chi" || cmd === "/hi") {
        if (input) input.value = "";
        appendNormChat(name, "👋 (waved hello)");
        try {
            if (typeof playAvatarWave === "function" && _normLocalMesh) playAvatarWave(_normLocalMesh, 1100);
        } catch (eW) {}
        broadcastNormChat(name, "👋 (waved hello)", { cmd: "wave" });
        return;
    }
    if (cmd === "/c follow" || cmd === "/cfollow") {
        if (input) input.value = "";
        if (!_aturiusInGame) {
            appendNormChat("System", "Aturius isn't in this game yet. Wait for the join reminder, or turn joins on in Aturius Settings.", true);
            return;
        }
        _aturiusFollow = true;
        _aturiusExploreTarget = null;
        appendNormChat("Aturius", "Following you now! I'll stick close.", true);
        return;
    }
    if (cmd === "/c unfollow" || cmd === "/cunfollow") {
        if (input) input.value = "";
        if (!_aturiusInGame) {
            appendNormChat("System", "Aturius isn't in this game yet.", true);
            return;
        }
        _aturiusFollow = false;
        _aturiusExploreTarget = null;
        appendNormChat("Aturius", "Okay — I'll explore nearby. I won't go farther than about " + ATURIUS_MAX_DISTANCE + " units from you.", true);
        return;
    }

    appendNormChat(name, msg);
    if (input) input.value = "";
    var voice = getNormCvbSettings().voice;
    var stamp = Date.now();
    broadcastNormChat(name, msg, { cvb: true, voice: voice, fromId: _normMyPresenceId, at: stamp });
    if (_normSession) {
        _normSession._seenChatKeys = _normSession._seenChatKeys || {};
        _normSession._seenChatKeys[name + "|" + msg + "|" + stamp] = true;
        _normSession._seenChatKeys[name + "|" + msg] = true;
    }
    setTimeout(function () {
        playCvbSpeech(msg, _normLocalMesh, true);
    }, 2000);
}

function broadcastNormChat(name, text, extra) {
    extra = extra || {};
    try {
        if (_normSession && typeof AZORA_CLOUD !== "undefined" && AZORA_CLOUD.isReady && AZORA_CLOUD.isReady()) {
            var base = (AZORA_CLOUD.firebaseUrl || "").replace(/\/$/, "");
            var chatUrl = base + "/azoraNormRooms/" + _normSession.id + "/chat.json";
            var body = {
                user: name,
                text: text,
                at: extra.at || Date.now(),
                cvb: extra.cvb !== false,
                voice: extra.voice || getNormCvbSettings().voice,
                fromId: extra.fromId || _normMyPresenceId || "",
                cmd: extra.cmd || ""
            };
            fetch(chatUrl, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(body)
            }).catch(function () {});
        }
    } catch (e) {}
}

function findNormMeshByName(name) {
    if (!name) return null;
    if (typeof getNormDisplayName === "function" && String(getNormDisplayName()) === String(name)) {
        return _normLocalMesh;
    }
    if (!_normRemoteMeshes || !_normPlayers) return null;
    for (var i = 0; i < _normPlayers.length; i++) {
        var p = _normPlayers[i];
        if (p && !p.isMe && String(p.name) === String(name) && _normRemoteMeshes[p.id]) {
            return _normRemoteMeshes[p.id];
        }
    }
    return null;
}

function cvbDistanceVolume(fromMesh) {
    if (!fromMesh || !_normLocalMesh) return 1;
    if (fromMesh === _normLocalMesh) return 1;
    var dx = fromMesh.position.x - _normLocalMesh.position.x;
    var dy = (fromMesh.position.y || 0) - (_normLocalMesh.position.y || 0);
    var dz = fromMesh.position.z - _normLocalMesh.position.z;
    var dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
    var maxD = 32;
    if (dist >= maxD) return 0;
    return Math.max(0, 1 - dist / maxD);
}

function pulseCvbBox(mesh, ms) {
    if (!mesh) return;
    var box = mesh.userData && mesh.userData.cvbVoiceBox;
    if (!box) {
        try { box = mesh.getObjectByName("cvbVoiceBox"); } catch (e) {}
    }
    if (!box) return;
    box.userData = box.userData || {};
    box.userData.cvbPulseUntil = Date.now() + (ms || 1800);
}

function tickCvbVoiceBoxes() {
    function pulseOne(mesh) {
        if (!mesh) return;
        var box = (mesh.userData && mesh.userData.cvbVoiceBox) || (mesh.getObjectByName && mesh.getObjectByName("cvbVoiceBox"));
        if (!box) return;
        var until = box.userData && box.userData.cvbPulseUntil;
        if (until && Date.now() < until) {
            var t = Date.now() / 90;
            var s = 1 + Math.sin(t) * 0.35;
            box.scale.set(s, s, s);
            try {
                if (box.material && box.material.emissive) {
                    box.material.emissive.setHex(0x94a3b8);
                    box.material.emissiveIntensity = 0.6;
                } else if (box.material && box.material.color) {
                    box.material.color.setHex(0x9ca3af);
                }
            } catch (e) {}
        } else {
            box.scale.set(1, 1, 1);
        }
    }
    pulseOne(_normLocalMesh);
    if (_normRemoteMeshes) {
        Object.keys(_normRemoteMeshes).forEach(function (k) { pulseOne(_normRemoteMeshes[k]); });
    }
}

function playCvbSpeech(text, sourceMesh, isLocal, voiceOverride) {
    var s = getNormCvbSettings();
    if (!s.enabled) return;
    text = String(text || "").replace(/👋/g, "hello").trim();
    if (!text) return;
    var vol = isLocal ? 1 : cvbDistanceVolume(sourceMesh);
    if (vol <= 0.02) return;
    pulseCvbBox(sourceMesh || _normLocalMesh, Math.min(8000, 600 + text.length * 70));
    var voiceKind = (voiceOverride === "dark" || voiceOverride === "light") ? voiceOverride : s.voice;
    try { playCvbSpatialFromMesh(sourceMesh || _normLocalMesh, voiceKind, vol, Math.min(4000, 700 + text.length * 40)); } catch (eSp) {}
    try {
        if (!window.speechSynthesis) return;
        window.speechSynthesis.cancel();
        var u = new SpeechSynthesisUtterance(text);
        u.volume = Math.max(0.12, Math.min(1, vol));
        if (voiceKind === "dark") {
            u.pitch = 0.62;
            u.rate = 0.9;
        } else {
            u.pitch = 1.42;
            u.rate = 1.06;
        }
        try {
            var voices = window.speechSynthesis.getVoices() || [];
            var pick = null;
            for (var i = 0; i < voices.length; i++) {
                var n = (voices[i].name || "").toLowerCase();
                if (voiceKind === "dark" && /male|david|daniel|fred|alex/.test(n)) { pick = voices[i]; break; }
                if (voiceKind === "light" && /female|samantha|karen|zira|victoria/.test(n)) { pick = voices[i]; break; }
            }
            if (pick) u.voice = pick;
        } catch (eV) {}
        window.speechSynthesis.speak(u);
    } catch (e) {}
}

var _normAudioListener = null;
function ensureNormAudioListener() {
    if (typeof THREE === "undefined" || !_normCamera) return null;
    try {
        if (!_normAudioListener) {
            _normAudioListener = new THREE.AudioListener();
            _normCamera.add(_normAudioListener);
        }
        if (_normAudioListener.context && _normAudioListener.context.state === "suspended") {
            _normAudioListener.context.resume().catch(function () {});
        }
    } catch (e) { return null; }
    return _normAudioListener;
}

function playCvbSpatialFromMesh(mesh, voiceKind, vol, durMs) {
    var listener = ensureNormAudioListener();
    if (!listener || !mesh || typeof THREE === "undefined") return;
    var box = (mesh.userData && mesh.userData.cvbVoiceBox) || mesh.getObjectByName("cvbVoiceBox") || mesh;
    var ctx = listener.context;
    if (!ctx) return;
    var sound = new THREE.PositionalAudio(listener);
    sound.setRefDistance(8);
    sound.setRolloffFactor(1.6);
    sound.setDistanceModel("inverse");
    sound.setMaxDistance(32);
    sound.setVolume(Math.max(0.05, Math.min(0.45, vol * 0.4)));
    var osc = ctx.createOscillator();
    var gain = ctx.createGain();
    osc.type = "triangle";
    osc.frequency.value = voiceKind === "dark" ? 118 : 240;
    gain.gain.setValueAtTime(0.0001, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.12, ctx.currentTime + 0.05);
    gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + Math.max(0.2, (durMs || 800) / 1000));
    osc.connect(gain);
    try { sound.setNodeSource(gain); } catch (eN) {
        try { sound.setNodeSource(osc); } catch (eN2) {}
    }
    box.add(sound);
    try { osc.start(); } catch (eS) {}
    setTimeout(function () {
        try { osc.stop(); } catch (eSt) {}
        try { box.remove(sound); } catch (eRm) {}
    }, (durMs || 800) + 80);
}

function startNormChatPoll(def) {
    stopNormChatPoll();
    if (!_normSession) return;
    _normSession._seenChatKeys = _normSession._seenChatKeys || {};
    _cvbChatPollTimer = setInterval(function () {
        if (!_normSession || typeof AZORA_CLOUD === "undefined" || !AZORA_CLOUD.isReady || !AZORA_CLOUD.isReady()) return;
        var base = (AZORA_CLOUD.firebaseUrl || "").replace(/\/$/, "");
        var url = base + "/azoraNormRooms/" + _normSession.id + "/chat.json?ts=" + Date.now();
        fetch(url, { cache: "no-store" })
            .then(function (r) { return r.json(); })
            .then(function (data) {
                if (!data || typeof data !== "object") return;
                var me = (typeof getNormDisplayName === "function") ? getNormDisplayName() : "";
                Object.keys(data).forEach(function (k) {
                    var row = data[k];
                    if (!row || !row.text) return;
                    var key = String(row.user || "") + "|" + String(row.text) + "|" + String(row.at || k);
                    var loose = String(row.user || "") + "|" + String(row.text);
                    if (_normSession._seenChatKeys[key] || _normSession._seenChatKeys[loose]) return;
                    _normSession._seenChatKeys[key] = true;
                    if (row.fromId && row.fromId === _normMyPresenceId) return;
                    if (row.user && me && String(row.user) === String(me) && Date.now() - (row.at || 0) < 4000) return;
                    appendNormChat(row.user || "___", row.text, false);
                    if (row.cvb !== false && row.cmd !== "wave") {
                        var mesh = findNormMeshByName(row.user);
                        playCvbSpeech(row.text, mesh, false, row.voice);
                    }
                });
            })
            .catch(function () {});
    }, 1400);
}

function stopNormChatPoll() {
    if (_cvbChatPollTimer) {
        clearInterval(_cvbChatPollTimer);
        _cvbChatPollTimer = null;
    }
    if (window.speechSynthesis) {
        try { window.speechSynthesis.cancel(); } catch (e) {}
    }
}

